-- Migration V11: Seed Complete SRD Spells (Levels 0 through 9 for SRD_2014 and SRD_2024)
-- Automatically generated compendium seed with pt-BR localization

INSERT INTO player_character.spells (
    ruleset, slug, name_en, name, level, school, casting_time, range_area, components, duration, description, source
) VALUES
($$SRD_2014$$, $$acid-arrow-2014$$, $$Acid Arrow$$, $$Flecha Ácida$$, 2, $$Evocação$$, $$1 ação$$, $$27 metros$$, $$V, S, M (Powdered rhubarb leaf and an adder's stomach.)$$, $$Instantânea$$, $$Uma flecha com um rastro verde cintilante voa em direção ao alvo dentro do alcance e explode, borrifando ácido. Faça um ataque mágico à distância contra o alvo. Em caso de acerto, o alvo sofre 4d4 pontos de dano ácido imediatamente e 2d4 pontos de dano ácido ao final do próximo turno dele. Se errar, a flecha borrifa ácido no alvo causando metade do dano inicial e não causa dano ao final do próximo turno dele.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano (tanto o inicial quanto o final) aumenta em 1d4 para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$acid-splash-2014$$, $$Acid Splash$$, $$Acid Splash$$, 0, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$You create an acidic bubble at a point within range, where it explodes in a 5-foot-radius Sphere. Each creature in that Sphere must succeed on a Dexterity saving throw or take 1d6 Acid damage.   Aprimoramento de Truque.  The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).$$, $$SRD$$),
($$SRD_2014$$, $$aid-2014$$, $$Aid$$, $$Auxílio$$, 2, $$Abjuração$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A tiny strip of white cloth.)$$, $$8 horas$$, $$Esta magia reforça seus aliados com tenacidade e determinação. Escolha até três criaturas dentro do alcance. Os pontos de vida máximos e os pontos de vida atuais de cada alvo aumentam em 5 enquanto a magia durar.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, os pontos de vida do alvo aumentam em 5 pontos adicionais para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$alarm-2014$$, $$Alarm$$, $$Alarme$$, 1, $$Abjuração$$, $$1 minuto$$, $$9 metros$$, $$V, S, M (A tiny bell and a piece of fine silver wire.)$$, $$8 horas$$, $$Você prepara um alarme contra intrusos indesejados. Escolha uma porta, uma janela ou uma área dentro do alcance que não seja maior que um cubo de 6 metros de lado [20-foot cube]. Enquanto a magia durar, um alarme o alerta quando uma criatura Minúscula ou maior tocar ou entrar na área protegida. Ao conjurar a magia, você pode escolher quais criaturas não dispararão o alarme. Você também pode escolher se o alarme é mental ou audível.  Um alarme mental avisa com um sibilo em sua mente, se você estiver no alcance de 1,5 quilômetro [1 mile] da área protegida. Esse sibilo o desperta caso você esteja dormindo.  Um alarme audível produz o som de uma sineta durante 10 segundos, dentro de um alcance de 18 metros [60 ft.].$$, $$SRD$$),
($$SRD_2014$$, $$alter-self-2014$$, $$Alter Self$$, $$Alterar-se$$, 2, $$Transmutação$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Você assume uma forma diferente. Quando conjurar a magia, escolha uma das opções a seguir, cujos efeitos persistem enquanto a magia durar. Dentro desse período, você pode usar uma ação para finalizar uma das opções escolhidas, e obter os benefícios de outra.   Adaptação Aquática.  Você adapta seu corpo para o ambiente aquático, com guelras crescendo e membranas nascendo entre seus dedos. Você pode respirar debaixo d'água e ganha deslocamento de natação com valor igual ao seu deslocamento de caminhada.   Mudar Aparência.  Você transforma sua aparência conforme desejar, alterando sua altura, peso, características raciais, som da voz, comprimento do cabelo, cor da pele e características peculiares, se existirem. Você pode adquirir a aparência de outra raça, embora nenhuma de suas estatísticas mude. Você não pode parecer com uma criatura de tamanho diferente do seu, e sua forma básica permanece a mesma; por exemplo, se você é bípede, você não pode usar a magia para se tornar quadrúpede. A qualquer momento, enquanto a magia durar, você pode usar sua ação para trocar de aparência novamente.   Armas Naturais.  Crescem em seu corpo garras, presas, espinhos, chifres ou uma arma natural diferente, à sua escolha. Seu ataque desarmado causa 1d6 pontos de dano contundente, cortante ou perfurante, conforme a arma natural escolhida, e você é proficiente com seus ataques desarmados. Por fim, sua arma natural é mágica e você tem um bônus de +1 em suas jogadas de ataque e dano quando usá-la.$$, $$SRD$$),
($$SRD_2014$$, $$animal-friendship-2014$$, $$Animal Friendship$$, $$Amizade Animal$$, 1, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A morsel of food.)$$, $$24 horas$$, $$Escolha como alvo uma Fera à sua vista e no alcance da magia. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou tem a condição &Reference[charmed apply=false] pela duração da magia. Se você ou um de seus aliados causar dano ao alvo, a magia encerra.   Usando Espaços de Magia de Círculo Superior.  Você pode escolher uma criatura adicional para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$animal-messenger-2014$$, $$Animal Messenger$$, $$Mensageiro Animal$$, 2, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A morsel of food.)$$, $$24 horas$$, $$Por meio desta magia, você usa um animal para entregar uma mensagem. Escolha uma fera Minúscula à sua vista e no alcance da magia, como um esquilo, uma gralha azul ou um morcego. Você especifica uma localização que já tenha visitado e um destinatário que combine com uma descrição geral, tal como: "uma mulher ou um homem vestido com o uniforme da guarda da cidade" ou "um anão ruivo usando um chapéu pontudo". Você também deve falar uma mensagem de até vinte e cinco palavras. Enquanto a magia durar, a fera alvo viaja em direção à localização especificada, cobrindo cerca de 80 quilômetros [50 miles] durante 24 horas para um mensageiro voador, ou 40 quilômetros [25 miles] para outros animais.

Quando o mensageiro chegar, ele entrega a mensagem para a criatura que você descreveu, replicando o som da sua voz. O mensageiro fala somente com a criatura que combina com a descrição que você forneceu. Se o mensageiro não alcançar o destino antes do fim da duração da magia, a mensagem se perde e a fera refaz o caminho de volta para o lugar onde você conjurou a magia.

Em Círculos Superiores.  Se você conjurar essa magia usando um espaço de magia de 3º círculo ou superior, a duração da magia aumenta em 48 horas para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$animal-shapes-2014$$, $$Animal Shapes$$, $$Formas Animais$$, 8, $$Transmutação$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Concentração, até 24 horas$$, $$Sua magia transforma outras criaturas em feras. Escolha qualquer número de criaturas voluntárias à sua vista e dentro do alcance. Você transforma cada alvo em uma fera Grande ou menor, cujo nível de desafio seja 4 ou menor. Nos turnos subsequentes, você pode usar uma ação para dar novas formas às criaturas afetadas.

A transformação persiste enquanto a magia durar ou até que o alvo fique com 0 pontos de vida ou morra. Você pode escolher uma forma diferente para cada alvo. As estatísticas de jogo de cada alvo são substituídas pelas estatísticas da fera escolhida, embora o alvo mantenha o alinhamento e valores de Inteligência, Sabedoria e Carisma originais. O alvo assume os pontos de vida da nova forma, e quando reverte para a forma original, retorna para a quantidade de pontos de vida que possuía antes da transformação. Se a transformação for revertida como resultado dos pontos de vida do alvo serem reduzidos a 0, todo o excesso de dano será transferido para a forma original. Contanto que esse excesso de dano não reduza a forma original do alvo a 0 pontos de vida, ele não fica inconsciente. As ações que a criatura pode executar estão limitadas pela nova forma, e ela não pode falar ou conjurar magias.

Os equipamentos do alvo se fundem à nova forma. O alvo não pode ativar, empunhar, ou receber quaisquer benefícios desses equipamentos.$$, $$SRD$$),
($$SRD_2014$$, $$animate-dead-2014$$, $$Animate Dead$$, $$Animar Mortos$$, 3, $$Necromancia$$, $$1 minuto$$, $$3 metros$$, $$V, S, M (A drop of blood, a piece of flesh, and a pinch of bone dust.)$$, $$Instantânea$$, $$Esta magia cria um servo morto-vivo. Escolha uma pilha de ossos ou o cadáver de um humanoide Médio ou Pequeno, dentro do alcance da magia. Você infunde o alvo com uma perversa imitação de vida, fazendo-o se erguer como uma criatura morta-viva. O alvo se torna um esqueleto, se você escolheu ossos, ou um zumbi, se você escolheu um cadáver (o DM fornece as estatísticas da criatura).

Em cada um de seus turnos, você pode usar uma ação bônus para comandar mentalmente qualquer criatura que tenha criado com esta magia, e que esteja a até 18 metros [60 ft.] de você (se controlar múltiplas criaturas, você pode comandar uma ou todas simultaneamente, emitindo o mesmo comando para todas). Você decide qual ação a criatura tomará e para onde ela se moverá durante o próximo turno dela, ou você pode emitir um comando mais genérico, como manter a guarda de uma câmara ou corredor. Se você não emitir nenhum comando, a criatura apenas se defende de criaturas hostis. Uma vez dada a ordem, a criatura continuará seguindo-a até que a tarefa esteja completa.

A criatura fica sob seu controle por 24 horas, período após o qual ela para de obedecer aos seus comandos. Para manter o controle por mais 24 horas, é necessário conjurar novamente esta magia na criatura antes que o período de controle atual de 24 horas acabe. Isso restabelece o seu controle sobre até quatro criaturas que você tenha animado com esta magia em vez de animar uma nova.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou maior, você pode animar ou restabelecer o controle sobre mais dois mortos-vivos para cada círculo do espaço acima do 3º. Cada uma das criaturas precisa ter vindo de uma pilha de ossos ou cadáver único.$$, $$SRD$$),
($$SRD_2014$$, $$animate-objects-2014$$, $$Animate Objects$$, $$Animar Objetos$$, 5, $$Transmutação$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Objetos ganham vida ao seu comando. Escolha até dez objetos não-mágicos no alcance da magia e que não estejam sendo usados ou carregados. Alvos de tamanho Médio contam como dois objetos, de tamanho Grande contam como quatro objetos e os de tamanho Enorme contam como oito objetos. Você não pode animar qualquer objeto maior que Enorme. Cada alvo se anima, tornando-se uma criatura sobre o seu controle enquanto a magia durar ou até ficar com 0 pontos de vida.  Com uma ação bônus, você pode comandar mentalmente qualquer criatura que tenha criado com esta magia e que esteja a até 150 metros [500 ft.] de você (se controlar múltiplas criaturas, você pode comandar uma ou todas simultaneamente, emitindo o mesmo comando para todas). Você decide qual ação a criatura tomará e para onde ela se moverá durante o próximo turno dela, ou você pode emitir um comando mais genérico, como manter a guarda de uma câmara ou corredor. Se você não emitir nenhum comando, a criatura apenas se defende de criaturas hostis. Uma vez dada a ordem, a criatura continua seguindo-a até que a tarefa esteja completa.   Estatísticas de Objeto Animado   Tamanho        PV   CA   Ataque                                      For Des  Minúsculo        20   18   +8 para acertar, 1d4 + 4 pontos de dano    4     18  Pequeno     25   16   +6 para acertar, 1d8 + 2 pontos de dano    6     14  Médio 40   13  +5 para acertar, 2d6 + 1 pontos de dano    10   12  Grande      50   10  +6 para acertar, 2d10 + 2 pontos de dano  14   10  Enorme       80   10  +8 para acertar, 2d12 + 4 pontos de dano  18   6  Um objeto animado é um constructo com CA, pontos de vida, ataques, Força e Destreza determinados pelo tamanho dele. A Constituição é 10, a Inteligência e Sabedoria são 3 e o Carisma é 1. O deslocamento é de 9 metros [30 ft.]; se o objeto não tiver pernas ou outros apêndices que possa usar para se locomover, ele tem um deslocamento de voo de 9 metros [30 ft.] e pode flutuar. Se o objeto estiver preso firmemente a uma superfície ou a um objeto maior, como uma corrente presa a uma parede, o deslocamento é 0. Ele tem percepção às cegas em um raio de 9 metros [30 ft.] e é cego além dessa distância. Quando o objeto animado ficar com 0 pontos de vida, ele reverte para a forma original e qualquer dano restante é transferido para a forma original de objeto.  Se você ordenar a um objeto que ataque, ele faz um único ataque corpo a corpo contra uma criatura a até 1,5 metro [5 ft.] de distância dele. Ele ataca com uma pancada, cujo bônus de ataque e dano contundente são determinados pelo tamanho dele. O DM pode determinar que um objeto específico inflige dano cortante ou perfurante, dependendo da forma que ele possuir.   Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, você pode animar mais dois objetos para cada círculo do espaço acima do 5º.$$, $$SRD$$),
($$SRD_2014$$, $$antilife-shell-2014$$, $$Antilife Shell$$, $$Cúpula Antivida$$, 5, $$Abjuração$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Uma barreira cintilante estende-se a partir de você em um raio de 3 metros [10 ft.]. Ela permanece centrada em você e, portanto, acompanha-o aonde quer que vá, barrando a presença de criaturas que não sejam mortos-vivos e constructos. A barreira persiste enquanto a magia durar.

A barreira impede uma criatura afetada por ela de ultrapassá-la completa ou parcialmente. Tal criatura, contudo, pode conjurar magias, realizar ataques com armas de combate à distância ou armas de combate corpo a corpo que possuam a propriedade extensão, através da barreira.

Se você se mover de modo que uma criatura seja forçada a atravessar a barreira, a magia se encerra.$$, $$SRD$$),
($$SRD_2014$$, $$antimagic-field-2014$$, $$Antimagic Field$$, $$Campo Antimagia$$, 8, $$Abjuração$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A pinch of powdered iron or iron filings.)$$, $$Concentração, até 1 hora$$, $$Você é circundado por uma esfera antimagia invisível, com 3 metros de raio [10-foot-radius sphere]. Essa área é separada da energia mágica que permeia o Multiverso. Dentro da esfera, magias não podem ser conjuradas, criaturas convocadas desaparecem e itens mágicos tornam-se mundanos. Enquanto a magia durar, a esfera, centrada em você, move-se para onde quer que você vá.

Magias e outros efeitos mágicos, exceto aqueles criados por um artefato ou uma divindade, são suprimidos na esfera e não podem penetrá-la. Um espaço de magia utilizado para conjurar uma magia suprimida é consumido normalmente. Enquanto um efeito é suprimido, ele não funciona, mas o tempo que passa suprimido conta para sua duração.

Áreas de Magias.  A área de outra magia ou efeito mágico como Bola de Fogo, não se alastra para dentro da esfera. Se a esfera se sobrepuser a uma área de magia, a parte da área coberta pela esfera é suprimida. Por exemplo, as chamas criadas por Muralha de Fogo são suprimidas dentro da esfera, criando uma lacuna na muralha se a área sobreposta for grande o suficiente.

Criaturas e Objetos.  Quaisquer criaturas ou objetos conjurados ou criados por magia desaparecem temporariamente da existência enquanto estiverem dentro da esfera, reaparecendo instantaneamente uma vez que o espaço ocupado por eles não esteja mais dentro da esfera.

Dissipar Magia.  Magias e outros efeitos mágicos, como Dissipar Magia, não afetam a esfera. Da mesma forma, as esferas criadas por campos antimagia diferentes não anulam umas às outras.

Efeitos de Alvo.  Magias e outros efeitos mágicos, como os de Mísseis Mágicos e Enfeitiçar Pessoa, que tenham como alvo uma criatura ou um objeto dentro da esfera não têm efeito sobre eles.

Itens Mágicos.  As propriedades e poderes de itens mágicos são suprimidos dentro da esfera. Por exemplo, uma espada longa +1 dentro da esfera funciona como uma espada longa não-mágica.

As propriedades e poderes de uma arma mágica são suprimidos se usados contra um alvo dentro da esfera ou usados por um atacante dentro da esfera. Se uma arma ou munição mágica sair completamente da esfera (por exemplo, se você atirar uma flecha ou arremessar uma lança mágica em um alvo fora da esfera), a magia do item deixa de ser suprimida assim que este deixar a esfera.

Magias.  Quaisquer magias ou outros efeitos mágicos ativos sobre uma criatura ou objeto dentro da esfera são suprimidos enquanto a criatura ou objeto estiver dentro dela.

Viagem Mágica.  Teleporte e viagens planares falham dentro da esfera, seja esta o ponto de destino ou o ponto de partida de tal viagem mágica. Um portal para outra localidade, mundo ou plano de existência, assim como uma abertura para um espaço interdimensional, como o criado pela magia Corda Extradimensional, fecha-se temporariamente enquanto estiver dentro da esfera.$$, $$SRD$$),
($$SRD_2014$$, $$antipathy-sympathy-2014$$, $$Antipathy/Sympathy$$, $$Antipatia/Simpatia$$, 8, $$Encantamento$$, $$1 hora$$, $$18 metros$$, $$V, S, M (Either a lump of alum soaked in vinegar for the antipathy effect or a drop of honey for the sympathy effect.)$$, $$10 dias$$, $$Esta magia atrai ou repele criaturas à sua escolha. Você escolhe um alvo dentro do alcance da magia, seja uma criatura ou objeto Enorme ou menor, ou uma área que não seja maior do que um cubo de 60 metros de lado [200-foot cube]. Depois, especifique um tipo de criatura inteligente, como dragões vermelhos, goblins ou vampiros. Você confere ao alvo uma aura que atrai ou repele o tipo de criatura especificado, enquanto a magia durar. Escolha antipatia ou simpatia como efeito das auras.

Antipatia.  O encantamento faz com que criaturas do tipo que você designou sintam um intenso desejo de deixar a área e evitar o alvo. Quando a criatura avistar o alvo ou aproximar-se a até 18 metros [60 ft.] ou menos dele, a criatura deve ser bem-sucedida em uma salvaguarda de Sabedoria ou fica amedrontada. A criatura permanece amedrontada enquanto puder ver o alvo ou estiver a até 18 metros [60 ft.] ou menos dele. Enquanto estiver amedrontada pelo alvo, a criatura deve usar seu deslocamento para mover-se para o local seguro mais próximo de onde não possa mais ver o alvo. Se a criatura mover-se para mais que 18 metros [60 ft.] do alvo e não puder mais vê-lo, ela não está mais amedrontada, mas fica amedrontada novamente se avistar o alvo ou ficar a até 18 metros [60 ft.] ou menos dele.

Simpatia.  O encantamento faz com que as criaturas especificadas sintam um intenso desejo de se aproximar do alvo, enquanto estiverem a até 18 metros [60 ft.] dele ou puderem vê-lo. Quando a criatura vir o alvo, ou se aproximar a até 18 metros [60 ft.] ou menos dele, ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou usar o deslocamento em cada um dos turnos dela para entrar na área ou ficar sob alcance do alvo. Tendo feito isso, a criatura não pode afastar-se voluntariamente do alvo.

Se o alvo causar dano ou ferir de qualquer outra forma a criatura afetada por esta magia, esta pode fazer uma salvaguarda de Sabedoria para encerrar o efeito, como descrito adiante.

Encerrando o Efeito.  Se uma criatura afetada por esta magia terminar o turno a uma distância maior do que 18 metros [60 ft.] do alvo ou sem poder vê-lo, ela deve fazer uma salvaguarda de Sabedoria. Em caso de sucesso, ela não está mais sob efeito desta magia e reconhece o sentimento de repugnância ou de atração como sendo mágico. Além disso, uma criatura sob este efeito pode realizar outra salvaguarda de Sabedoria a cada 24 horas que a magia persistir.

Uma criatura bem-sucedida na salvaguarda contra esse efeito fica imune a ele por 1 minuto, podendo voltar a ser afetada após esse período.$$, $$SRD$$),
($$SRD_2014$$, $$arcane-eye-2014$$, $$Arcane Eye$$, $$Olho Arcano$$, 4, $$Adivinhação$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A bit of bat fur.)$$, $$Concentração, até 1 hora$$, $$Você cria um olho mágico e invisível dentro do alcance da magia. Esse olho paira no ar enquanto a magia durar.  Você recebe mentalmente as imagens vindas do olho, que conta com visão normal e visão no escuro de 9 metros [30 ft.]. O olho pode enxergar em qualquer direção.  Com uma ação, você pode mover o olho por até 9 metros [30 ft.] em qualquer direção. Não há limites para quão longe de você o olho pode se mover, porém, ele não pode entrar em outro plano de existência. Qualquer barreira sólida bloqueará os movimentos do olho, mas ele pode passar por uma pequena abertura de pelo menos 2,5 centímetros [1 inch].$$, $$SRD$$),
($$SRD_2014$$, $$arcane-hand-2014$$, $$Arcane Hand$$, $$Mão Arcana$$, 5, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S, M (An eggshell and a snakeskin glove.)$$, $$Concentração, até 1 minuto$$, $$Você cria uma mão de tamanho Grande, feita de uma energia translúcida e reluzente, em um espaço desocupado à sua vista e dentro do alcance da magia. A mão persiste enquanto a magia durar e move-se ao seu comando, imitando os movimentos de sua própria mão.  A mão é um objeto que tem CA 20 e pontos de vida iguais ao valor máximo de seus pontos de vida. Se ela cair para 0 pontos de vida, a magia se encerra. Ela tem Força 26 (+8) e Destreza 10 (+0), não preenchendo o espaço que parece ocupar.  No turno em que você conjurar a magia e depois, usando uma ação bônus nos seus turnos subsequentes, você poderá movê-la por até 18 metros [60 ft.] e causar os seguintes efeitos:   Punho Cerrado . A mão ataca uma criatura ou objeto a até 1,5 metro [5 ft.] dela. Faça um ataque mágico de combate corpo a corpo para a mão como se ela fizesse parte do seu corpo, ou seja, usando suas próprias estatísticas de jogo. Em caso de acerto, o alvo sofre 4d8 pontos de dano energético.   Mão Vigorosa . A mão tenta empurrar uma criatura a até 1,5 metro [5 ft.] de distância em uma direção que você escolher. Faça um teste de Força da mão, resistido pela Força (Atletismo) do alvo. Se o alvo for Médio ou menor, você tem vantagem no teste. Se for bem-sucedido, a mão empurra o alvo a até 1,5 metro [5 ft.] de distância, mais 1,5 metro [5 ft.] multiplicado por cinco vezes o valor de seu modificador do atributo de conjuração. A mão se move com o alvo para permanecer a 1,5 metro [5 ft.] dele.   Mão Esmagadora . A mão tenta agarrar uma criatura de tamanho Enorme ou menor dentro do alcance de 1,5 metro [5 ft.]. Você usa o valor da Força da mão para resolver o agarramento. Se o alvo for Médio ou menor, você tem vantagem no teste. Enquanto a mão estiver agarrando o alvo, você pode usar uma ação bônus para fazer com que a mão o esmague. Quando você faz isso, o alvo sofre dano contundente equivalente a 2d6 pontos de dano + o modificador de seu atributo de conjuração.   Mão Interposta . A mão se interpõe entre você e uma criatura à sua escolha, até que você lhe dê um comando diferente. A mão se desloca até ficar entre você e o alvo, proporcionando a você meia cobertura contra o alvo. Este último não pode se mover através do espaço da mão se o valor de Força dele for menor ou igual ao da mão. Se o valor de Força do alvo for maior do que o valor de Força da mão, ele pode se mover em direção a você atravessando o espaço ocupado pela mão, mas esse espaço é considerado terreno difícil para o alvo.   Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano da opção Punho Cerrado aumenta em 2d8 e o da Mão Esmagadora aumenta em 2d6 para cada círculo do espaço acima do 5º.$$, $$SRD$$),
($$SRD_2014$$, $$arcane-lock-2014$$, $$Arcane Lock$$, $$Tranca Arcana$$, 2, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (Gold dust worth at least 25gp, which the spell consumes.)$$, $$Até ser dissipada$$, $$Você toca uma porta, janela, portão, baú, ou outro tipo de entrada que já esteja fechada, tornando-a bloqueada enquanto a magia durar. Você e as criaturas que designar ao realizar a conjuração podem abrir o objeto normalmente. Você também pode definir uma senha que, quando dita a até 1,5 metro [5 ft.] do objeto, suprima esta magia durante 1 minuto. Caso contrário, o objeto fica trancado até que seja quebrado ou a magia seja dissipada ou suprimida. Conjurar Arrombar no objeto suprime a tranca arcana por 10 minutos.

Enquanto afetado por esta magia, o objeto é mais difícil de quebrar ou arrombar; a CD para quebrá-lo ou arrombar qualquer fechadura contida nele aumenta em 10.$$, $$SRD$$),
($$SRD_2014$$, $$arcane-sword-2014$$, $$Arcane Sword$$, $$Espada Arcana$$, 7, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp.)$$, $$Concentração, até 1 minuto$$, $$Você cria um plano de força em forma de espada que paira dentro do intervalo. Dura pela duração.  Quando a espada aparecer, você faz um ataque feitiço contra um alvo à sua escolha dentro de 5 pés da espada. Em um golpe, o alvo recebe 3d10 danos forçados. Até que a magia termine, você pode usar uma ação bônus em cada um dos seus turnos para mover a espada para um ponto que você pode ver e repetir esse ataque contra o mesmo alvo ou um diferente.$$, $$SRD$$),
($$SRD_2014$$, $$arcanists-magic-aura-2014$$, $$Arcanist's Magic Aura$$, $$Aura Mágica do Arcanista$$, 2, $$Ilusão$$, $$1 ação$$, $$Toque$$, $$V, S, M (A small square of silk.)$$, $$24 horas$$, $$Você toca uma criatura ou objeto, criando uma ilusão sobre o alvo e fazendo com que magias de adivinhação revelem informações falsas sobre ele. O alvo pode ser uma criatura voluntária ou um objeto que não esteja sendo carregado ou usado por outra criatura.

Ao conjurar a magia, escolha um ou ambos os efeitos a seguir. O efeito fica ativo enquanto a magia durar. Se você conjurar esta magia na mesma criatura ou objeto todos os dias durante 30 dias, colocando o mesmo efeito toda vez, a ilusão dura até ser dissipada.

Falsa Aura.  Você altera a maneira como o alvo parece para magias e efeitos mágicos, como Detectar Magia, que detectam auras mágicas. Você pode fazer um objeto não mágico parecer mágico, um objeto mágico parecer não mágico ou alterar a aura mágica do objeto, de modo que ele pareça pertencer a uma escola específica de magia que você escolher. Quando usar este efeito em um objeto, você pode fazer com que a magia falsa fique aparente para qualquer criatura que manipule o item.

Máscara.  Você altera a maneira como o alvo parece para magias e efeitos mágicos que detectam tipos de criatura, como o Sentido Divino de um paladino ou o gatilho de uma magia Símbolo. Você escolhe um tipo de criatura e outras magias e efeitos mágicos passam a tratar o alvo como se este pertencesse ao tipo ou alinhamento da criatura escolhida.$$, $$SRD$$),
($$SRD_2014$$, $$astral-projection-2014$$, $$Astral Projection$$, $$Projeção Astral$$, 9, $$Necromancia$$, $$1 hora$$, $$3 metros$$, $$V, S, M (For each creature you affect with this spell, you must provide one jacinth worth at least 1,000gp and one ornately carved bar of silver worth at least 100gp, all of which the spell consumes.)$$, $$Especial$$, $$Você e até oito criaturas voluntárias dentro do alcance da magia projetam seus corpos astrais no Plano Astral (a magia falha e a conjuração é desperdiçada caso você já se encontre nesse plano). O corpo material que você deixa para trás fica inconsciente e em estado de animação suspensa; ele não precisa de comida ou ar e não envelhece.

Seu corpo astral se assemelha à sua forma mortal em quase todos os sentidos, replicando suas estatísticas de jogo e posses. A principal diferença é a adição de um cordão prateado que se estende das suas omoplatas e deixa um rastro para trás, desvanecendo até ficar invisível após 30 centímetros [1 foot]. Esse cordão é sua conexão com seu corpo material. Enquanto o cordão permanece intacto, você pode encontrar seu caminho de volta para casa. Se ele for cortado - algo que só pode acontecer quando um efeito especificamente declarar isto -, sua alma e o corpo são separados, matando-o instantaneamente.

Sua forma astral pode viajar livremente no Plano Astral e passar através de portais ali existentes, que levem a qualquer outro plano. Se você entrar em um novo plano ou voltar para o plano em que estava quando conjurou esta magia, seu corpo e posses são transportadas ao longo do cordão prateado, permitindo que você entre novamente em seu corpo, imediatamente ao ingressar no novo plano. Sua forma astral é uma encarnação separada. Qualquer dano ou outros efeitos que se apliquem a ela não têm nenhum efeito em seu corpo físico, nem persistem quando você retorna para ele.

A magia termina para você e seus companheiros quando você usa sua ação para encerrá-la. Quando a magia termina, a criatura afetada retorna ao próprio corpo físico e desperta.

A magia também pode terminar mais cedo para você ou para um de seus companheiros. Uma magia Dissipar Magia conjurada com sucesso contra um corpo astral ou físico encerra a magia para essa criatura. Se o corpo original da criatura ou de sua forma astral fica com 0 pontos de vida, a magia se encerra para essa criatura. Se a magia se encerrar e o cordão prateado estiver intacto, ele puxa a forma astral da criatura de volta para o próprio corpo, que sai do estado de animação suspensa.

Se você for devolvido ao seu corpo prematuramente, seus companheiros permanecem em suas formas astrais e devem encontrar um meio de voltar para seus corpos, geralmente ao ficarem com 0 pontos de vida.$$, $$SRD$$),
($$SRD_2014$$, $$augury-2014$$, $$Augury$$, $$Augúrio$$, 2, $$Adivinhação$$, $$1 minuto$$, $$Pessoal$$, $$V, S, M (Specially marked sticks, bones, or similar tokens worth at least 25gp.)$$, $$Instantânea$$, $$Ao lançar varetas incrustadas com pedras preciosas, jogar ossos de dragão, dispor cartas ornamentadas ou empregar alguma outra ferramenta de adivinhação, você recebe um presságio de uma entidade de outro mundo sobre os resultados de um determinado curso de ação que você planeja tomar dentro dos próximos 30 minutos. O DM escolhe entre os seguintes presságios possíveis:

Prosperidade, para bons resultados

Infortúnio, para maus resultados

Prosperidade e Infortúnio, para resultados bons e maus

Nada, para resultados que não são especialmente bons ou maus

A magia não leva em conta quaisquer circunstâncias possíveis que possam mudar o resultado futuro, como a conjuração de magias adicionais ou a perda ou ganho de um companheiro.

Caso você conjure a magia duas ou mais vezes antes de concluir seu próximo descanso longo, há uma chance cumulativa de 25% para cada conjuração após a primeira de você obter uma resposta aleatória. O DM faz esta jogada em segredo.$$, $$SRD$$),
($$SRD_2014$$, $$awaken-2014$$, $$Awaken$$, $$Despertar$$, 5, $$Transmutação$$, $$8 horas$$, $$Toque$$, $$V, S, M (An agate worth at least 1,000 gp, which the spell consumes.)$$, $$Instantânea$$, $$Depois de gastar o tempo de conjuração traçando padrões mágicos com uma pedra preciosa, você toca em uma fera ou planta de tamanho Enorme ou menor. O alvo deve ter um valor de Inteligência igual a 3 ou menor ou não possuir Inteligência alguma. O alvo ganha um valor de Inteligência de 10. O alvo também ganha a habilidade de falar um idioma que você conheça. Se o alvo for uma planta, ela ganha a habilidade de mover seus galhos, raízes, cipós, trepadeiras e assim por diante, além de ganhar sentidos semelhantes aos de um humano. Seu DM escolhe as estatísticas adequadas a uma planta despertada, como as de um arbusto ou árvore despertados.

A fera ou planta despertada fica enfeitiçada por você durante 30 dias, ou até que você ou seus companheiros façam qualquer coisa que a prejudique. Quando a condição de enfeitiçada termina, a criatura despertada escolhe se quer permanecer amigável com você, com base em como foi tratada enquanto estava enfeitiçada.$$, $$SRD$$),
($$SRD_2014$$, $$bane-2014$$, $$Bane$$, $$Perdição$$, 1, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A drop of blood.)$$, $$Concentração, até 1 minuto$$, $$Até três criaturas, à sua escolha, à sua vista e que estejam dentro do alcance da magia, devem realizar salvaguardas de Carisma. Enquanto a magia durar, sempre que um alvo que falhar nessa salvaguarda fizer uma jogada de ataque ou uma salvaguarda, ele deverá jogar 1d4 e subtrair o número obtido do resultado da jogada de ataque ou salvaguarda.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você pode enfeitiçar uma criatura adicional para cada círculo do espaço acima do 1º.$$, $$SRD$$),
($$SRD_2014$$, $$banishment-2014$$, $$Banishment$$, $$Banimento$$, 4, $$Abjuração$$, $$1 ação$$, $$18 metros$$, $$V, S, M (An item distasteful to the target.)$$, $$Concentração, até 1 minuto$$, $$Você tenta enviar uma criatura à sua vista e que esteja dentro do alcance da magia para outro plano de existência. O alvo deve ser bem-sucedido em uma salvaguarda de Carisma ou será banido.

Se o alvo for nativo do plano em que você se encontra, ele é banido para um semiplano inofensivo. Enquanto permanecer lá, fica incapacitado. O alvo permanece banido enquanto a magia durar, quando, então, reaparece no espaço de onde partiu ou no espaço desocupado mais próximo, se o espaço original estiver ocupado.

Se o alvo for nativo de um plano de existência diferente daquele no qual você se encontra, ele é banido com um ligeiro estalo, voltando para o seu próprio plano de origem. Se a magia se encerrar antes que 1 minuto se passe, o alvo reaparece no espaço de onde partiu ou no espaço desocupado mais próximo, se o espaço original estiver ocupado. Caso contrário, o alvo não retorna.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 5º círculo ou maior, você pode atingir uma criatura adicional para cada círculo do espaço acima do 4º.$$, $$SRD$$),
($$SRD_2014$$, $$barkskin-2014$$, $$Barkskin$$, $$Pele-casca$$, 2, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (A handful of oak bark.)$$, $$Concentração, até 1 hora$$, $$Você toca uma criatura voluntária. A magia transforma a pele do alvo, tornando-a áspera e com a aparência de casca de árvore. Enquanto a magia durar, o alvo tem uma CA que não pode ser menor do que 16, independente do tipo de armadura vestida.$$, $$SRD$$),
($$SRD_2014$$, $$beacon-of-hope-2014$$, $$Beacon of Hope$$, $$Sinal de Esperança$$, 3, $$Abjuração$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Esta magia concede esperança e vitalidade. Escolha qualquer número de criaturas dentro do alcance da magia. Durante a duração desta magia, cada alvo terá vantagem em salvaguardas de Sabedoria e contra a morte, além de recuperar a quantidade máxima de pontos de vida possível de qualquer fonte de cura.$$, $$SRD$$),
($$SRD_2014$$, $$bestow-curse-2014$$, $$Bestow Curse$$, $$Rogar Maldição$$, 3, $$Necromancia$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Quando você toca uma criatura, ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou torna-se amaldiçoada enquanto a magia durar. Ao conjurar esta magia, você deve escolher a natureza da maldição, entre as seguintes opções:

Escolha um atributo. Enquanto amaldiçoado, o alvo tem desvantagem nos testes de atributo e salvaguardas feitas com este atributo.

Enquanto amaldiçoado, o alvo tem desvantagem nas jogadas de ataque contra você.

Enquanto amaldiçoado, o alvo deve fazer uma salvaguarda de Sabedoria no início de cada um dos turnos dele. Se falha, desperdiça a própria ação nesse turno, ficando sem fazer nada.

Enquanto o alvo está amaldiçoado, seus ataques e magias contra ele causam 1d8 pontos de dano necrótico extra.

Uma magia Remover Maldição encerra o efeito da magia. À escolha do DM, você pode optar por um efeito de maldição alternativo, mas ele não deve ser mais poderoso do que os descritos acima. O DM tem a palavra final sobre este efeito da maldição alternativa.

Em Círculos Superiores.  Se você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, a duração dela será Concentração, até 10 minutos. Se você usar um espaço de magia de 5º círculo ou superior, a duração passa a ser 8 horas. Se você usar um espaço de magia de 7º círculo ou superior, a duração passa a ser 24 horas. Se você usar um espaço de magia de 9º círculo, a magia dura até ser dissipada. Usar um espaço de magia de 5º círculo ou superior concede uma duração que não requer concentração.$$, $$SRD$$),
($$SRD_2014$$, $$black-tentacles-2014$$, $$Black Tentacles$$, $$Tentáculos Negros$$, 4, $$Conjuração$$, $$1 ação$$, $$27 metros$$, $$V, S, M (A piece of tentacle from a giant octopus or a giant squid)$$, $$Concentração, até 1 minuto$$, $$Tentáculos negros se contorcem, preenchendo uma área de 6 metros quadrados [20-foot square] de solo à sua vista, no alcance da magia. Enquanto a magia durar, os tentáculos transformam o solo da área em terreno difícil.

Quando uma criatura entra pela primeira vez ou quando inicia o próprio turno na área afetada, ela deve fazer uma salvaguarda de Destreza. Se falhar, sofre 3d6 pontos de dano contundente, ficando contida pelos tentáculos até que a magia encerre. Uma criatura que inicie o próprio turno na área e esteja contida pelos tentáculos, sofre 3d6 pontos de dano contundente.

Uma criatura contida pelos tentáculos pode usar a própria ação para fazer um teste de Força ou Destreza (à escolha dela) contra a CD para evitar sua magia. Em caso de sucesso, ela se liberta.$$, $$SRD$$),
($$SRD_2014$$, $$blade-barrier-2014$$, $$Blade Barrier$$, $$Barreira de Lâminas$$, 6, $$Evocação$$, $$1 ação$$, $$27 metros$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Você cria uma barreira vertical de lâminas rodopiantes e afiadas feitas de energia mágica. A barreira aparece dentro do alcance da magia e permanece enquanto a magia durar. Você pode fazer uma barreira reta de até 30 metros [100 ft.] de comprimento, 6 metros [20 ft.] de altura e 1,5 metro [5 ft.] de espessura, ou uma barreira circular de até 18 metros [60 ft.] de diâmetro, 6 metros [20 ft.] de altura e 1,5 metro [5 ft.] de espessura. A barreira fornece três quartos de cobertura para as criaturas atrás dela; o espaço dela é considerado terreno difícil.

Quando uma criatura entra na área da barreira pela primeira vez ou inicia o próprio turno ali, ela deve fazer uma salvaguarda de Destreza. Se falhar, sofre 6d10 pontos de dano cortante, ou metade do dano em caso de sucesso.$$, $$SRD$$),
($$SRD_2014$$, $$bless-2014$$, $$Bless$$, $$Bênção$$, 1, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A sprinkling of holy water.)$$, $$Concentração, até 1 minuto$$, $$Você abençoa até três criaturas no alcance da magia. Sempre que um alvo realiza uma jogada de ataque ou uma salvaguarda antes que a magia termine, o alvo adiciona 1d4 à jogada de ataque ou salvaguarda.   Usando Espaços de Magia de Círculo Superior.  Você pode escolher uma criatura adicional para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$blight-2014$$, $$Blight$$, $$Blight$$, 4, $$Necromancia$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Instantânea$$, $$A creature that you can see within range makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one. A Plant creature automatically fails the save.  Alternatively, target a nonmagical plant that isn't a creature, such as a tree or shrub. It doesn't make a save; it simply withers and dies.   Usando Espaços de Magia de Círculo Superior.  The damage increases by 1d8 for each spell slot level above 4.$$, $$SRD$$),
($$SRD_2014$$, $$blindness-deafness-2014$$, $$Blindness/Deafness$$, $$Cegueira/Surdez$$, 2, $$Necromancia$$, $$1 ação$$, $$9 metros$$, $$V$$, $$1 minuto$$, $$Você pode cegar ou ensurdecer um inimigo. Escolha um alvo à sua vista e que esteja no alcance desta magia. Ele deve fazer uma salvaguarda de Constituição. Se falhar, fica cego ou surdo (à sua escolha) enquanto a magia durar. No final de cada um dos turnos dele, o alvo pode realizar uma salvaguarda de Constituição. Se for bem-sucedido, a magia se encerra.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode atingir uma criatura adicional para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$blink-2014$$, $$Blink$$, $$Piscar$$, 3, $$Transmutação$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$1 minuto$$, $$Jogue 1d20 no final de cada um de seus turnos enquanto a magia durar. Com um resultado igual ou maior que 11, você desaparece do seu plano de existência atual e aparece no Plano Etéreo (a magia falha e a conjuração é desperdiçada se você já estiver nesse plano). No início do seu próximo turno, e quando a magia terminar, se você estiver no Plano Etéreo, você retorna para um espaço desocupado à sua escolha, à sua vista e que esteja a até 3 metros [10 ft.] do espaço de onde você desapareceu. Se não houver espaço desocupado disponível dentro desse alcance, você aparece no próximo espaço desocupado (escolhido aleatoriamente, se mais do que um espaço estiver igualmente próximo). Você pode encerrar esta magia com uma ação.

Enquanto estiver no Plano Etéreo, você pode ver (em tons de cinza, a uma distância de até 18 metros [60 ft.]) e ouvir seu plano de origem. Você só pode afetar e ser afetado por criaturas que estejam no Plano Etéreo. Criaturas que não estejam nesse plano não podem percebê-lo ou interagir com você, a menos que tenham uma habilidade específica que lhes permita fazê-lo.$$, $$SRD$$),
($$SRD_2014$$, $$blur-2014$$, $$Blur$$, $$Turvar$$, 2, $$Ilusão$$, $$1 ação$$, $$Pessoal$$, $$V$$, $$Concentração, até 1 minuto$$, $$Seu corpo torna-se turvo, mudando e oscilando para todos os que possam vê-lo. Ao longo da duração desta magia, qualquer criatura tem desvantagem em jogadas de ataque contra você. Um atacante é imune a este efeito se não depender da visão, como alguém com percepção às cegas, ou se puder ver através de ilusões, como alguém com visão verdadeira.$$, $$SRD$$),
($$SRD_2014$$, $$branding-smite-2014$$, $$Branding Smite$$, $$Marca da Punição$$, 2, $$Evocação$$, $$1 ação bônus$$, $$Pessoal$$, $$V$$, $$Concentração, até 1 minuto$$, $$Enquanto durar esta magia, na próxima vez que você atingir uma criatura com uma arma, ela brilhará com radiação astral conforme você acerta. O ataque causa 2d6 pontos de dano radiante adicionais ao alvo, que torna-se visível (caso esteja invisível), emitindo uma luz fraca, criando meia-luz num raio de 1,5 metro [5 ft.] e não podendo retornar à condição invisível enquanto a magia durar.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$burning-hands-2014$$, $$Burning Hands$$, $$Mãos Flamejantes$$, 1, $$Evocação$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$Instantânea$$, $$Uma fina camada de chamas parte de você. Cada criatura em um Cone de 4,5 metros realiza uma salvaguarda de Destreza, sofrendo 3d6 pontos de dano Ígneo se falhar, ou metade desse dano em caso de sucesso.  Objetos inflamáveis no Cone que não estão sendo usados ou carregados entram em combustão.   Usando Espaços de Magia de Círculo Superior.  O dano aumenta em 1d6 pontos para cada círculo de espaço de magia acima do 1º.$$, $$SRD$$),
($$SRD_2014$$, $$call-lightning-2014$$, $$Call Lightning$$, $$Convocar Relâmpagos$$, 3, $$Conjuração$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Uma nuvem de tempestade aparece na forma de um cilindro de 3 metros de altura [10 ft. tall cilinder] com um raio de 18 metros [60 ft. radius], centralizado em um ponto à sua vista, dentro do alcance diretamente acima de você. A magia falha se você não puder ver um ponto no ar onde a nuvem de tempestade possa aparecer (por exemplo, se você estiver em uma sala que não possa acomodar a nuvem).

Ao conjurar a magia, escolha um ponto que você possa ver sob a nuvem. Um raio de eletricidade parte da nuvem até esse ponto. Cada criatura a uma distância de até 1,5 metro [5 ft.] desse ponto deve fazer uma salvaguarda de Destreza. Se falhar, sofre 3d10 pontos de dano elétrico, ou metade do dano em caso de sucesso. Em cada um de seus turnos, enquanto a magia durar, você pode usar sua ação para convocar relâmpagos dessa maneira, atingindo o mesmo ponto ou outro.

Se você estiver ao ar livre e em condições tempestuosas ao conjurar esta magia, ela lhe confere o controle sobre a tempestade existente, em vez de criar uma nova. Sob essas condições, o dano da magia aumenta em 1d10.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 3º.$$, $$SRD$$),
($$SRD_2014$$, $$calm-emotions-2014$$, $$Calm Emotions$$, $$Acalmar Emoções$$, 2, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você tenta suprimir emoções fortes em um grupo de criaturas. Cada humanoide dentro de uma esfera de 6 metros de raio [20-foot-radius sphere] centrada em um ponto dentro do alcance da magia deve fazer uma salvaguarda de Carisma; uma criatura pode escolher falhar nesta salvaguarda, caso deseje. Se uma criatura falhar na salvaguarda, escolha um dos dois efeitos a seguir. Você pode suprimir qualquer efeito que cause a um alvo as condições enfeitiçado ou amedrontado. Quando esta magia termina, qualquer efeito suprimido retorna, caso a duração não tenha expirado nesse meio-tempo.

Como alternativa, você pode tornar o alvo indiferente a criaturas, à sua escolha, contra as quais o alvo era hostil. Tal indiferença termina se o alvo for atacado ou ferido por uma magia, ou se testemunhar quaisquer de seus próprios amigos sendo feridos. Quando a magia termina, a criatura torna-se hostil novamente, a menos que o DM decida de outra forma.$$, $$SRD$$),
($$SRD_2014$$, $$chain-lightning-2014$$, $$Chain Lightning$$, $$Corrente de Relâmpagos$$, 6, $$Evocação$$, $$1 ação$$, $$45 metros$$, $$V, S, M (A bit of fur; a piece of amber, glass, or a crystal rod; and three silver pins.)$$, $$Instantânea$$, $$Você cria um raio de eletricidade que salta em direção a um alvo à sua escolha, o qual você possa ver e que esteja dentro do alcance da magia. Em seguida, três raios saltam do alvo na direção de até três outros alvos, que devem estar a até 9 metros [30 ft.] do primeiro. Cada alvo pode ser uma criatura ou um objeto, e só pode ser atingido por apenas um dos raios.

O alvo deve fazer uma salvaguarda de Constituição. Se falhar, sofre 10d8 de dano elétrico, ou metade do dano em caso de sucesso.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 7º círculo ou superior, um raio adicional salta do primeiro alvo em direção a outro, para cada círculo do espaço acima do 6º.$$, $$SRD$$),
($$SRD_2014$$, $$charm-person-2014$$, $$Charm Person$$, $$Enfeitiçar Pessoa$$, 1, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$1 hora$$, $$Um Humanoide à sua vista e no alcance da magia realiza uma salvaguarda de Sabedoria. Ele tem Vantagem se você ou seus aliados estiverem lutando contra ele. Se falhar, o alvo tem a condição &Reference[charmed apply=false] até que a magia termine ou até que você ou seus aliados causem dano a ele. A criatura Enfeitiçada é Amigável a você. Quando a magia termina, o alvo sabe que foi Enfeitiçado por você.   Usando Espaços de Magia de Círculo Superior.  Você pode escolher uma criatura adicional para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$chill-touch-2014$$, $$Chill Touch$$, $$Toque Necrótico$$, 0, $$Necromancia$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$1 rodada$$, $$Você cria uma mão esquelética e fantasmagórica no espaço ocupado por uma criatura que se encontre no alcance da magia. Faça um ataque mágico à distância contra a criatura para atingi-la com um calafrio sepulcral. Se o ataque for bem-sucedido, ela sofre 1d8 pontos de dano necrótico e não pode recuperar pontos de vida até o início do seu próximo turno. Até lá, a mão se agarra ao alvo.

Se você atacar um alvo morto-vivo, ele também terá desvantagem nas jogadas de ataque contra você até o final do seu próximo turno.

O dano desta magia aumenta em 1d8 quando você alcança o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).$$, $$SRD$$),
($$SRD_2014$$, $$circle-of-death-2014$$, $$Circle of Death$$, $$Círculo da Morte$$, 6, $$Necromancia$$, $$1 ação$$, $$45 metros$$, $$V, S, M (The powder of a crushed black pearl worth at least 500 gp.)$$, $$Instantânea$$, $$Uma esfera de energia negativa emite ondulações em um raio de 18 metros [60-foot radius] a partir de um ponto dentro da área do alcance da magia. Cada criatura na área deve fazer uma salvaguarda de Constituição. Se falhar, sofre 8d6 de dano necrótico, ou metade do dano em caso de sucesso.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 7º círculo ou superior, o dano aumenta em 2d6 para cada círculo do espaço acima do 6º.$$, $$SRD$$),
($$SRD_2014$$, $$clairvoyance-2014$$, $$Clairvoyance$$, $$Clarividência$$, 3, $$Adivinhação$$, $$10 minutos$$, $$2 km$$, $$V, S, M (A focus worth at least 100gp, either a jeweled horn for hearing or a glass eye for seeing.)$$, $$Concentração, até 10 minutos$$, $$Você cria um sensor invisível em um local que lhe seja familiar (um lugar que visitou ou que já tenha visto) ou em uma localidade óbvia, mas que não lhe seja familiar (como atrás de uma porta, contornando uma esquina ou em um bosque), ambos dentro do alcance da magia. O sensor permanece no local enquanto a magia durar, não podendo ser atacado nem ser alvo de qualquer outro tipo de interação.

Ao conjurar a magia, você escolhe ver ou ouvir. Você pode usar o sentido escolhido por meio do sensor como se estivesse no espaço ocupado por ele. Com uso de uma ação, você pode alternar entre ver e ouvir.

Uma criatura que possa ver o sensor (como aquelas que se beneficiam de Ver o Invisível ou visão verdadeira), enxerga um orbe luminoso e intangível do tamanho de um punho.$$, $$SRD$$),
($$SRD_2014$$, $$clone-2014$$, $$Clone$$, $$Clone$$, 8, $$Necromancia$$, $$1 hora$$, $$Toque$$, $$V, S, M (A diamond worth at least 1,000 gp and at least 1 cubic inch of flesh of the creature that is to be cloned, which the spell consumes, and a vessel worth at least 2,000 gp that has a sealable lid and is large enough to hold a Medium creature, such as a huge urn, coffin, mud-filled cyst in the ground, or crystal container filled with salt water.)$$, $$Instantânea$$, $$Esta magia cria uma duplicata inerte de uma criatura viva, a título de garantia contra a morte. Esse clone forma-se dentro de um receptáculo selado, crescendo e amadurecendo completamente após 120 dias; também existe a opção de o clone ser a versão mais jovem da mesma criatura. Ele se mantém inerte e dura indefinidamente, contanto que o receptáculo não seja perturbado.  A qualquer momento após o clone amadurecer, se a criatura original morrer, a alma dela é transferida para o clone, considerando que a alma seja livre e disposta a retornar. O clone é fisicamente idêntico ao original, tendo a mesma personalidade, memórias e habilidades, mas nenhum dos equipamentos da forma original. Os restos mortais da criatura original permanecem, se ainda existirem, ficam inertes e não podem ter a vida restaurada, já que a alma da criatura está em outro receptáculo.$$, $$SRD$$),
($$SRD_2014$$, $$cloudkill-2014$$, $$Cloudkill$$, $$Névoa Mortal$$, 5, $$Conjuração$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Você cria uma esfera com raio de 6 metros [20-foot-radius sphere], feita de uma névoa venenosa amarelo-esverdeada, centrada em um ponto à sua escolha e no alcance da magia. A névoa se alastra, contornando os cantos e a área afetada fica totalmente obscurecida. Ela persiste enquanto a magia durar ou até que um vento forte a disperse, encerrando a magia.

Quando uma criatura entra na área da magia pela primeira vez ou inicia o próprio turno ali, ela deve fazer uma salvaguarda de Constituição. Se falhar, sofre 5d8 de dano venenoso, ou metade do dano em caso de sucesso. As criaturas são afetadas mesmo se prenderem a respiração ou não precisarem respirar.

O nevoeiro se distancia 3 metros [10 ft.] de você no início de cada um de seus turnos, deslizando sobre o solo. Os vapores, por serem mais pesados que o ar, descem para o nível mais baixo da terra, esvaindo-se por eventuais aberturas.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 5º.$$, $$SRD$$),
($$SRD_2014$$, $$color-spray-2014$$, $$Color Spray$$, $$Leque Cromático$$, 1, $$Ilusão$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A pinch of powder or sand that is colored red, yellow, and blue.)$$, $$1 rodada$$, $$Uma deslumbrante variedade de luzes ofuscantes e coloridas projeta-se da sua mão. Jogue 6d10; o resultado será a quantidade total de pontos de vida das criaturas que esta magia pode afetar. Criaturas em um cone de 4,5 metros [15-foot cone] com origem em você são afetadas em ordem crescente de seus pontos de vida atuais (ignorando criaturas inconscientes e criaturas que não possam enxergar).

Começando com a criatura com a menor quantidade de pontos de vida, cada criatura afetada por esta magia fica cega enquanto a magia durar. Subtraia os pontos de vida de cada criatura do total, antes de continuar para a próxima com os pontos de vida mais baixos. Os pontos de vida da criatura devem ser menores ou iguais ao total remanescente para que ela seja afetada.

Em Cïrculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 2º círculo ou superior, jogue 2d10 adicionais para cada círculo do espaço acima do 1º.$$, $$SRD$$),
($$SRD_2014$$, $$command-2014$$, $$Command$$, $$Comando$$, 1, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V$$, $$1 rodada$$, $$Você profere uma palavra única de comando para uma criatura à sua vista e no alcance da magia. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou segue o comando no próximo turno dele. Escolha o comando a partir destas opções:   Abaixar.  O alvo tem a condição Caído e, em seguida, termina o turno.   Aproximar.  O alvo se move em sua direção pela rota mais curta e direta, terminando o turno dele se ele se mover a até 1,5 metro de você.   Fugir.  O alvo usa o próprio turno se afastando de você pelos meios mais rápidos disponíveis.   Largar. O alvo solta o que estiver segurando e, em seguida, termina o turno.   Parar.  No turno do alvo, ele não se move e não executa nenhuma ação ou Ação Bônus.   Usando Espaços de Magia de Círculo Superior.  Você pode escolher um efeito adicional para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$commune-2014$$, $$Commune$$, $$Comunhão$$, 5, $$Adivinhação$$, $$1 minuto$$, $$Pessoal$$, $$V, S, M (Incense and a vial of holy or unholy water.)$$, $$1 minuto$$, $$Você entra em contato com sua divindade ou com um representante dela, e faz até três perguntas que podem ser respondidas com sim ou não. É preciso fazer as perguntas antes da magia terminar. Você recebe uma resposta correta para cada pergunta.

Seres divinos não são, necessariamente, oniscientes, então você pode receber "indeterminado" como resposta, caso a pergunta se refira a uma informação que está além do conhecimento da divindade. No caso em que uma única palavra como resposta puder levar a uma interpretação errada ou contrária aos interesses da divindade, o DM pode responder com uma frase curta.

Se você conjurar a magia duas ou mais vezes antes de concluir seu próximo descanso longo, há uma chance cumulativa de 25% para cada conjuração após a primeira de você não obter uma resposta. O DM faz essa jogada em segredo.$$, $$SRD$$),
($$SRD_2014$$, $$commune-with-nature-2014$$, $$Commune With Nature$$, $$Comunhão com a Natureza$$, 5, $$Adivinhação$$, $$1 minuto$$, $$Pessoal$$, $$V, S$$, $$Instantânea$$, $$Você se torna um com a natureza por um curto período, ganhando conhecimento do território circundante. Ao ar livre, a magia lhe dá informações sobre o terreno num raio de 5 quilômetros [3 miles]. Em cavernas e outros ambientes naturais subterrâneos, o raio é limitado a 90 metros [300 ft.]. A magia não funciona onde a natureza foi substituída por construções, como masmorras, aldeias e cidades.

Você ganha instantaneamente o conhecimento de até três fatos sobre qualquer um dos temas a seguir, à sua escolha, e sobre como eles se relacionam com a área:

Terreno e corpos d'água;

Plantas, minerais, animais ou povos predominantes;

Celestiais, elementais, feéricos, ínferos ou mortos-vivos poderosos;

Influência de outros planos de existência;

Construções.

Por exemplo, você pode determinar a localização de mortos-vivos poderosos na área, a localização das principais fontes de água potável e a localização de quaisquer aldeias próximas.$$, $$SRD$$),
($$SRD_2014$$, $$comprehend-languages-2014$$, $$Comprehend Languages$$, $$Compreender Idiomas$$, 1, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A pinch of soot and salt.)$$, $$1 hora$$, $$Enquanto a magia durar, você entende o significado literal de qualquer idioma falado que ouvir. Você tambem entende qualquer idioma escrito que veja, mas deve tocar a superfície sobre a qual as palavras estão escritas. Demora cerca de 1 minuto para ler uma página de texto.  Esta magia não decodifica mensagens secretas em um texto ou um glifo, como um selo arcano, que não faça parte de um idioma escrito.$$, $$SRD$$),
($$SRD_2014$$, $$compulsion-2014$$, $$Compulsion$$, $$Compulsão$$, 4, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Criaturas à sua escolha, à sua vista, que estejam dentro do alcance da magia e possam ouvi-lo devem fazer uma salvaguarda de Sabedoria. Um alvo é automaticamente bem-sucedido nessa salvaguarda se não puder ser enfeitiçado. Se falhar, o alvo é afetado por esta magia. Enquanto a magia durar, você pode usar sua ação bônus em cada um dos seus turnos para designar uma direção paralela ao solo. Cada alvo afetado deve usar tanto do próprio deslocamento quanto possível para mover-se naquela direção no próximo turno dele. Ele pode realizar a própria ação antes de mover-se. Depois de se deslocar dessa maneira, o alvo pode fazer outra salvaguarda de Sabedoria para tentar encerrar o efeito.

Um alvo não é compelido a mover-se em direção a um perigo obviamente mortal, como um incêndio ou fosso, mas provoca ataques de oportunidade enquanto se move na direção designada.$$, $$SRD$$),
($$SRD_2014$$, $$cone-of-cold-2014$$, $$Cone of Cold$$, $$Cone de Frio$$, 5, $$Evocação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A small crystal or glass cone.)$$, $$Instantânea$$, $$Uma explosão de ar frio irrompe das suas mãos. Cada criatura dentro de um cone de 18 metros [60 ft.] deve fazer uma salvaguarda de Constituição. Se falhar, sofre 8d8 pontos de dano gélido, ou metade do dano em caso de sucesso.  Uma criatura morta por esta magia torna-se uma estátua congelada até derreter.   Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 5º.$$, $$SRD$$),
($$SRD_2014$$, $$confusion-2014$$, $$Confusion$$, $$Confusão$$, 4, $$Encantamento$$, $$1 ação$$, $$27 metros$$, $$V, S, M (Three walnut shells.)$$, $$Concentração, até 1 minuto$$, $$Esta magia assalta e distorce a mente das criaturas, implantando delírios e provocando ações descontroladas. Cada criatura em uma esfera de 3 metros de raio [10-foot-radius sphere], centrada em um ponto à sua escolha e dentro do alcance da magia, deve ser bem-sucedida em uma salvaguarda de Sabedoria, ou é afetada por esta magia.

Um alvo afetado não pode executar reações e precisa rolar na tabela de Confusão no início de cada um de seus próprios turnos.

Em Círculos Superiores.   Ao conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o raio da esfera aumenta em 1,5 metro [5 ft.] para cada círculo do espaço acima do 4º.$$, $$SRD$$),
($$SRD_2014$$, $$conjure-animals-2014$$, $$Conjure Animals$$, $$Conjurar Animais$$, 3, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Você invoca espíritos feéricos que assumem a forma de feras e surgem em espaços desocupados à sua vista, no alcance da magia. Escolha o que aparece entre as opções a seguir:

Uma fera com nível de desafio 2 ou menor

Duas feras com nível de desafio 1 ou menor

Quatro feras com nível de desafio 1/2 ou menor

Oito feras com nível de desafio 1/4 ou menor

Cada fera também é considerada feérica, desaparecendo ao ficar com 0 pontos de vida ou ao término da magia.

As criaturas invocadas são amistosas com você e seus companheiros. Jogue a iniciativa para as criaturas invocadas como um grupo, que tem seu próprio turno. As criaturas invocadas obedecem a qualquer comando verbal que você lhes direcione (não requer ação sua). Caso não seja dado comando algum, elas se defendem de seres hostis, não executando nenhuma outra ação.   Em Círculos Superiores.  Ao conjurar esta magia utilizando espaços de magia de círculos superiores, escolha uma das opções de invocação apresentadas anteriormente, e mais criaturas aparecem: o dobro com um espaço de 5º círculo, o triplo com um espaço de 7º círculo e o quádruplo com um espaço de 9º círculo.$$, $$SRD$$),
($$SRD_2014$$, $$conjure-celestial-2014$$, $$Conjure Celestial$$, $$Invocar Celestial$$, 7, $$Conjuração$$, $$1 minuto$$, $$27 metros$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Você invoca um celestial com nível de desafio 4 ou menor, que surge em um espaço desocupado à sua vista e no alcance da magia. O celestial desaparece ao atingir 0 pontos de vida ou ao término da magia.  O celestial é amistoso com você e seus companheiros enquanto durar a magia. Jogue a iniciativa para o celestial, que tem seus próprios turnos. O celestial obedece a qualquer comando verbal que você lhe direcione (não requer ação sua), desde que isso não viole o alinhamento dele. Caso não seja dado comando algum, ele se defende de seres hostis, não executando nenhuma outra ação.   Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 9º círculo, você convoca um celestial de nível de desafio 5 ou menor.$$, $$SRD$$),
($$SRD_2014$$, $$conjure-elemental-2014$$, $$Conjure Elemental$$, $$Conjure Elemental$$, 5, $$Conjuração$$, $$1 minuto$$, $$27 metros$$, $$V, S, M (Burning incense for air, soft clay for earth, sulfur and phosphorus for fire, or water and sand for water.)$$, $$Concentração, até 1 hora$$, $$You conjure a Large, intangible spirit from the Elemental Planes that appears in an unoccupied space within range. Choose the spirit's element, which determines its damage type: air (Lightning), earth (Thunder), fire (Fire) ou water (Cold). The spirit lasts for the duration.  Whenever a creature you can see enters the spirit's space or starts its turn within 5 feet of the spirit, you can force that creature to make a Dexterity saving throw if the spirit has no creature Restrained. On failed save, the target takes 8d8 damage of the spirit's type, and the target has the &Reference[Restrained apply=false] condition until the spell ends. At the start of each of its turns, the Restrained target repeats the save. On a failed save, the target takes 4d8 damage of the spirit's type. On a successful save, the target isn't Restrained by the spirit.   Usando Espaços de Magia de Círculo Superior.  The damage increases by 1d8 for each spell slot level above 5.$$, $$SRD$$),
($$SRD_2014$$, $$conjure-fey-2014$$, $$Conjure Fey$$, $$Conjure Fey$$, 6, $$Conjuração$$, $$1 minuto$$, $$27 metros$$, $$V, S$$, $$Concentração, até 1 hora$$, $$You conjure a Medium spirit from the Feywild in an unoccupied space you can see within range. The spirit lasts for the duration, and it looks like a Fey creature of your choice. When the spirit appears, you can make one melee spell attack against a creature within 5 feet of it. On a hit, the target takes Psychic damage equal to 3d12 plus your spellcasting ability modifier, and the target has the &Reference[Frightened] condition until the start of your next turn, with both you and the spirit as the source of the fear.  As a Bonus Action on your later turns, you can teleport the spirit to an unoccupied space you can see within 30 feet of the space it left and make the attack against a creature within 5 feet of it.   Usando Espaços de Magia de Círculo Superior.  The damage increases by 1d12 for each spell slot level above 6.$$, $$SRD$$),
($$SRD_2014$$, $$conjure-minor-elementals-2014$$, $$Conjure Minor Elementals$$, $$Conjure Minor Elementals$$, 4, $$Conjuração$$, $$1 minuto$$, $$27 metros$$, $$V, S$$, $$Concentração, até 1 hora$$, $$You conjure spirits from the Elemental Planes that flit around you in a 15-foot Emanation for the duration. Until the spell ends, any attack you make deals an extra 2d8 damage when you hit a creature in the Emanation. This damage is Acid, Cold, Fire, or Lightning (your choice when you make the attack).  In addition, the ground in the Emanation is &Reference[DifficultTerrain] for your enemies.   Usando Espaços de Magia de Círculo Superior.  The damage increases by 1d8 for each spell slot level above 4.$$, $$SRD$$),
($$SRD_2014$$, $$conjure-woodland-beings-2014$$, $$Conjure Woodland Beings$$, $$Conjure Woodland Beings$$, 4, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S, M (One holly berry per creature summoned.)$$, $$Concentração, até 1 hora$$, $$You conjure nature spirits that flit around you in a 10-foot Emanation for the duration. Whenever the Emanation enters the space of a creature you can see and whenever a creature you can see enters the Emanation or ends its turn there, you can force that creature to make a Wisdom saving throw. The creature takes 5d8 Force damage on a failed save or half as much damage on a successful one. A creature makes this save only once per turn.  In addition, you can take the &Reference[Disengage] action as a Bonus Action for the spell's duration.   Usando Espaços de Magia de Círculo Superior.  The damage increases by 1d8 for each spell slot level above 4.$$, $$SRD$$),
($$SRD_2014$$, $$contact-other-plane-2014$$, $$Contact Other Plane$$, $$Contact Other Plane$$, 5, $$Adivinhação$$, $$1 minuto$$, $$Pessoal$$, $$V$$, $$1 minuto$$, $$You mentally contact a demigod, the spirit of a long-dead sage, or some other knowledgeable entity from another plane. Contacting this otherworldly intelligence can break your mind. When you cast this spell, make a DC 15 Intelligence saving throw. On a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The DM answers each question with one word, such as "yes," "no," "maybe," "never," "irrelevant," or "unclear" (if the entity doesn't know the answer to the question). If a one-word answer would be misleading, the DM might instead offer a short phrase as an answer.  On a failed save, you take 6d6 Psychic damage and have the &Reference[Incapacitated] condition until you finish a Long Rest. A  Greater Restoration  spell cast on you ends this effect.$$, $$SRD$$),
($$SRD_2014$$, $$contagion-2014$$, $$Contagion$$, $$Contagion$$, 5, $$Necromancia$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$7 dias$$, $$Your touch inflicts a magical contagion. The target must succeed on a Constitution saving throw or take 11d8 Necrotic damage and have the &Reference[Poisoned apply=false] condition. Also, choose one ability when you cast the spell. While Poisoned, the target has Disadvantage on saving throws made with the chosen ability.  The target must repeat the saving throw at the end of each of its turns until it gets three successes or failures. If the target succeeds on three of these saves, the spell ends on the target. If the target fails three of the saves, the spell lasts for 7 days on it.  Whenever the Poisoned target receives an effect that would end the Poisoned condition, the target must succeed on a [[/save ability=con dc=@attributes.spell.dc format=long]], or the Poisoned condition doesn't end on it.$$, $$SRD$$),
($$SRD_2014$$, $$contingency-2014$$, $$Contingency$$, $$Contingência$$, 6, $$Evocação$$, $$10 minutos$$, $$Pessoal$$, $$V, S, M (A statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp.)$$, $$10 dias$$, $$Escolha uma magia de 5º círculo ou inferior que você possa conjurar, que tenha tempo de conjuração de 1 ação e que possa tê-lo como alvo. Você conjura essa magia - chamada magia contingente - como parte da conjuração de Contingência, usando espaços de magia para ambas. No entanto, a magia contingente não se efetiva. Em vez disso, ela entra em ação quando ocorrer determinada circunstância. Você descreve essa circunstância ao conjurar as duas magias. Por exemplo, uma Contingência conjurada com a magia Respirar na Água pode estipular que esta última entra em vigor quando você está envolto em água ou líquido semelhante.

A magia contingente entra em vigor imediatamente após a circunstância ocorrer pela primeira vez, independentemente da sua escolha ou vontade, e então Contingência termina.

A magia contingente afeta somente você, mesmo que ela normalmente possa ter outros alvos. Você só pode usar uma magia Contingência de cada vez. Caso conjure esta magia novamente, o efeito da Contingência anterior se encerra, o mesmo ocorrendo se o componente material para contingência já não estiver em sua posse.$$, $$SRD$$),
($$SRD_2014$$, $$continual-flame-2014$$, $$Continual Flame$$, $$Chama Contínua$$, 2, $$Evocação$$, $$1 ação$$, $$Toque$$, $$V, S, M (Ruby dust worth 50 gp, which the spell consumes.)$$, $$Até ser dissipada$$, $$Uma chama, brilhante como uma tocha, surge de um objeto que você toca. O efeito assemelha-se ao de uma chama comum, exceto pelo fato de não emitir calor nem consumir oxigênio. Uma chama contínua pode ser coberta ou escondida, mas não apagada ou abafada.$$, $$SRD$$),
($$SRD_2014$$, $$control-water-2014$$, $$Control Water$$, $$Controlar Água$$, 4, $$Transmutação$$, $$1 ação$$, $$90 metros$$, $$V, S, M (A drop of water and a pinch of dust.)$$, $$Concentração, até 10 minutos$$, $$Você controla qualquer corpo de água parada dentro de uma área à sua escolha, em um cubo de 30 metros [100 ft.] de lado e enquanto esta magia durar. Você pode escolher entre qualquer um dos efeitos a seguir. Ao conjurar esta magia com uma ação em seu turno, você pode repetir o mesmo efeito ou pode escolher outro.

Inundação.  Você provoca o aumento do nível de toda a água parada na área, que sobe até 6 metros [20 ft.]. Se a área inclui uma margem, a água transborda sobre a terra seca. Caso você tenha escolhido uma área em um grande corpo de água, em vez de uma inundação, você cria uma onda de 6 metros [20 ft.] de altura que viaja de um lado da área para o outro, até quebrar. Quaisquer veículos de tamanho Grande ou menor no caminho da onda são carregados com ela para o outro lado. Quaisquer veículos de tamanho Grande ou menor atingidos pela onda têm 25% de chance de emborcar.

O nível da água permanece elevado enquanto a magia durar ou caso você escolha um efeito diferente. Se este efeito produziu uma onda, ela se repete no início do seu próximo turno, enquanto durar o efeito da inundação.

Dividir a Água.  Você faz com que a água na área se afaste e crie uma trincheira que se estende por toda a área da magia, com a água afastada formando uma parede em cada lado. A trincheira permanece enquanto a magia durar ou até que você escolha um efeito diferente. A água, então, lentamente preenche a trincheira ao longo da próxima rodada, até que o nível normal da água seja restaurado.

Redirecionar Fluxo.  Você faz o fluxo de água na área mover-se na direção que você escolher, mesmo que a água tenha que fluir entre obstáculos, subir paredes ou seguir em outras direções improváveis. A água na área move-se de acordo com o seu direcionamento, mas tendo ultrapassado a área da magia, ela retoma o fluxo natural, de acordo com as condições do terreno. A água continua a mover-se na direção que você escolheu enquanto a magia durar ou até que você escolha um efeito diferente.

Redemoinho.  Este efeito requer um corpo d'água de pelo menos 15 metros [50 ft.] quadrados e 7,5 metros [25 ft.] de profundidade. Você provoca a formação de um redemoinho no centro da área. O redemoinho forma um vórtice que tem 1,5 metro [5 ft.] de base, até 15 metros [50 ft.] de largura no topo e 7,5 metros [25 ft.] de altura. Qualquer criatura ou objeto na água e a cerca de 7,5 metros [25 ft.] do vórtice é puxado 3 metros [10 ft.] em direção a ele. Uma criatura pode nadar para longe do vórtice sendo bem-sucedida em um teste de Força (Atletismo) contra a CD para evitar sua magia.

Quando uma criatura entra no vórtice pela primeira vez durante um turno ou inicia o turno ali, ela deve fazer uma salvaguarda de Força. Se falhar, sofre 2d8 pontos de dano contundente, sendo aprisionada no vórtice enquanto a magia durar. Em caso de sucesso, sofre metade do dano e não é aprisionada no vórtice. Uma criatura capturada no vórtice pode usar uma ação para tentar nadar para longe dele, como descrito anteriormente, mas tem desvantagem no teste de Força (Atletismo) para fazê-lo.

Quando um objeto entra no vórtice pela primeira vez durante um turno, ele sofre 2d8 pontos de dano contundente; esse dano ocorre a cada rodada em que o objeto permanecer no vórtice.$$, $$SRD$$),
($$SRD_2014$$, $$control-weather-2014$$, $$Control Weather$$, $$Control Weather$$, 8, $$Transmutação$$, $$10 minutos$$, $$Pessoal$$, $$V, S, M (Burning incense and bits of earth and wood mixed in water.)$$, $$Concentração, até 8 horas$$, $$You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell, and it ends early if you go indoors.  When you cast the spell, you change the current weather conditions, which are determined by the DM. You can change precipitation, temperature, and wind. It takes 1d4 × 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal.  When you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.    Precipitation      Stage  Condition      1  Clear    2  Light clouds    3  Overcast or ground fog    4  Rain, hail, or snow    5  Torrential rain, driving hail, or blizzard        Temperature      Stage  Condition      1  Heat wave    2  Hot    3  Warm    4  Cool    5  Cold    6  Freezing        Wind      Stage  Condition      1  Calm    2  Moderate wind    3  Strong wind    4  Gale    5  Storm$$, $$SRD$$),
($$SRD_2014$$, $$counterspell-2014$$, $$Counterspell$$, $$Counterspell$$, 3, $$Abjuração$$, $$1 reação$$, $$18 metros$$, $$S$$, $$Instantânea$$, $$You attempt to interrupt a creature in the process of casting a spell. The creature makes a Constitution saving throw. On a failed save, the spell dissipates with no effect, and the action, Bonus Action, or Reaction used to cast it is wasted. If that spell was cast with a spell slot, the slot isn't expended.$$, $$SRD$$),
($$SRD_2014$$, $$create-food-and-water-2014$$, $$Create Food and Water$$, $$Create Food and Water$$, 3, $$Conjuração$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Instantânea$$, $$You create 45 pounds of food and 30 gallons of fresh water on the ground or in containers within range—both useful in fending off the hazards of malnutrition and dehydration. The food is bland but nourishing and looks like a food of your choice, and the water is clean. The food spoils after 24 hours if uneaten.$$, $$SRD$$),
($$SRD_2014$$, $$create-undead-2014$$, $$Create Undead$$, $$Create Undead$$, 6, $$Necromancia$$, $$1 minuto$$, $$3 metros$$, $$V, S, M (One clay pot filled with grave dirt, one clay pot filled with brackish water, and one 150 gp black onyx stone for each corpse.)$$, $$Instantânea$$, $$You can cast this spell only at night. Choose up to three corpses of Medium or Small Humanoids within range. Each one becomes a  Ghoul  under your control (see the  Monster Manual  for its stat block).  As a Bonus Action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to them). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a particular place. If you issue no commands, the creature takes the &Reference[Dodge] action and moves only to avoid harm. Once given an order, the creature continues to follow the order until its task is complete.  The creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell rather than animating new ones.   Usando Espaços de Magia de Círculo Superior. If you use a level 7 spell slot, you can animate or reassert control over four  Ghouls . If you use a level 8 spell slot, you can animate or reassert control over five  Ghouls  or two  Ghasts  or  Wights . If you use a level 9 spell slot, you can animate or reassert control over six  Ghouls , three  Ghasts  or  Wights , or two  Mummies . See the  Monster Manual  for these stat blocks.$$, $$SRD$$),
($$SRD_2014$$, $$create-or-destroy-water-2014$$, $$Create or Destroy Water$$, $$Create or Destroy Water$$, 1, $$Transmutação$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A drop of water if creating water, or a few grains of sand if destroying it.)$$, $$Instantânea$$, $$You do one of the following:   Create Water.  You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot Cube within range, extinguishing exposed flames there.   Destroy Water.  You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot Cube within range.   Usando Espaços de Magia de Círculo Superior.  You create or destroy 10 additional gallons of water, or the size of the Cube increases by 5 feet, for each spell slot level above 1.$$, $$SRD$$),
($$SRD_2014$$, $$creation-2014$$, $$Creation$$, $$Creation$$, 5, $$Ilusão$$, $$1 minuto$$, $$9 metros$$, $$V, S, M (A tiny piece of matter of the same type of the item you plan to create.)$$, $$Especial$$, $$You pull wisps of shadow material from the Shadowfell to create an object within range. It is either an object of vegetable matter (soft goods, rope, wood, and the like) or mineral matter (stone, crystal, metal, and the like). The object must be no larger than a 5-foot Cube, and the object must be of a form and material that you have seen.  The spell's duration depends on the object's material, as shown in the Materials table. If the object is composed of multiple materials, use the shortest duration. Using any object created by this spell as another spell's Material component causes the other spell to fail.     Material  Duration      Vegetable matter  24 hours    Stone or crystal  12 hours    Precious metals  1 hour    Gems  10 minutes    Adamantine or mithral  1 minute      Usando Espaços de Magia de Círculo Superior.  The Cube increases by 5 feet for each spell slot level above 5.$$, $$SRD$$),
($$SRD_2014$$, $$cure-wounds-2014$$, $$Cure Wounds$$, $$Curar Ferimentos$$, 1, $$Evocação$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Instantânea$$, $$Uma criatura que você toca recupera um número de Pontos de Vida igual a 2d8 mais seu modificador de atributo de conjuração.   Usando Espaços de Magia de Círculo Superior.  A cura aumenta em 2d8 para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$dancing-lights-2014$$, $$Dancing Lights$$, $$Luzes Dançantes$$, 0, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S, M (A bit of phosphorus or wychwood, or a glowworm.)$$, $$Concentração, até 1 minuto$$, $$Você cria até quatro luzes do tamanho de tochas no alcance da magia, fazendo com que elas pareçam tochas, lanternas ou esferas brilhantes que pairam pela duração da magia. Como alternativa, você combina as quatro luzes em uma forma Média, brilhante, a qual é vagamente humanoide. Seja qual for a forma que você escolher, cada luz emite Meia-luz em um raio de 3 metros.  Como uma Ação Bônus, você pode mover as luzes até 18 metros para um espaço no alcance da magia. Uma luz deve estar a até 6 metros de outra luz criada por esta magia, e uma luz desaparece se ultrapassar o alcance da magia.$$, $$SRD$$),
($$SRD_2014$$, $$darkness-2014$$, $$Darkness$$, $$Darkness$$, 2, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V, M (Bat fur and a drop of pitch or piece of coal.)$$, $$Concentração, até 10 minutos$$, $$For the duration, magical &Reference[darkness] spreads from a point within range and fills a 15-foot-radius Sphere. Darkvision can't see through it, and nonmagical light can't illuminate it.  Alternatively, you cast the spell on an object that isn't being worn or carried, causing the Darkness to fill a 15-foot Emanation originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the Darkness.  If any of this spell's area overlaps with an area of Bright Light or Dim Light created by a spell of level 2 or lower, that other spell is dispelled.$$, $$SRD$$),
($$SRD_2014$$, $$darkvision-2014$$, $$Darkvision$$, $$Darkvision$$, 2, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (Either a pinch of dried carrot or an agate.)$$, $$8 horas$$, $$For the duration, a willing creature you touch has &Reference[darkvision] with a range of 150 feet.$$, $$SRD$$),
($$SRD_2014$$, $$daylight-2014$$, $$Daylight$$, $$Luz do Dia$$, 3, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$1 hora$$, $$Uma esfera de luz com raio de 18 metros [60 ft.] se expande a partir de um ponto à sua escolha e no alcance da magia. A esfera é de luz plena e emite meia-luz por mais 18 metros [60 ft.].  Se o ponto escolhido for um objeto que você está segurando ou que não esteja sendo usado ou carregado, a luz brilha a partir do objeto e move-se com ele. Cobrir completamente o objeto afetado com algo opaco, como uma tigela ou um elmo, bloqueia a luz.  Se qualquer área desta magia se sobrepuser a uma área de escuridão criada por uma magia de 3º círculo ou inferior, a magia que criou a escuridão é anulada.$$, $$SRD$$),
($$SRD_2014$$, $$death-ward-2014$$, $$Death Ward$$, $$Proteção Contra Morte$$, 4, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$8 horas$$, $$Ao tocar uma criatura você lhe concede alguma medida de proteção contra a morte.  Na primeira vez que ela sofrer dano e isso reduzir-lhe os pontos de vida a 0, ela volta a ter 1 ponto de vida e a magia termina.  Se a magia ainda estiver em ação quando a criatura for submetida a um efeito que a mataria instantaneamente sem causar dano, esse efeito é anulado e a magia termina.$$, $$SRD$$),
($$SRD_2014$$, $$delayed-blast-fireball-2014$$, $$Delayed Blast Fireball$$, $$Bola de Fogo Adiável$$, 7, $$Evocação$$, $$1 ação$$, $$45 metros$$, $$V, S, M (A tiny ball of bat guano and sulfur.)$$, $$Concentração, até 1 minuto$$, $$Um facho de luz amarela dispara do seu dedo em riste, condensando-se na forma de uma conta brilhante num ponto escolhido dentro do alcance da magia por toda a duração. Quando a magia se encerra, seja porque sua concentração foi quebrada ou por decisão sua, a conta desabrocha, com um rugido baixo, em uma explosão de chamas que se alastram pelos cantos. Cada criatura em uma esfera com raio de 6 metros [20-foot-radius sphere] centrada na conta deve fazer uma salvaguarda de Destreza. Se falhar, sofre dano ígneo equivalente ao total acumulado de dano, ou metade do dano, em caso de sucesso.

O dano base da magia é 12d6. Se ao final do seu turno a conta ainda não tiver sido detonada, o dano aumenta em 1d6.

Se a conta brilhante for tocada antes que o intervalo expire, a criatura que a tocar precisa fazer uma salvaguarda de Destreza. Se falhar, a magia encerra imediatamente e a conta explode em chamas; se for bem-sucedida, a criatura pode arremessar a conta a até 12 metros [40 ft.] de distância. Se a conta atingir uma criatura ou objeto sólido, a magia se encerra e ela explode.

O fogo danifica objetos na área e incendeia objetos inflamáveis que não estejam sendo usados ou carregados.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 8º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 7º.$$, $$SRD$$),
($$SRD_2014$$, $$demiplane-2014$$, $$Demiplane$$, $$Semiplano$$, 8, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$S$$, $$1 hora$$, $$Você cria uma porta de sombras em uma superfície sólida e plana, à sua vista e dentro do alcance da magia. A porta é grande o suficiente para permitir que uma criatura Média passe sem impedimento. Quando aberta, a porta leva para um semiplano que parece ser um quarto vazio, com 9 metros [30 ft.] em cada dimensão, feito de madeira ou pedra. Quando a magia termina, a porta desaparece e quaisquer criaturas ou objetos dentro do semiplano ficam presos ali, já que a porta também desaparece do outro lado.  Todas as vezes que conjurar esta magia, você pode criar um novo semiplano ou fazer a porta de sombras se conectar a um semiplano que tenha criado em uma conjuração anterior desta magia. Além disso, se você conhecer a natureza e o conteúdo de um semiplano criado por uma conjuração desta magia por outra criatura, você pode fazer a porta de sombras se conectar a esse semiplano e não ao seu.$$, $$SRD$$),
($$SRD_2014$$, $$detect-evil-and-good-2014$$, $$Detect Evil and Good$$, $$Detectar o Bem e o Mal$$, 1, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Enquanto a magia durar, você pode sentir a presença e localização de uma criatura do tipo aberração, celestial, elemental, feérico, ínfero ou morto-vivo que encontre-se a até 9 metros [30 ft.] de distância. Da mesma forma, você sabe se existe um lugar ou objeto a até 9 metros [30 ft.] que tenha sido magicamente consagrado ou profanado.  A magia pode atravessar a maioria das barreiras, sendo bloqueada, no entanto, por 30 centímetros [1 foot] de pedra, 2,5 centímetros [1 inch] de metal comum, uma folha fina de chumbo ou 1 metro [3 ft.] de madeira ou terra.$$, $$SRD$$),
($$SRD_2014$$, $$detect-magic-2014$$, $$Detect Magic$$, $$Detectar Magia$$, 1, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Pela duração da magia, você sente a presença de efeitos mágicos a até 9 metros de você. Se você sentir tais efeitos, pode realizar uma ação mágica para ver uma aura fraca ao redor de qualquer criatura ou objeto visível na área que contém a magia, e se um efeito foi criado por uma magia, você descobre a escola dessa magia.  A magia é bloqueada por 30 centímetros de pedra, terra ou madeira, 2,5 centímetros de metal ou uma folha fina de chumbo.$$, $$SRD$$),
($$SRD_2014$$, $$detect-poison-and-disease-2014$$, $$Detect Poison and Disease$$, $$Detectar Veneno e Doença$$, 1, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A yew leaf.)$$, $$Concentração, até 10 minutos$$, $$Enquanto a magia durar, você pode sentir a presença e a localização de venenos, criaturas venenosas e doenças a até 9 metros [30 ft.] de distância. Você também pode identificar o tipo de veneno, criatura venenosa ou doença em cada caso.  A magia pode atravessar a maioria das barreiras, sendo bloqueada, no entanto, por 30 centímetros [1 foot] de pedra, 2,5 centímetros [1 inch] de metal comum, uma folha fina de chumbo ou 1 metro [3 ft.] de madeira ou terra.$$, $$SRD$$),
($$SRD_2014$$, $$detect-thoughts-2014$$, $$Detect Thoughts$$, $$Detectar Pensamentos$$, 2, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A copper coin.)$$, $$Concentração, até 1 minuto$$, $$Enquanto a magia durar, você pode ler os pensamentos de certas criaturas. Ao conjurar esta magia, e com uma ação em cada um de seus turnos enquanto a magia durar, você pode focar sua mente em qualquer criatura à sua vista e que esteja a até 9 metros [30 ft.] de distância de você. Se a criatura que você escolher tiver uma Inteligência igual ou menor que 3, ou não falar qualquer idioma, ela não é afetada.  Inicialmente, você descobre os pensamentos superficiais da criatura - o que está mais evidente na mente dela naquele momento. Com uma ação, você pode mudar sua atenção para os pensamentos de outra criatura ou tentar sondar mais profundamente a mente da mesma criatura. Se sondar mais profundamente, o alvo deve fazer uma salvaguarda de Sabedoria. Se falhar, você ganha acesso aos raciocínios (se houver), estado emocional e qualquer coisa que ocupe grande parte da mente dele (como alguma coisa com a qual ele se preocupa, ame ou odeie). Se o alvo for bem-sucedido, a magia se encerra. De qualquer forma, o alvo sabe que você está sondando a mente dele e, a menos que você mude sua atenção para os pensamentos de outra criatura, a criatura pode usar uma ação para fazer um teste de Inteligência resistido por um teste de Inteligência seu; se ela for bem-sucedida, a magia se encerra.  Perguntas verbais dirigidas à criatura alvo moldam naturalmente o curso dos pensamentos dela, o que torna esta magia particularmente eficaz como parte de um interrogatório.  Você também pode usar esta magia para detectar a presença de criaturas pensantes que você não possa ver. Ao conjurar esta magia ou como sua ação, enquanto a magia durar, você pode procurar por pensamentos em uma área de 9 metros [30 ft.] de distância de você. A magia pode penetrar barreiras,sendo bloqueada, no entanto, por 60 centímetros [2 ft.] de rocha, 5 centímetros [2 inches] de qualquer metal ou uma folha fina de chumbo. Você não pode detectar uma criatura com Inteligência igual a 3 ou menor, ou que não fale nenhum idioma.  Depois de detectar a presença de uma criatura desse modo, você pode ler os pensamentos dela pelo restante da duração da magia, conforme descrito acima, mesmo que não possa vê-la, embora ela ainda precise estar dentro do alcance da magia.$$, $$SRD$$),
($$SRD_2014$$, $$dimension-door-2014$$, $$Dimension Door$$, $$Porta Dimensional$$, 4, $$Conjuração$$, $$1 ação$$, $$150 metros$$, $$V$$, $$Instantânea$$, $$Você pode se teleportar a partir de sua localização atual para qualquer outro local dentro do alcance da magia. Você chega exatamente no local desejado. Pode se tratar de um lugar que você possa ver, visualizar ou descrever, relatando a distância e a direção, como "60 metros [200 ft.] em linha reta para baixo" ou "para cima e para o noroeste a um ângulo de 45 graus, a 90 metros [300 ft.]."

Você pode levar consigo objetos, desde que o peso deles não exceda aquele que você consiga carregar. Você também pode levar uma criatura voluntária, do seu tamanho ou menor, que esteja portando equipamentos até a capacidade de carga dela. A criatura deve estar a até 1,5 metro [5 ft.] de você quando você conjurar esta magia.

Se você ou qualquer criatura que você leve junto chegarem a um local ocupado por um objeto ou outra criatura, sofrerão, cada, 4d6 pontos de dano energético, e a magia falha em teleportá-los.$$, $$SRD$$),
($$SRD_2014$$, $$disguise-self-2014$$, $$Disguise Self$$, $$Disfarçar-se$$, 1, $$Ilusão$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$1 hora$$, $$Você faz com que você mesmo - incluindo suas roupas, armaduras, armas e outros pertences que esteja carregando - ganhe outra aparência, enquanto a magia durar ou até que você use sua ação para encerrá-la. Você pode parecer 30 centímetros [1 ft.] mais baixo ou mais alto, e parecer magro, gordo ou algo entre os dois. Você não pode alterar o seu tipo de corpo, portanto, deve adotar uma forma que tenha a mesma disposição básica de membros. No mais, a extensão da ilusão cabe a você.  As alterações feitas por esta magia não se sustentam diante de uma inspeção física. Por exemplo, se você usar esta magia para adicionar um chapéu à sua indumentária, objetos atravessam o chapéu, e quem o tocar não sentirá nada ou sentirá sua cabeça e cabelos. Se você usar esta magia para parecer mais magro do que é, alguém que estenda a mão para tocá-lo pode esbarrar em você enquanto ela ainda estiver, aparentemente, tocando o ar.  Para descobrir que você está disfarçado, uma criatura pode usar a ação dela para inspecionar sua aparência, devendo ser bem-sucedida em um teste de Inteligência (Investigação) contra a CD para evitar sua magia.$$, $$SRD$$),
($$SRD_2014$$, $$disintegrate-2014$$, $$Disintegrate$$, $$Desintegrar$$, 6, $$Transmutação$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A lodestone and a pinch of dust.)$$, $$Instantânea$$, $$Um pequeno raio verde sai da ponta do seu dedo, dirigindo-se a um alvo à sua vista, no alcance da magia. O alvo deve ser uma criatura, um objeto ou uma criação de força mágica, como a barreira criada por Muralha de Energia.

Uma criatura atingida por esta magia deve fazer uma salvaguarda de Destreza. Se falhar, o alvo sofre 10d6+40 pontos de dano energético, sendo desintegrado caso seus pontos de vida sejam reduzidos a 0.

Uma criatura desintegrada e tudo que ela estiver usando e carregando, exceto itens mágicos, são reduzidos a uma pilha de poeira cinza. A criatura pode ter a vida restaurada apenas por meio da magia true Ressurreição Verdadeira ou Desejo.

Esta magia desintegra automaticamente um objeto não mágico de tamanho Grande ou menor ou uma criação de força mágica. Se o alvo for um objeto ou criação de força mágica de tamanho Enorme ou maior, esta magia desintegra uma porção equivalente a um cubo de 3 metros [10-foot cube] de lado dela. Itens mágicos não são afetados por esta magia.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 7º círculo ou superior, o dano da magia aumenta em 3d6 para cada círculo do espaço acima do 6º.$$, $$SRD$$),
($$SRD_2014$$, $$dispel-evil-and-good-2014$$, $$Dispel Evil and Good$$, $$Dissipar o Bem e o Mal$$, 5, $$Abjuração$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (Holy water or powdered silver and iron.)$$, $$Concentração, até 1 minuto$$, $$Uma energia cintilante o envolve e protege contra feéricos, mortos-vivos e criaturas originárias de além do Plano Material. Enquanto a magia durar, celestiais, elementais, feéricos, ínferos e mortos-vivos têm desvantagem nas jogadas de ataque contra você.

Você pode encerrar precocemente a magia usando qualquer uma das funções especiais abaixo.

Quebrar Encantamento.  Utilize sua ação para tocar uma criatura, dentro do alcance da magia, que esteja amedrontada, enfeitiçada ou possuída por um celestial, elemental, feérico, ínfero ou morto-vivo. A criatura tocada não está mais encantada, amedrontada ou possuída por tais criaturas.

Regressar.  Utilize sua ação para executar um ataque mágico corpo a corpo contra um celestial, elemental, feérico, ínfero ou morto-vivo ao seu alcance. Em caso de sucesso, você força a criatura a retornar ao próprio plano de origem. Ela deve ser bem-sucedida em uma salvaguarda de Carisma ou é mandada de volta (se já não estiver lá). Caso já não estejam nos próprios planos, mortos-vivos são enviados para o Sombral e feéricos para a Faéria.$$, $$SRD$$),
($$SRD_2014$$, $$dispel-magic-2014$$, $$Dispel Magic$$, $$Dissipar Magia$$, 3, $$Abjuração$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Instantânea$$, $$Escolha uma criatura, objeto ou efeito mágico no alcance da magia. Quaisquer magias de 3º círculo ou inferiores que afetam o alvo se encerram. Para cada magia de 4º círculo ou superior que esteja afetando o alvo, faça um teste de atributo usando seu atributo de conjuração. A CD é igual a 10 + o círculo desta magia. Em caso de sucesso, a magia se encerra.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, você automaticamente encerra os efeitos de uma magia que esteja afetando o alvo, se o círculo da magia for igual ou menor ao círculo do espaço de magia que você usou.$$, $$SRD$$),
($$SRD_2014$$, $$divination-2014$$, $$Divination$$, $$Presságio$$, 4, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (Incense and a sacrificial offering appropriate to your religion, together worth at least 25gp, which the spell consumes.)$$, $$Instantânea$$, $$Sua magia e uma oferenda colocam-no em contato com um deus ou um dos servos dele. Você faz uma única pergunta a respeito de um objetivo específico, evento ou atividade que ocorrerá no prazo de 7 dias. O DM oferece uma resposta verdadeira. A resposta pode ser uma frase curta, uma rima enigmática ou um presságio.  A magia não leva em conta quaisquer circunstâncias que possam mudar o resultado futuro, como a conjuração de magias adicionais ou a perda ou chegada de um companheiro.  Se você conjurar a magia duas ou mais vezes antes de concluir seu próximo descanso longo, há uma chance cumulativa de 25% para cada conjuração após a primeira de você obter uma resposta aleatória. O DM faz essa jogada em segredo.$$, $$SRD$$),
($$SRD_2014$$, $$divine-favor-2014$$, $$Divine Favor$$, $$Favor Divino$$, 1, $$Evocação$$, $$1 ação bônus$$, $$Pessoal$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Sua oração o fortalece com o resplendor divino. Enquanto a magia durar, seus ataques com armas causam 1d4 pontos de dano radiante adicional em caso de acerto.$$, $$SRD$$),
($$SRD_2014$$, $$divine-word-2014$$, $$Divine Word$$, $$Palavra Sagrada$$, 7, $$Evocação$$, $$1 ação bônus$$, $$9 metros$$, $$V$$, $$Instantânea$$, $$Você profere uma palavra sagrada, imbuída com o poder que moldou o mundo na aurora da criação. Escolha qualquer número de criaturas à sua vista, no alcance da magia. Cada criatura que puder ouvi-lo deve fazer uma salvaguarda de Carisma. Se falhar, uma criatura sofre um efeito baseado nos pontos de vida atuais dela:

50 pontos de vida ou menos: surda por 1 minuto

40 pontos de vida ou menos: surda e cega por 10 minutos

30 pontos de vida ou menos: cega, surda e atordoada por 1 hora

20 pontos de vida ou menos: morta instantaneamente

Independentemente dos seus pontos de vida atuais, um celestial, elemental, feérico ou ínfero que falhe na salvaguarda é forçado a voltar para o plano de origem dele (se já não estiver lá), não podendo voltar ao seu plano atual durante 24 horas por qualquer meio inferior à magia Desejo.$$, $$SRD$$),
($$SRD_2014$$, $$dominate-beast-2014$$, $$Dominate Beast$$, $$Dominar Fera$$, 4, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você tenta cativar uma fera à sua vista, dentro do alcance da magia. Ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou fica enfeitiçada enquanto durar a magia. Se você ou criaturas amigáveis a você estiverem lutando contra a fera, ela tem vantagem na salvaguarda.

Você possui um elo telepático com a criatura, permanecendo conectados enquanto ela estiver enfeitiçada e ambos estejam no mesmo plano de existência. Você pode usar este elo telepático para enviar comandos para a criatura, enquanto você estiver consciente (nenhuma ação é necessária) e ela faz o possível para obedecer. Pode ser especificado um curso de ação genérico e simples, como "Ataque aquela criatura", "Corra para cá" ou "Pegue aquele objeto". Se a criatura completar a ordem e não receber novas instruções suas, ela se defende e se preserva o melhor que puder.

Você pode usar sua ação para assumir controle total e preciso do alvo. Até o fim do seu turno, a criatura executa apenas as ações que você escolher e não faz nada que você não permita. Durante esse tempo, você também pode fazer com que a criatura use a reação dela, mas isso requer que você use sua reação também.

Toda vez que o alvo sofrer dano, ele deve fazer uma nova salvaguarda de Sabedoria contra CD para evitar a sua magia. Em caso de sucesso, a magia se encerra.

Em Círculos Superiores.  Ao conjurar esta magia com um espaço de magia de 5º círculo, a duração será concentração, até 10 minutos. Ao conjurar esta magia com um espaço de magia de 6º círculo, a duração será concentração, até 1 hora. Ao conjurar esta magia utilizando um espaço de magia de 7º círculo, a duração será concentração, até 8 horas.$$, $$SRD$$),
($$SRD_2014$$, $$dominate-monster-2014$$, $$Dominate Monster$$, $$Dominar Monstro$$, 8, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Você tenta cativar uma criatura à sua vista e no alcance da magia. Ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou fica enfeitiçada enquanto a magia durar. Se você ou criaturas amigáveis a você estiverem lutando contra a criatura alvo, ela tem vantagem na salvaguarda.

Você possui um elo telepático com a criatura, permanecendo conectados enquanto ela estiver enfeitiçada e ambos estejam no mesmo plano de existência. Você pode usar este elo telepático para enviar comandos para a criatura, enquanto você estiver consciente (nenhuma ação é necessá­ria) e ela faz o possível para obedecer. Pode ser especificado um curso de ação genérico e simples, como "Ataque aquela criatura", "Corra para cá" ou "Pegue aquele objeto". Se a criatura completar a ordem e não receber novas instruções suas, ela se defende e se preserva o melhor que puder.

Você pode usar sua ação para assumir controle total e preciso do alvo. Até o fim do seu turno, a criatura executa apenas as ações que você escolher e não faz nada que você não permita. Durante esse tempo, você também pode fazer com que a criatura use a reação dela, mas isso requer que você use sua reação também.

Toda vez que o alvo sofrer dano, ele deve fazer uma nova salvaguarda de Sabedoria contra CD para evitar a sua magia. Em caso de sucesso, a magia se encerra.

Em Círculos Superiores.  Ao conjurar esta magia com um espaço de magia de 9º círculo, a duração será de concentração, até 8 horas.$$, $$SRD$$),
($$SRD_2014$$, $$dominate-person-2014$$, $$Dominate Person$$, $$Dominar Pessoa$$, 5, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você tenta influenciar um humanoide à sua vista no alcance da magia. Ele deve ser bem-sucedido em uma salvaguarda de Sabedoria ou está enfeitiçado por você enquanto a magia durar. Se você ou criaturas amigáveis a você estiverem lutando contra o alvo, ele tem vantagem na salvaguarda.

Enquanto o alvo estiver enfeitiçado, você tem um elo telepático com ele desde que ambos estejam no mesmo plano de existência. Enquanto estiver consciente, você pode usar o elo telepático para enviar comandos para a criatura (nenhuma ação é necessária), que faz o possível para obedecer. Você pode especificar um curso de ação genérico e simples, como "Ataque aquela criatura", "Corra para cá" ou "Pegue aquele objeto". Se a criatura completar a ordem e não receber novas instruções suas, ela se defende e se preserva o melhor que puder.

Você pode usar sua ação para assumir controle total e preciso do alvo. Até o fim do seu turno, a criatura executa apenas as ações que você escolher e não faz nada que você não permita. Durante esse tempo, você também pode fazer com que a criatura use a reação dela, mas isso requer que você use sua reação também.

Toda vez que o alvo sofre dano, ele faz uma salvaguarda de Sabedoria contra a magia. Em caso de sucesso, a magia se encerra.

Em Círculos Superiores.  Ao conjurar esta magia com um espaço de magia de 6º círculo, a duração será concentração, até 10 minutos. Ao conjurar esta magia com um espaço de magia de 7º círculo, a duração será concentração, até 1 hora. Ao conjurar esta magia com um espaço de magia de 8º círculo, a duração será concentração, até 8 horas.$$, $$SRD$$),
($$SRD_2014$$, $$dream-2014$$, $$Dream$$, $$Sonho$$, 5, $$Ilusão$$, $$1 minuto$$, $$Especial$$, $$V, S, M (A handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird.)$$, $$8 horas$$, $$Esta magia molda os sonhos de uma criatura. Escolha uma criatura conhecida como alvo. Ela deve estar no mesmo plano de existência que você. Criaturas que não dormem, como elfos, não podem ser contatadas por esta magia. Você ou uma criatura voluntária tocada por você, entra em um estado de transe, atuando como mensageira. Enquanto estiver em transe, o mensageiro está ciente do que acontece ao redor dele, mas não pode executar ações ou mover-se.  Se o alvo estiver dormindo, o mensageiro aparece nos sonhos dele e, enquanto a magia durar e o sono persistir, pode conversar com ele. O mensageiro também pode moldar o ambiente do sonho, criando paisagens, objetos e outras imagens, podendo ainda sair do transe a qualquer momento, o que encerra previamente o efeito da magia. O alvo recorda perfeitamente o sonho ao acordar. Se o alvo estiver acordado quando você conjurar a magia, o mensageiro ficará ciente, podendo terminar o transe (e a magia), ou aguardar o alvo cair no sono até o ponto no qual ele aparece nos sonhos do alvo.  Você pode fazer o mensageiro parecer monstruoso e aterrador para o alvo. Se fizer isso, o mensageiro só poderá entregar uma mensagem com não mais do que dez palavras e, em seguida, o alvo deverá fazer uma salvaguarda de Sabedoria. Se falhar, ecos da monstruosidade fantasmagórica geram um pesadelo que dura por todo o tempo de sono, impedindo o alvo de obter qualquer benefício com o descanso. Além disso, quando o alvo acorda, sofre 3d6 pontos de dano psíquico.  Caso você tenha uma parte do corpo do alvo, tal como uma mecha de cabelo, pedaço de unha, pele ou parte semelhante, a salvaguarda é feita com desvantagem.$$, $$SRD$$),
($$SRD_2014$$, $$druidcraft-2014$$, $$Druidcraft$$, $$Arte Druídica$$, 0, $$Transmutação$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Instantânea$$, $$Sussurrando para os espíritos da natureza, você cria um dos seguintes efeitos no alcance da magia.   Sensor Meterológico.  Você cria um efeito sensorial minúsculo e inofensivo que prevê qual será o clima no local onde você está pelas próximas 24 horas. O efeito pode se manifestar como uma esfera dourada para céu claro, uma nuvem para chuva, flocos de neve caindo para neve e assim por diante. Esse efeito persiste por 1 rodada.   Florescer.  Você instantaneamente faz uma flor desabrochar, uma vagem se abrir ou um botão de folha se abrir.   Efeito Sensorial.  Você cria um efeito sensorial inofensivo, como folhas caindo, fadas dançantes espectrais, uma brisa suave, o som de um animal ou o leve odor de gambá. O efeito deve caber em um Cubo de 1,5 metro de lado.   Brincar com Fogo.  Você acende ou apaga uma vela, uma tocha ou uma fogueira.$$, $$SRD$$),
($$SRD_2014$$, $$earthquake-2014$$, $$Earthquake$$, $$Terremoto$$, 8, $$Evocação$$, $$1 ação$$, $$150 metros$$, $$V, S, M (A pinch of dirt, a piece of rock, and a lump of clay.)$$, $$Concentração, até 1 minuto$$, $$Você pode criar uma perturbação sísmica em um ponto no chão, à sua vista e no alcance da magia. Enquanto a magia durar, um intenso tremor rasga o chão em um círculo com raio de 30 metros [100-foot radius] centrado nesse ponto, sacudindo as criaturas e estruturas em contato com o solo nessa área.  O terreno na área se torna terreno difícil. Cada criatura em solo afetado e que esteja se concentrando, deve fazer uma salvaguarda de Constituição. Se falhar, a criatura terá a concentração quebrada.  Ao conjurar esta magia, e ao final de cada turno que gastar concentrando-se nela, cada criatura no solo da área deve fazer uma salvaguarda de Destreza. Se falhar, a criatura ficará caída.  Esta magia pode ter efeitos adicionais, dependendo do terreno na área, conforme determinado pelo DM.   Fissuras . Fissuras se abrem por toda a área da magia no início de seu próximo turno, após você ter conjurado a magia. Um total de 1d6 fissuras se abrem em locais escolhidos pelo DM. Cada uma possui 1d10 x 3 metros [10 ft.] de profundidade, 3 metros [10 ft.] de largura, e estendem-se de uma borda da área da magia até o lado oposto. Uma criatura em pé em um lugar onde a fissura se abre deve ser bem-sucedida em uma salvaguarda de Destreza ou cairá nela. Uma criatura bem-sucedida move-se com a borda da fissura quando esta se abre.  Uma fissura que se abre debaixo de uma estrutura provoca automaticamente o seu colapso (veja a seguir).   Estruturas . Assim que você conjura a magia e no começo de cada um dos seus turnos, enquanto a magia durar, o tremor causa 50 pontos de dano contundente em qualquer estrutura em contato com o chão na área atingida. Se uma estrutura chegar a 0 pontos de vida, ela entra em colapso e, potencialmente, provoca danos às criaturas próximas. Uma criatura dentro da metade da distância da altura da estrutura deve fazer uma salvaguarda de Destreza. Se falhar, sofre 5d6 pontos de dano contundente, fica caída e soterrada nos escombros, exigindo um teste de Força com CD 20 (Atletismo) como uma ação para escapar. O DM pode ajustar a CD para mais ou para menos, dependendo da natureza dos escombros. Com um teste bem-sucedido, a criatura sofre metade do dano e não fica caída ou soterrada.$$, $$SRD$$),
($$SRD_2014$$, $$eldritch-blast-2014$$, $$Eldritch Blast$$, $$Raio Místico$$, 0, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Instantânea$$, $$Você lança um raio de energia crepitante. Faça um ataque mágico à distância contra uma criatura ou objeto dentro da distância da magia. Se acertar, o alvo sofre 1d10 pontos de dano energético.   Aprimoramento de Truque.  A magia cria dois raios no nível 5, três raios no nível 11 e quatro raios no nível 17. Você pode direcionar os raios para o mesmo alvo ou para alvos diferentes. Realize uma jogada de ataque separada para cada raio.  [[(floor((@details.level+1)/6)+1)]]{Raios Totais}$$, $$SRD$$),
($$SRD_2014$$, $$enhance-ability-2014$$, $$Enhance Ability$$, $$Aprimorar Atributo$$, 2, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (Fur or a feather from a beast.)$$, $$Concentração, até 1 hora$$, $$Você toca uma criatura e lança sobre ela um aperfeiçoamento mágico. Escolha um dos efeitos a seguir; o alvo ganha esse efeito enquanto a magia durar.

Astúcia da Raposa . O alvo tem vantagem nos testes de Inteligência.

Elegância do Gato . O alvo tem vantagem nos testes de Destreza. Ele também não sofre dano por queda ao cair 6 metros [20 ft.] ou menos, caso não esteja incapacitado.

Esplendor da Águia . O alvo tem vantagem nos testes de Carisma.

Força do Touro . O alvo tem vantagem nos testes de Força e dobra a capacidade de carga.

Resistência do Urso . O alvo tem vantagem nos testes de Constituição. Ele também ganha 2d6 pontos de vida temporários que são perdidos ao término da magia.

Sabedoria da Coruja . O alvo tem vantagem nos testes de Sabedoria.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode atingir uma criatura adicional para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$enlarge-reduce-2014$$, $$Enlarge/Reduce$$, $$Aumentar/Reduzir$$, 2, $$Transmutação$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A pinch iron powder.)$$, $$Concentração, até 1 minuto$$, $$Você faz com que uma criatura ou um objeto, à sua vista e dentro do alcance da magia, fique maior ou menor enquanto a magia durar. Escolha uma criatura ou um objeto que não esteja sendo usado ou carregado. Se o alvo não for voluntário, ele pode fazer uma salvaguarda de Constituição. Em caso de sucesso, a magia não surte efeito.

Se o alvo for uma criatura, tudo o que estiver usando e carregando muda de tamanho junto com ela. Qualquer item descartado por uma criatura afetada por esta magia retorna, imediatamente, ao tamanho normal.

Aumentar . O tamanho do alvo dobra em todas as dimensões, e o peso é multiplicado por oito. O tamanho aumenta em uma categoria - de Médio para Grande, por exemplo. Se não houver espaço suficiente para o alvo dobrar o próprio tamanho, ele atinge o tamanho máximo possível no espaço disponível. Enquanto a magia durar, o alvo também tem vantagem em testes de Força e salvaguardas de Força. As armas dele também crescem para combinar com o novo tamanho. Se o alvo realizar um ataque bem-sucedido com essas armas, elas causam 1d4 pontos de dano a mais do que o normal da arma enquanto estiverem ampliadas.

Reduzir . O tamanho do alvo é reduzido à metade em todas as dimensões, e o peso é reduzido para um oitavo do normal. Essa redução diminui o tamanho do alvo em uma categoria - de Médio para Pequeno, por exemplo. Enquanto a magia durar, o alvo tem desvantagem em testes de Força e salvaguardas de Força. As armas dele também encolhem para combinar com o novo tamanho. Se o alvo realizar um ataque bem-sucedido com essas armas, elas causam 1d4 pontos de dano a menos que o normal da arma enquanto estiverem reduzidas (o dano mínimo é 1).$$, $$SRD$$),
($$SRD_2014$$, $$entangle-2014$$, $$Entangle$$, $$Emaranhar$$, 1, $$Conjuração$$, $$1 ação$$, $$27 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Ervas daninhas e vinhas aderentes brotam do chão em um quadrado de 6 metros de lado [20-foot square] a partir de um ponto no alcance da magia. Enquanto a magia durar, as plantas transformam o solo da área em terreno difícil.

Qualquer criatura na área, que não for bem-sucedida em uma salvaguarda de Força, fica contida pelas plantas constritoras enquanto a magia durar. Uma criatura contida pelas plantas pode usar uma ação para fazer um teste de Força contra a CD para evitar sua magia. Em caso de sucesso, ela se liberta.

Quando a magia termina, as plantas invocadas murcham.$$, $$SRD$$),
($$SRD_2014$$, $$enthrall-2014$$, $$Enthrall$$, $$Cativar$$, 2, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$1 minuto$$, $$Você dita uma sequência de palavras dispersivas, fazendo com que criaturas à sua escolha, à sua vista, dentro do alcance da magia e que possam ouvi-lo, façam uma salvaguarda de Sabedoria. Qualquer criatura que não possa ser enfeitiçada é automaticamente bem-sucedida na salvaguarda, e se você ou seus companheiros estiverem combatendo a criatura alvo, ela tem vantagem nesse teste. Se falhar, o alvo tem desvantagem nos testes de Sabedoria (Percepção) para perceber qualquer outra criatura que não seja o conjurador, enquanto a magia durar ou até que o alvo não consiga mais ouvi-lo. A magia termina se você estiver incapacitado ou se não puder mais falar.$$, $$SRD$$),
($$SRD_2014$$, $$etherealness-2014$$, $$Etherealness$$, $$Forma Etérea$$, 7, $$Transmutação$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$8 horas$$, $$Você adentra as regiões fronteiriças de Plano Etéreo, na área onde ele se sobrepõe ao seu plano atual. Você permanece na Fronteira Etérea enquanto a magia durar ou até que você use sua ação para dispensar a magia. Durante esse tempo, você pode se mover em qualquer direção. Se você se mover para cima ou para baixo, cada 0,3 metro [1 foot] de deslocamento custa 0,6 metro [2 ft.]. Você pode ver e ouvir o plano do qual é originário, mas tudo parece cinza e nada pode ser visto a mais de 18 metros [60 ft.] de distância.

Enquanto estiver no Plano Etéreo, você só pode afetar e ser afetado por outras criaturas nesse plano. Criaturas que não estejam no Plano Etéreo não podem percebê-lo e nem interagir com você, a menos que uma habilidade especial ou mágica lhes dê essa capacidade.

Você ignora todos os objetos e efeitos que não estejam no Plano Etéreo, o que lhe permite mover-se através de objetos que você perceba no plano do qual é originário.

Ao término da magia, você retorna imediatamente ao seu plano de origem, no lugar que está ocupando no momento. Se ocupar o mesmo lugar de um objeto ou criatura quando isso acontecer, você é imediatamente desviado para o espaço desocupado mais próximo que puder ocupar, sofrendo 10 pontos de dano energético a cada 1,5 metro [5 ft.] percorrido.

Esta magia não tem nenhum efeito se você conjurá-la enquanto estiver no Plano Etéreo ou em um plano que não faça fronteira com ele, como um dos Planos Externos.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 8º círculo ou superior, você pode atingir até três criaturas (incluindo você mesmo) para cada círculo do espaço acima do 7º. As criaturas devem estar a até 3 metros [10 ft.] de você quando esta magia for conjurada.$$, $$SRD$$),
($$SRD_2014$$, $$expeditious-retreat-2014$$, $$Expeditious Retreat$$, $$Retirada Acelerada$$, 1, $$Transmutação$$, $$1 ação bônus$$, $$Pessoal$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Esta magia permite que você se mova em um ritmo incrível. Ao conjurá-la, e depois com uma ação bônus em cada um dos seus turnos até a magia se encerrar, você pode executar a ação Correr.$$, $$SRD$$),
($$SRD_2014$$, $$eyebite-2014$$, $$Eyebite$$, $$Mau Olhado$$, 6, $$Necromancia$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Enquanto a magia durar, seus olhos tornam-se um vazio escuro imbuído com um poder aterrorizante. Escolha uma criatura à sua vista e que esteja a até 18 metros [60 ft.] de você, que deverá ser bem-sucedida em uma salvaguarda de Sabedoria ou será afetada por um dos efeitos a seguir, à sua escolha, enquanto a magia durar. Em cada um de seus turnos, até a magia terminar, você pode usar sua ação para atingir outra criatura, mas não pode ter como alvo uma criatura novamente se ela for bem-sucedida em uma salvaguarda contra esta conjuração de Mau Olhado.

Adormecer . O alvo fica inconsciente. Ele acorda ao sofrer algum dano ou se outra criatura usar a ação dela para sacudi-lo até acordá-lo.

Apavorard . O alvo fica amedrontado por você. Em cada um dos turnos dele, o alvo amedrontado deve executar a ação Correr e afastar-se de você pela rota mais segura e curta disponível, a menos que não haja nenhum lugar para onde ir. Se ele se dirigir para um local a pelo menos 18 metros [60 ft.] de você, de onde não possa mais vê-lo, este efeito termina.

Adoecer . O alvo tem desvantagem nas jogadas de ataque e testes de atributo. No final de cada um dos turnos dele, o alvo pode fazer outra salvaguarda de Sabedoria. Se for bem-sucedido, o efeito termina.$$, $$SRD$$),
($$SRD_2014$$, $$fabricate-2014$$, $$Fabricate$$, $$Fabricar$$, 4, $$Transmutação$$, $$10 minutos$$, $$36 metros$$, $$V, S$$, $$Instantânea$$, $$Você transforma matérias-primas em produtos do mesmo material. Por exemplo, você pode fabricar uma ponte de madeira a partir de um monte de árvores, uma corda a partir de um pedaço de cânhamo, e roupas a partir do linho ou lã.

Escolha uma matéria prima à sua vista e no alcance da magia. Você pode fabricar um objeto de tamanho Grande ou menor (que caiba dentro de um cubo de 3 metros [10 ft.], ou oito cubos de 1,5 metro [5 ft.] conectados), desde que haja matéria prima suficiente. Se você estiver trabalhando com metal, pedra ou outra substância mineral, todavia, o objeto fabricado não pode ser maior que Médio (contido em um cubo de 1,5 [5 ft.] metro). A qualidade dos objetos feitos pela magia depende da qualidade da matéria-prima.

Criaturas ou itens mágicos não podem ser criados ou transmutados por meio desta magia. Você também não pode usá-la para criar itens que ordinariamente exijam alto grau de manufatura, como joias, armas, vidro ou armadura, a não ser que tenha proficiência com o tipo de ferramentas de artesão necessárias para fabricar tais objetos.$$, $$SRD$$),
($$SRD_2014$$, $$faerie-fire-2014$$, $$Faerie Fire$$, $$Fogo das Fadas$$, 1, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V$$, $$Concentração, até 1 minuto$$, $$Objetos em um Cubo de 6 metros de lado no alcance da magia são delineados por luz azul, verde ou violeta (à sua escolha). Cada criatura no Cubo também é delineada se falhar em uma salvaguarda de Destreza. Pela duração da magia, objetos e criaturas afetadas emitem &Reference[dimlight] em um raio de 3 metros e não podem se beneficiar da condição Invisível.  Jogadas de ataque contra uma criatura ou objeto afetado têm Vantagem se o atacante puder vê-la.$$, $$SRD$$),
($$SRD_2014$$, $$faithful-hound-2014$$, $$Faithful Hound$$, $$Cão Fiel$$, 4, $$Conjuração$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A tiny silver whistle, a piece of bone, and a thread)$$, $$8 horas$$, $$Você conjura um cão de guarda fantasma em um espaço desocupado à sua vista, no alcance da magia, onde ele permanece enquanto a magia durar, até você dispensá-lo com uma ação, ou até você se mover a mais de 30 metros [100 ft.] dele.

O cão é invisível para todas as criaturas, exceto para você e não pode ser ferido. Quando uma criatura Pequena ou maior se aproximar a até 9 metros [30 ft.] do cão, sem primeiro dizer a senha que você especifica ao conjurar a magia, ele começa a latir alto. O cão enxerga criaturas invisíveis e pode ver no Plano Etéreo. Ele ignora ilusões.

No início de cada um de seus turnos, o cão tenta morder uma criatura hostil à você que esteja a até 1,5 metro [5 ft.] dele. O bônus de ataque do cão é igual ao seu modificador de atributo de conjuração + seu bônus de proficiência. Se acertar, ele causa 4d8 pontos de dano perfurante.$$, $$SRD$$),
($$SRD_2014$$, $$false-life-2014$$, $$False Life$$, $$False Life$$, 1, $$Necromancia$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A small amount of alcohol or distilled spirits.)$$, $$1 hora$$, $$You gain 2d4 + 4 Temporary Hit Points.   Usando Espaços de Magia de Círculo Superior.  You gain 5 additional Temporary Hit Points for each spell slot level above 1.$$, $$SRD$$),
($$SRD_2014$$, $$fear-2014$$, $$Fear$$, $$Medo$$, 3, $$Ilusão$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A white feather or the heart of a hen.)$$, $$Concentração, até 1 minuto$$, $$Você projeta uma imagem fantasmagórica dos piores medos de uma criatura. Cada criatura num cone de 9 metros [30 ft.] deve ser bem-sucedida numa salvaguarda de Sabedoria ou derrubará o que estiver segurando e ficará amedrontada enquanto a magia durar.

Em cada um dos turnos dela, a criatura deve executar a ação Correr e distanciar-se o máximo que puder de você pela rota mais segura disponível, a menos que não haja para onde ir. Se a criatura finalizar o turno dela em um local onde não possa mais vê-lo, ela pode fazer uma salvaguarda de Sabedoria. Em caso de sucesso, a magia se encerra para ela.$$, $$SRD$$),
($$SRD_2014$$, $$feather-fall-2014$$, $$Feather Fall$$, $$Queda Suave$$, 1, $$Transmutação$$, $$1 reação$$, $$18 metros$$, $$V, M (A small feather or a piece of down.)$$, $$1 minuto$$, $$Escolha até cinco criaturas em queda no alcance da magia. A taxa de queda de cada uma diminui para 18 metros por rodada até que a magia termine. Se uma criatura pousar antes do fim da magia, não sofre dano da queda e a magia se encerra para ela.$$, $$SRD$$),
($$SRD_2014$$, $$feeblemind-2014$$, $$Feeblemind$$, $$Enfraquecer Intelecto$$, 8, $$Encantamento$$, $$1 ação$$, $$45 metros$$, $$V, S, M (A handful of clay, crystal, glass, or mineral spheres.)$$, $$Instantânea$$, $$Você assola a mente de uma criatura à sua vista e no alcance da magia, tentando despedaçar o intelecto e a personalidade dela. O alvo sofre 4d6 pontos de dano psíquico e deve fazer uma salvaguarda de Inteligência.

Se falhar, o valor da Inteligência e do Carisma da criatura passa a ser 1. A criatura não pode conjurar magias, ativar itens mágicos, compreender idiomas ou se comunicar de forma inteligível. Ela pode identificar seus próprios amigos, segui-los e até protegê-los.

Ao final de um período de 30 dias, a criatura pode repetir a salvaguarda contra a magia. Em caso de sucesso, a magia se encerra.

Ela também pode ser anulada por Restauração Maior, Cura Completa ou Desejo.$$, $$SRD$$),
($$SRD_2014$$, $$find-familiar-2014$$, $$Find Familiar$$, $$Convocar Familiar$$, 1, $$Conjuração$$, $$1 hora$$, $$3 metros$$, $$V, S, M (10gp worth of charcoal, incense, and herbs that must be consumed by fire in a brass brazier.)$$, $$Instantânea$$, $$Você passa a contar com os serviços de um familiar, um espírito que assume a forma de um animal à sua escolha: morcego, gato, caranguejo, sapo (rã), falcão, lagarto, polvo, coruja, cobra venenosa, peixe (piranha), rato, corvo, cavalo marinho, aranha ou furão. Aparecendo em um espaço desocupado dentro do alcance da magia, o familiar tem as estatísticas da forma escolhida, apesar de ser um celestial, feérico ou ínfero (à sua escolha), em vez de uma fera.

Seu familiar age independentemente de você, mas ele sempre obedece aos seus comandos. Em combate, joga a própria iniciativa e age no próprio turno. Um familiar não pode atacar, mas pode realizar outras ações normalmente.

Ao ficar com 0 pontos de vida, ele desaparece, não deixando forma física alguma para trás. O familiar reaparece após você conjurar esta magia novamente.

Enquanto seu familiar estiver a até 30 metros [100 ft.] de você, é possível se comunicar telepaticamente com ele. Além disso, com uma ação, você pode ver através dos olhos dele e ouvir o que ele ouve até o começo de seu próximo turno, ganhando os benefícios de quaisquer sentidos especiais que ele tenha. Durante este tempo, você fica surdo e cego no que diz respeito aos seus próprios sentidos.

Com uma ação, você pode dispensar seu familiar temporariamente. Ele desaparece em um bolsão dimensional onde aguarda a sua convocação. Se preferir, você pode dispensá-lo permanentemente. Enquanto o familiar estiver temporariamente dispensado, com uma ação você pode fazer com que ele reapareça em qualquer espaço desocupado a até 9 metros [30 ft.] de você.

Você não pode ter mais de um familiar por vez. Se conjurar esta magia quando já tiver um familiar, você apenas fará com que o seu familiar adote uma nova forma. Escolha uma das formas da lista acima. O seu familiar se transforma na criatura escolhida.

Por fim, quando conjurar uma magia com alcance de toque, seu familiar pode lançar a magia como se ele mesmo a tivesse conjurado. Ele deve estar a até 30 metros [100 ft.] de você, e você deve usar a reação dele para lançar a magia quando a conjurar. Se a magia pedir uma jogada de ataque, use o seu modificador de ataque.$$, $$SRD$$),
($$SRD_2014$$, $$find-steed-2014$$, $$Find Steed$$, $$Convocar Montaria$$, 2, $$Conjuração$$, $$10 minutos$$, $$9 metros$$, $$V, S$$, $$Instantânea$$, $$Você invoca um espírito que assume a forma de uma montaria especialmente inteligente, forte e fiel, criando um vínculo de longa duração com ela. Aparecendo em um espaço desocupado dentro do alcance, a montaria toma uma forma à sua escolha: um alce, um camelo, um cavalo de guerra, um mastim ou um pônei (seu DM pode permitir que outros animais sejam conjurados como montarias). A montaria tem as estatísticas da forma escolhida, mas é um celestial, feérico ou ínfero (à sua escolha), em vez do tipo normal. Além disso, se a criatura tiver uma Inteligência igual ou menor que 5, esta se torna 6 e ela adquire a capacidade de entender um idioma que você possa falar, à sua escolha.

Ela serve como sua montaria, tanto em combate quanto fora dele, e vocês têm um elo instintivo que lhes permite lutar como uma unidade perfeita. Enquanto estiver montado na criatura, qualquer magia que você conjurar e que tenha a si mesmo como alvo, afeta também a sua montaria.

Quando a criatura ficar com 0 pontos de vida, ela desaparece, não deixando corpo algum para trás. Você também pode dispensar sua montaria a qualquer momento com uma ação, fazendo-a desaparecer. Em ambos os casos, conjurar esta magia novamente invoca o mesmo animal, restaurado com pontos de vida máximos.

Enquanto sua montaria estiver a até 1,5 quilômetro [1 mile] de você, é possível se comunicar telepaticamente com ela.

Não é possível ter mais de uma montaria vinculada por esta magia ao mesmo tempo. Com uma ação, você pode liberar a montaria de seu vínculo a qualquer momento, fazendo-a desaparecer.$$, $$SRD$$),
($$SRD_2014$$, $$find-traps-2014$$, $$Find Traps$$, $$Encontrar Armadilhas$$, 2, $$Adivinhação$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Instantânea$$, $$Você sente a presença de qualquer armadilha em sua linha de visão e no alcance da magia. Uma armadilha, para os fins desta magia, inclui qualquer coisa que causaria um efeito repentino ou inesperado que você considera danoso ou indesejado, e que tenha sido especificamente projetada como tal por quem a criou. Assim, a magia sentiria uma área afetada pelas magias Alarme, Glifo de Proteção ou uma armadilha mecânica de fosso, mas não revela uma fraqueza natural no piso, um teto instável ou um sumidouro escondido.  O efeito revela apenas se há uma armadilha presente. Você não descobre a localização de cada armadilha, mas passa a saber a natureza geral do perigo imposto pela armadilha que você sente.$$, $$SRD$$),
($$SRD_2014$$, $$find-the-path-2014$$, $$Find the Path$$, $$Encontrar o Caminho$$, 6, $$Adivinhação$$, $$1 minuto$$, $$Pessoal$$, $$V, S, M (A set of divinatory tools--such as bones, ivory sticks, cards, teeth, or carved runes--worth 100gp and an object from the location you wish to find.)$$, $$Concentração, até 24 horas$$, $$Esta magia permite que você encontre a rota física mais curta e direta até uma localidade específica que lhe seja familiar, no mesmo plano de existência. Se você nomear um destino em outro plano, um destino móvel (uma fortaleza móvel) ou uma localidade não específica (como "um covil de um dragão verde" ), a magia falha.

Enquanto a magia durar e você estiver no mesmo plano de existência que seu destino, você sabe quão longe e em qual direção ele está. Enquanto estiver a caminho de lá, toda vez que lhe for apresentada uma escolha de caminhos, você automaticamente sabe determinar qual o mais curto e direto (mas não necessariamente o mais seguro) até o destino.$$, $$SRD$$),
($$SRD_2014$$, $$finger-of-death-2014$$, $$Finger of Death$$, $$Dedo da Morte$$, 7, $$Necromancia$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Você descarrega energia negativa em uma criatura à sua vista e no alcance da magia, causando-lhe fortes dores. O alvo deve fazer uma salvaguarda de Constituição. Se falhar, sofre 7d8+30 pontos de dano necrótico, ou metade do dano em caso de sucesso.

Um humanoide morto por esta magia levanta-se, no início do seu próximo turno, como um zumbi que esta permanentemente sob o seu comando, seguindo suas ordens verbais da melhor forma possível.$$, $$SRD$$),
($$SRD_2014$$, $$fire-bolt-2014$$, $$Fire Bolt$$, $$Raio de Fogo$$, 0, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Instantânea$$, $$Você arremessa uma partícula de fogo em uma criatura ou objeto no alcance da magia. Realize um ataque mágico à distância contra o alvo. Em caso de acerto, o alvo sofre 1d10 pontos de dano Ígneo. Um objeto inflamável atingido por esta magia entra em combustão se não estiver sendo usado ou carregado.   Aprimoramento de Truque.  O dano aumenta em 1d10 quando você atinge os níveis 5 (2d10), 11 (3d10) e 17 (4d10).$$, $$SRD$$),
($$SRD_2014$$, $$fire-shield-2014$$, $$Fire Shield$$, $$Escudo Ardente$$, 4, $$Evocação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A little phosphorus or a firefly.)$$, $$10 minutos$$, $$Chamas finas e bruxuleantes recobrem seu corpo enquanto a magia durar, emitindo luz plena em um raio de 3 metros [10 ft.] e meia-luz por 3 metros adicionais. A magia termina antecipadamente quando você usa uma ação para dissipá-la.

As labaredas proporcionam a você um escudo ígneo ou um escudo gélido, à sua escolha. O escudo ígneo lhe confere resistência contra dano gélido e o escudo gélido fornece resistência contra dano ígneo.

Além disso, sempre que uma criatura a menos de 1,5 metros [5 ft.] de você acertá-lo com um ataque corpo a corpo, o escudo entra em erupção flamejante. O atacante sofre 2d8 pontos de dano ígneo de um escudo ígneo e 2d8 pontos de dano gélido de um escudo gélido.$$, $$SRD$$),
($$SRD_2014$$, $$fire-storm-2014$$, $$Fire Storm$$, $$Tempestade de Fogo$$, 7, $$Evocação$$, $$1 ação$$, $$45 metros$$, $$V, S$$, $$Instantânea$$, $$Uma tempestade feita de camadas crepitantes de chamas aparece em uma localização à sua escolha e no alcance da magia. A área da tempestade consiste em até 10 cubos de 3 metros [10-foot cubes], que você pode arranjar como quiser. Cada cubo deve ter ao menos uma face adjacente à face de outro cubo. Cada criatura na área deve fazer uma salvaguarda de Destreza. Se falhar, sofre 7d10 pontos de dano ígneo, ou metade do dano em caso de sucesso.

O fogo danifica objetos na área e incendeia objetos inflamáveis que não estejam sendo usados ou carregados. Você pode determinar que a vida vegetal na área não seja afetada por esta magia.$$, $$SRD$$),
($$SRD_2014$$, $$fireball-2014$$, $$Fireball$$, $$Bola de Fogo$$, 3, $$Evocação$$, $$1 ação$$, $$45 metros$$, $$V, S, M (A tiny ball of bat guano and sulfur.)$$, $$Instantânea$$, $$Um rastro brilhante lampeja do seu dedo apontado para um local à sua escolha e no alcance da magia, onde desabrocha com um estrondo grave em uma explosão de chamas. Cada criatura em uma esfera com raio de 6 metros [20-foot-radius sphere], centrada naquele ponto, deve fazer uma salvaguarda de Destreza. Se falhar, sofre 8d6 pontos de dano ígneo, ou metade do dano em caso de sucesso.

O fogo se alastra, contornando os cantos. Ele incendeia objetos inflamáveis na área que não estejam sendo usados ou carregados.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 3º.$$, $$SRD$$),
($$SRD_2014$$, $$flame-blade-2014$$, $$Flame Blade$$, $$Lâmina Flamejante$$, 2, $$Evocação$$, $$1 ação bônus$$, $$Pessoal$$, $$V, S, M (Leaf of sumac.)$$, $$Concentração, até 10 minutos$$, $$Você evoca uma lâmina de fogo em sua mão livre. A lâmina é semelhante em tamanho e forma a uma cimitarra e permanece enquanto a magia durar. Se você soltar a lâmina, ela desaparece, mas você pode evocá-la novamente com uma ação bônus.

A lâmina de fogo pode ser usada para fazer um ataque mágico corpo a corpo, usando uma ação. Se acertar, o alvo sofre 3d6 pontos de dano ígneo.

A lâmina flamejante emite luz plena em um raio de 3 metros [10 ft.] e cria meia-luz por 3 metros adicionais.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d6 para cada dois círculos do espaço de magia acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$flame-strike-2014$$, $$Flame Strike$$, $$Coluna de Chamas$$, 5, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V, S, M (Pinch of sulfur.)$$, $$Instantânea$$, $$Uma coluna vertical de fogo divino ressoa, caindo dos céus sobre um local que você especifica. Cada criatura dentro de um cilindro de 3 metros de raio e 12 metros de altura [10-foot-radius, 40-foot-tall cylinder], centrado em um ponto no alcance da magia, deve fazer uma salvaguarda de Destreza. Se falhar, sofre 4d6 pontos de dano ígneo e 4d6 pontos de dano radiante, ou metade do dano em caso de sucesso.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano ígneo ou o dano radiante aumenta em 1d6 para cada círculo do espaço acima do 5º.$$, $$SRD$$),
($$SRD_2014$$, $$flaming-sphere-2014$$, $$Flaming Sphere$$, $$Esfera Flamejante$$, 2, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A bit of tallow, a pinch of brimstone, and a dusting of powdered iron.)$$, $$Concentração, até 1 minuto$$, $$Uma esfera de fogo com 1,5 metro de diâmetro [5-foot-diameter sphere] aparece em um espaço desocupado à sua escolha, no alcance da magia e permanece enquanto esta durar. Qualquer criatura que termine seu próprio turno no alcance de 1,5 metro [5 ft.] da esfera deve fazer uma salvaguarda de Destreza. Se falhar, sofre 2d6 pontos de dano ígneo, ou metade do dano em caso de sucesso.

Com uma ação bônus, você pode mover a esfera até 9 metros [30 ft.]. Se forçá-la contra uma criatura, esta deve fazer uma salvaguarda contra o dano da esfera, que fica imóvel neste turno.

Ao mover a esfera, você pode direcioná-la sobre barreiras de até 1,5 metro [5 ft.] de altura e fazê-la saltar sobre fossos de até 3 metros [10 ft.] de largura. A esfera incendeia objetos inflamáveis que não estejam sendo usados ou carregados, emitindo luz plena em um raio de 6 metros e meia-luz por mais 6 metros.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$flesh-to-stone-2014$$, $$Flesh to Stone$$, $$De Carne Para Pedra$$, 6, $$Transmutação$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A pinch of lime, water, and earth.)$$, $$Concentração, até 1 minuto$$, $$Você tenta transformar em pedra uma criatura à sua vista e no alcance da magia. Se o corpo do alvo for feito de carne, ele deve fazer uma salvaguarda de Constituição. Se falhar, fica contida imediatamente, conforme sua carne começa a endurecer. Em caso de sucesso, a criatura não é afetada.

Uma criatura contida por esta magia deve fazer outra salvaguarda de Constituição ao final de cada um dos turnos dela. Se for bem-sucedida três vezes, a magia se encerra. Se falhar três vezes, é transformada em pedra, passando a ser considerada com a condição petrificada, enquanto a magia durar. Os sucessos e falhas não precisam ser consecutivos; mantenha registro de ambos até que o alvo tenha três de um tipo.

Se a criatura for quebrada fisicamente enquanto petrificada, ela sofre deformações semelhantes, caso reverta para o estado original.

Se você mantiver sua concentração nesta magia durante toda a duração, a criatura permanece petrificada até que o efeito seja removido.$$, $$SRD$$),
($$SRD_2014$$, $$floating-disk-2014$$, $$Floating Disk$$, $$Disco Flutuante$$, 1, $$Conjuração$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A drop of mercury.)$$, $$1 hora$$, $$Esta magia cria um disco circular horizontal feito de energia com 1 metro de diâmetro e 2,5 centímetros de altura, que flutua a 1 metro [3 ft] do chão em um espaço desocupado à sua escolha, à sua vista e no alcance da magia. O disco permanece enquanto a magia durar, e pode carregar até 225 quilos. Se mais peso for colocado sobre ele, a magia se encerra e tudo oque está no disco cai.

O disco é imóvel enquanto você estiver a até 6 metros [20 ft] dele. Se você se mover para mais de 6 metros [20 ft] de distância dele, o disco segue você, permanecendo a até 6 metros [20 ft] de distância de você. Ele pode atravessar terrenos irregulares, subir ou descer escadas, declives e afins, mas não pode atravessar uma mudança de elevação de 3 metros [10 ft] ou mais. Por exemplo, o disco não pode se mover através de um fosso de 3 metros [10 ft] de profundidade, nem poderia deixar tal fosso se fosse criado no fundo dele.

Se você se mover a mais de 30 metros [100 ft] do disco (geralmente por ele não poder se mover através de um obstáculo para seguir você), a magia se encerra.$$, $$SRD$$),
($$SRD_2014$$, $$fly-2014$$, $$Fly$$, $$Voo$$, 3, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (A wing feather from any bird.)$$, $$Concentração, até 10 minutos$$, $$Você toca uma criatura voluntária. O alvo ganha um deslocamento de voo de 18 metros [60 ft.] enquanto a magia durar. Ao término da magia, caso o alvo ainda esteja no ar, ele cai, a menos que possa parar a queda.

Em Círculos Superiores.  Ao conjurar esta magia utilizando um espaço de magia de 4º círculo ou superior, você pode escolher uma criatura alvo adicional para cada círculo do espaço acima do 3º.$$, $$SRD$$),
($$SRD_2014$$, $$fog-cloud-2014$$, $$Fog Cloud$$, $$Névoa Obscurecente$$, 1, $$Conjuração$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Você cria uma esfera de nevoeiro com raio de 6 metros [20-foot radius], centrado em um ponto no alcance da magia. A esfera se alastra, contornando os cantos e a área afetada fica totalmente obscurecida. Ele permanece enquanto a magia durar ou até que um vento de velocidade moderada (de pelo menos 15 quilômetros por hora) ou maior a disperse.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o raio da esfera aumenta em 6 metros para cada círculo do espaço acima do 1º.$$, $$SRD$$),
($$SRD_2014$$, $$forbiddance-2014$$, $$Forbiddance$$, $$Proibição$$, 6, $$Abjuração$$, $$10 minutos$$, $$Toque$$, $$V, S, M (A sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp.)$$, $$24 horas$$, $$Você cria uma defesa contra viagem mágica que protege uma área de até 3.500 metros quadrados [40.000 square feet] e até 9 metros [30 ft.] de altura, a partir do chão. Enquanto a magia durar, nenhuma criatura pode se teleportar para dentro dessa área ou usar portais, como aqueles criados pela magia Portal, para adentrá-la. A magia bloqueia a área contra viagens planares e, portanto, impede que criaturas acessem a área por meio do Plano Astral, Plano Etéreo, Faéria, Sombral ou pela magia Transição Planar.

Além disso, esta magia causa dano a tipos de criaturas escolhidos por você. Ao conjurá-la, escolha um ou mais dos seguintes tipos: celestiais, elementais, feéricos, ínferos e mortos-vivos. Quando uma criatura do tipo escolhido entra na área da magia pela primeira vez ou inicia o próprio turno dentro da área, ela sofre 5d10 pontos de dano radiante ou necrótico (à sua escolha).

Ao conjurar esta magia, você pode designar uma senha. Uma criatura que diga a senha ao adentrar a área não sofre nenhum dano da magia.

A área mágica não pode se sobrepor com a área de outra magia Proibição. Se você conjurar Proibição todos os dias no mesmo local, durante 30 dias, a magia dura até ser dissipada e os componentes materiais são consumidos ao término da última conjuração.$$, $$SRD$$),
($$SRD_2014$$, $$forcecage-2014$$, $$Forcecage$$, $$Cárcere de Energia$$, 7, $$Evocação$$, $$1 ação$$, $$30 metros$$, $$V, S, M (Ruby dust worth 1,500 gp.)$$, $$1 hora$$, $$Uma prisão com a forma de um cubo invisível e imóvel, composta de força mágica, surge ao redor de uma área à sua escolha e no alcance da magia. Ela pode ser uma jaula ou uma caixa sólida, à sua escolha.

A jaula pode ter até 6 metros [20 ft.] de lado, sendo feita de barras de 1,5 centímetros [1/2 inch] de espessura com espaços de 1,5 centímetros [1/2 inch] entre elas.

A caixa pode ter 3 metros [10 ft.] de lado e cria uma barreira sólida que impede qualquer matéria de passar através dela, bloqueando quaisquer magias conjuradas dentro ou fora da área.

Quando a magia é conjurada, qualquer criatura que estiver completamente dentro da área afetada fica aprisionada. Criaturas que estejam apenas parcialmente na área, ou que sejam grandes demais para caber dentro da área, são empurradas para longe do centro da área, até ficarem completamente fora dela.

Uma criatura dentro da prisão não pode deixá-la por meios não-mágicos. Se a criatura tenta usar alguma forma de teleporte ou viagem extraplanar para sair da prisão, precisa primeiro fazer uma salvaguarda de Carisma. Se falhar, ela não pode sair e desperdiça o uso da magia ou efeito; se for bem-sucedida, ela pode usar a magia para deixar a prisão. A prisão também se estende ao Plano Etéreo, bloqueando viagens etéreas

Esta magia não pode ser dissipada por Dissipar Magia.$$, $$SRD$$),
($$SRD_2014$$, $$foresight-2014$$, $$Foresight$$, $$Sexto Sentido$$, 9, $$Adivinhação$$, $$1 minuto$$, $$Toque$$, $$V, S, M (A hummingbird feather.)$$, $$8 horas$$, $$Você toca uma criatura voluntária. O alvo ganha uma capacidade limitada de ver o futuro imediato. Enquanto a magia durar, o alvo não pode ser surpreendido e tem vantagem em jogadas de ataque, testes de atributos e salvaguardas. Além disso, outras criaturas têm desvantagem em jogadas de ataque contra o alvo enquanto a magia durar.

Esta magia se encerra imediatamente se você conjurá-la novamente antes que a duração inicial tenha terminado.$$, $$SRD$$),
($$SRD_2014$$, $$freedom-of-movement-2014$$, $$Freedom of Movement$$, $$Movimentação Livre$$, 4, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (A leather strap, bound around the arm or a similar appendage.)$$, $$1 hora$$, $$Você toca uma criatura voluntária. Enquanto a magia durar, o movimento do alvo não é afetado por terreno difícil, e magias e outros efeitos mágicos não podem reduzir o deslocamento, paralisar ou conter o alvo.

O alvo também pode gastar 1,5 metro [5 ft.] de movimento para escapar automaticamente de impedimentos não-mágicos, como algemas ou o agarramento de uma criatura. Por fim, estar debaixo d'água não impõe penalidades ao movimento do alvo ou aos seus ataques.$$, $$SRD$$),
($$SRD_2014$$, $$freezing-sphere-2014$$, $$Freezing Sphere$$, $$Esfera Congelante$$, 6, $$Evocação$$, $$1 ação$$, $$90 metros$$, $$V, S, M (A small crystal sphere.)$$, $$Instantânea$$, $$Um globo frígido de energia gélida é disparado da ponta de seus dedos até um ponto à sua escolha, no alcance da magia, onde explode em uma esfera de 18 metros de raio [60-foot-radius sphere]. Cada criatura na área deve fazer uma salvaguarda de Constituição. Se falhar, sofre 10d6 pontos de dano gélido, ou metade do dano em caso de sucesso.

Se o globo acertar um corpo de água ou um líquido formado principalmente de água (isso não inclui criaturas baseadas em água), ele congela o líquido até uma profundidade de 15 centímetros [6 inches] sobre uma área de 9 metros [30 ft.] quadrados. O gelo dura 1 minuto. Criaturas que estavam nadando na superfície de água congelada ficam presas no gelo. Uma criatura pode usar uma ação para fazer um teste de Força contra a CD para evitar sua magia para se libertar.

Você pode abster-se de disparar o globo depois de completar a magia, se assim desejar. Um pequeno globo com o tamanho aproximado de uma pedra de funda, frio ao toque, aparece em sua mão. A qualquer momento, você ou a criatura a quem você der o globo pode jogá-lo (a um alcance de 12 metros [40 ft.]) ou arremessá-lo com uma funda (no alcance normal da funda). Ele se despedaça no impacto com o mesmo efeito que a conjuração normal da magia. Você também pode colocar o globo no chão sem quebrá-lo. Depois de 1 minuto, se o globo já não estiver despedaçado, ele explode.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 7º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 6º.$$, $$SRD$$),
($$SRD_2014$$, $$gaseous-form-2014$$, $$Gaseous Form$$, $$Forma Gasosa$$, 3, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (A bit of gauze and a wisp of smoke.)$$, $$Concentração, até 1 hora$$, $$Você toca uma criatura voluntária. O alvo, junto com tudo aquilo que estiver usando e carregando, é transformado em uma nuvem de neblina, enquanto a magia durar. A magia termina se os pontos de vida da criatura forem reduzidos a 0. Criaturas incorpóreas não são afetadas.

Enquanto estiver nesta forma, o único método de movimento do alvo é o voo com deslocamento de 3 metros [10 ft.]. O alvo pode entrar e ocupar o espaço de outra criatura. O alvo tem resistência a danos não-mágicos e vantagem em salvaguardas de Força, Destreza e Constituição. O alvo pode passar através de pequenos orifícios, aberturas estreitas e até mesmo por meras rachaduras, embora trate líquidos como se fossem superfícies sólidas. O alvo não é afetado por queda, e continua pairando no ar mesmo quando atordoado ou incapacitado.

Enquanto estiver sob a forma de nuvem, o alvo não pode falar ou manipular objetos, aqueles que estiver carregando ou segurando não podem ser descartados ou usados, e nenhuma forma de interação pode ser estabelecida com eles. O alvo não pode atacar ou conjurar magias.$$, $$SRD$$),
($$SRD_2014$$, $$gate-2014$$, $$Gate$$, $$Portal$$, 9, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A diamond worth at least 5,000gp.)$$, $$Concentração, até 1 minuto$$, $$Você conjura um portal ligando um espaço desocupado, à sua vista, a um lugar específico em outro plano de existência. O portal é uma abertura circular, que pode ter de 1,5 [5 ft.] a 6 metros [20 ft.] de diâmetro. Você pode orientá-lo em qualquer direção que escolher. Ele permanece aberto enquanto a magia durar.

O portal tem uma frente e um verso em cada plano onde aparecer. É possível viajar simplesmente atravessando-o pela frente. Qualquer coisa que atravessá-lo será transportada instantaneamente para o outro plano, aparecendo no espaço desocupado mais próximo ao portal.

Divindades e outros regentes planares podem evitar que portais criados por esta magia abram-se em sua presença ou em qualquer lugar dos seus domínios.

Ao conjurar esta magia, você pode citar o nome de uma criatura específica (um pseudônimo, um título ou apelido não servem). Se essa criatura estiver em um plano diferente do seu, o portal abre-se em um espaço imediatamente ao lado da criatura citada e a arrasta através dele para o lugar desocupado mais próximo do seu lado do portal. Você não ganha poder especial algum sobre a criatura, e ela é livre para agir conforme o DM achar apropriado. A criatura pode ir embora, atacá-lo ou ajudá-lo.$$, $$SRD$$),
($$SRD_2014$$, $$geas-2014$$, $$Geas$$, $$Missão$$, 5, $$Encantamento$$, $$1 minuto$$, $$18 metros$$, $$V$$, $$30 dias$$, $$Você lança um comando mágico sobre uma criatura à sua vista e no alcance da magia, forçando-a a realizar algum serviço ou impedindo-a de executar alguma ação ou curso de atividade, conforme você desejar. Se a criatura for capaz de entendê-lo ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará enfeitiçada por você enquanto a magia durar. Enquanto a criatura estiver enfeitiçada por você, ela sofre 5d10 pontos de dano psíquico ao agir de maneira diretamente contraditória às suas instruções, mas não mais do que uma vez ao dia. Uma criatura que não for capaz de entendê-lo não é afetada por esta magia.

Você pode emitir qualquer comando que desejar, a não ser um que resulte em morte certa. Se você emitir um comando suicida, a magia se encerra.

A magia termina antecipadamente se você usar a sua ação para dissipá-la. Uma magia Remover Maldição, Restauração Maior ou Desejo também a encerra.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 7º ou 8º círculo, a duração é de 1 ano. Ao conjurar esta magia usando um espaço de magia de 9º círculo, a magia dura até ser encerrada por uma das magias mencionadas acima.$$, $$SRD$$),
($$SRD_2014$$, $$gentle-repose-2014$$, $$Gentle Repose$$, $$Repouso Tranquilo$$, 2, $$Necromancia$$, $$1 ação$$, $$Toque$$, $$V, S, M (A pinch of salt and one copper piece placed on each of the corpse's eyes, which must remain there for the duration.)$$, $$10 dias$$, $$Você toca um cadáver ou outros restos mortais. Enquanto a magia durar, o alvo está protegido da decomposição e não pode se tornar um morto-vivo.  A magia também estende efetivamente o tempo limite para trazer o alvo dos mortos, pois os dias passados sob a influência desta magia não contam contra o tempo limite de magias como Reviver os Mortos.$$, $$SRD$$),
($$SRD_2014$$, $$giant-insect-2014$$, $$Giant Insect$$, $$Inseto Gigante$$, 4, $$Transmutação$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Você transforma até dez centopeias, três aranhas, cinco vespas ou um escorpião no alcance da magia, em versões gigantes de suas formas naturais, enquanto a magia durar. Uma centopeia torna-se uma centopeia gigante, uma aranha, uma aranha gigante, uma vespa, uma vespa gigante e um escorpião, um escorpião gigante.

Cada criatura obedece aos seus comandos verbais e, em combate, age no mesmo turno que você, em cada rodada. O DM fornece as estatísticas para essas criaturas, sendo responsável por resolver ações e movimentos delas.

Uma criatura permanece em tamanho gigante enquanto a magia durar, enquanto não chegar a 0 ponto de vida ou até você usar uma ação para dispensar o efeito sobre ela.

O DM pode permitir que você escolha alvos diferentes dos listados. Se você transformar uma abelha, a versão gigante desta pode ter as mesmas estatísticas de uma vespa gigante, por exemplo.$$, $$SRD$$),
($$SRD_2014$$, $$glibness-2014$$, $$Glibness$$, $$Loquacidade$$, 8, $$Transmutação$$, $$1 ação$$, $$Pessoal$$, $$V$$, $$1 hora$$, $$Enquanto a magia durar, quando você realiza um teste de Carisma, pode substituir o número que tirou por 15. Além disso, não importa o que diga, uma magia que determinaria se você está falando a verdade indica que você está sendo honesto.$$, $$SRD$$),
($$SRD_2014$$, $$globe-of-invulnerability-2014$$, $$Globe of Invulnerability$$, $$Globo de Invulnerabilidade$$, 6, $$Abjuração$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A glass or crystal bead that shatters when the spell ends.)$$, $$Concentração, até 1 minuto$$, $$Uma barreira imóvel e levemente cintilante surge a 3 metros de raio [10-foot radius] em volta de você e permanece enquanto durar a magia.

Qualquer magia de 5º círculo ou inferior conjurada do lado de fora da barreira não poderá afetar criaturas ou objetos dentro dela, mesmo se for conjurada usando um espaço de magia superior. A magia pode atingir criaturas e objetos dentro da barreira, mas não terá efeito sobre eles. Da mesma forma, a área dentro da barreira é excluída das zonas afetadas por essa magia.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 7º círculo ou superior, a barreira bloqueia magias um círculo superior para cada círculo do espaço acima do 6º.$$, $$SRD$$),
($$SRD_2014$$, $$glyph-of-warding-2014$$, $$Glyph of Warding$$, $$Glifo de Proteção$$, 3, $$Abjuração$$, $$1 hora$$, $$Toque$$, $$V, S, M (Incense and powdered diamond worth at least 200 gp, which the spell consumes.)$$, $$Até ser dissipada$$, $$Ao conjurar esta magia, você inscreve um glifo que mais tarde desencadeia um efeito mágico. Você o inscreve em uma superfície (como uma mesa, uma seção de piso ou parede) ou dentro de um objeto que possa ser fechado (como um livro, um pergaminho ou uma arca de tesouro) e onde o glifo possa ser escondido. O símbolo pode cobrir uma área de até 3 metros de diâmetro [10-foot diameter]. Se a superfície ou objeto for movido mais de 3 metros [10 ft.] de onde você conjurou esta magia, o símbolo é quebrado e a magia se encerra, sem efeito.

O glifo é quase invisível, exigindo um teste de Inteligência (Investigação) contra a CD para evitar sua magia para encontrá-lo.

Ao conjurar esta magia, você decide o gatilho do glifo. Para os glifos que foram inscritos em uma superfície, os gatilhos mais típicos incluem tocar ou pisar no glifo, remover um objeto que o cubra, aproximar-se a uma certa distância dele ou manipular um objeto que o contenha. Para os que forem inscritos dentro de um objeto, as condições podem ser a abertura deste, aproximar-se a uma certa distância, ou ainda ver ou ler o glifo. Uma vez que um glifo seja disparado, esta magia termina.

Você pode refinar o gatilho para que a magia seja ativada apenas sob certas circunstâncias ou de acordo com as características físicas (como altura ou peso), tipo de criatura (por exemplo, a proteção poderia ser programada para afetar aberrações ou drow) ou alinhamento. Podem também ser especificadas condições para que não se dispare o glifo, como dizer uma palavra-chave, por exemplo.

Quando você inscrever o glifo, escolha entre runas explosivas ou glifo arcano.

Runas Explosivas . Quando acionada, a runa explode com energia mística em uma esfera de 6 metros [20 ft.] centrada no glifo. A esfera se alastra, contornando os cantos. Cada criatura na área deve fazer uma salvaguarda de Destreza. Se falhar, sofre 5d8 pontos de dano ácido, elétrico, gélido, ígneo ou trovejante (à sua escolha, ao conjurar a magia), ou metade do dano em caso de sucesso.

Glifo Arcano . Você pode armazenar uma magia preparada de 3º círculo ou inferior junto ao glifo, se conjurar esta magia como parte do processo. Ela deve ter como alvo uma única criatura, ou uma área. A magia que foi conjurada não tem efeito imediato nesta modalidade. Ela se ativa quando o glifo for disparado. Se a magia tiver um alvo, quem acionou o glifo é atingido. Se a magia afetar uma área, o centro é a criatura. Se a magia invocar criaturas hostis ou criar objetos nocivos ou armadilhas, eles surgem o mais próximo possível do intruso e o atacam. Se a magia exigir concentra­ção, ela permanece até o fim de sua duração total.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano por um símbolo de runas explosivas aumenta em 1d8 para cada círculo do espaço acima do 3º. Se criar um glifo arcano, você pode armazenar qualquer magia até o mesmo círculo que o espaço que foi usado para conjurar o Glifo de Proteção.$$, $$SRD$$),
($$SRD_2014$$, $$goodberry-2014$$, $$Goodberry$$, $$Bom Fruto$$, 1, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (A sprig of mistletoe.)$$, $$Instantânea$$, $$Até dez frutos aparecem na sua mão, tornando-se magicamente infundidos. Uma criatura pode usar uma ação para comer um fruto. Comer um fruto restaura 1 ponto de vida, além de fornecer nutrição suficiente para sustentar uma criatura por um dia.  Os frutos perdem sua potência se não tiverem sido consumidos após 24 horas da conjuração desta magia.$$, $$SRD$$),
($$SRD_2014$$, $$grease-2014$$, $$Grease$$, $$Graxa$$, 1, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A bit of pork rind or butter.)$$, $$1 minuto$$, $$Uma graxa escorregadia recobre uma área de 3 metros quadrados [10-foot square] de chão em um ponto dentro do alcance da magia, tornando-a terreno difícil enquanto esta durar.  Quando a graxa aparece, cada criatura parada na área precisa ser bem-sucedida em uma salvaguarda de Destreza ou é considerada caída. Uma criatura que entre ou termine seu próprio turno na área também precisa ser bem-sucedida em uma salvaguarda de Destreza, ou fica caída.$$, $$SRD$$),
($$SRD_2014$$, $$greater-invisibility-2014$$, $$Greater Invisibility$$, $$Invisibilidade Maior$$, 4, $$Ilusão$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você ou uma criatura tocada por você torna-se invisível enquanto a magia durar. Qualquer coisa que o alvo estiver usando ou carregando torna-se invisível enquanto permanecer em contato com ele.$$, $$SRD$$),
($$SRD_2014$$, $$greater-restoration-2014$$, $$Greater Restoration$$, $$Restauração Maior$$, 5, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (Diamond dust worth at least 100gp, which the spell consumes.)$$, $$Instantânea$$, $$Você toca uma criatura, imbuindo-a com energia positiva que desfaz um efeito debilitante. Você pode reduzir o nível de exaustão dela em 1 ou cancelar algum dos efeitos a seguir:

Um efeito que enfeitiçou ou petrificou o alvo;

Uma maldição, incluindo a sintonia do indivíduo com um item mágico amaldiçoado;

Qualquer redução de um dos valores de atributo do alvo;

Um efeito que reduza os pontos de vida máximos do alvo.$$, $$SRD$$),
($$SRD_2014$$, $$guardian-of-faith-2014$$, $$Guardian of Faith$$, $$Defensor da Fé$$, 4, $$Conjuração$$, $$1 ação$$, $$9 metros$$, $$V$$, $$8 horas$$, $$Uma sentinela espectral de tamanho Grande aparece e flutua em um espaço desocupado à sua escolha, à sua vista e no alcance da magia. Ele permanece enquanto a magia durar. A sentinela é indistinta exceto por uma espada brilhante e um escudo ornado com o símbolo da sua divindade.

Qualquer criatura hostil a você que se mova para um espaço a até 3 metros [10 ft.] da sentinela pela primeira vez em um turno deve ser bem-sucedida em uma salvaguarda de Destreza. Se falhar, sofre 20 pontos de dano radiante, ou metade do dano em caso de sucesso. A sentinela desaparece quando tiver causado um total de 60 pontos de dano.$$, $$SRD$$),
($$SRD_2014$$, $$guards-and-wards-2014$$, $$Guards and Wards$$, $$Proteger Fortaleza$$, 6, $$Abjuração$$, $$10 minutos$$, $$Toque$$, $$V, S, M (Burning incense, a small measure of brimstone and oil, a knotted string, a small amount of umber hulk blood, and a small silver rod worth at least 10 gp.)$$, $$24 horas$$, $$Você cria uma defesa que protege até 225 metros quadrados [2.500 square feet] de área útil (uma área quadrada de 15 metros [50 ft.] de lado, ou cem quadrados de 1,5 metro [5 ft.], ou 25 quadrados de 3 metros [10 ft.]). A área defendida pode ter até 6 metros [20 ft.] de altura e assumir a forma que você desejar. Você pode defender várias secções de uma fortaleza, dividindo a área entre elas na medida em que puder andar em cada área contígua, enquanto está conjurando a magia.

Ao conjurar esta magia, você pode especificar os indiví­duos que não são afetados por um ou por todos os efeitos. Você também pode especificar uma senha que, dita em voz alta, torna imune aos efeitos aquele que a proferir.

Ao conjurar Proteger Fortaleza trate a área defendida como sendo alvo dos seguintes efeitos:

Corredores . Um nevoeiro preenche todos os corredores defendidos, tornando-os fortemente obscurecidos. Além disso, em cada interseção ou passagem que ofereça uma escolha de direção, há uma chance de 50 por cento de uma criatura, que não seja você, acreditar que segue na direção oposta à que escolheu.

Portas . Todas as portas da área protegida são bloqueadas magicamente, como se estivessem seladas pela magia Tranca Arcana. Além disso, você pode cobrir até dez portas com uma ilusão (equivalente à função objeto ilusório da magia Ilusão Menor), para fazer com que se pareçam como seções contínuas da parede.

Escadas . Teias preenchem todas as escadas da área defendida, de cima a baixo, como a magia Teia. Essas teias voltam a crescer em 10 minutos se forem queimadas ou arrancadas enquanto a magia Proteger Fortaleza durar.

Outros Efeitos Mágicos . Você pode colocar, à sua escolha, um dos seguintes efeitos mágicos dentro da área defendida.

Luzes Dançantes em quatro corredores. Você pode definir um programa simples que as luzes repetirão enquanto a magia Proteger Fortaleza durar.

Boca Encantada em dois locais.

Núvem Fétida em dois locais. Os vapores aparecem nos lugares que você designar; eles retornam dentro de 10 minutos se dispersados pelo vento, enquanto a magia Proteger Fortaleza durar.

Uma Lufada de Vento soprando constantemente em um corredor ou aposento.

Sugestão em um lugar. Você deve selecionar uma área de 1,5 metro [5 ft.] quadrado, e qualquer criatura que entrar ou passar através dessa área recebe a sugestão mentalmente.

Toda a área defendida irradia magia. Uma conjuração bem-sucedida de Dissipar Magia sobre determinado efeito remove apenas esse efeito.

Você pode criar uma estrutura permanentemente protegida e defendida ao conjurar esta magia nela, todos os dias, durante um ano.$$, $$SRD$$),
($$SRD_2014$$, $$guidance-2014$$, $$Guidance$$, $$Orientação$$, 0, $$Adivinhação$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você toca uma criatura disposta e escolhe uma perícia. Até que a magia termine, a criatura adiciona 1d4 a qualquer teste de atributo usando a perícia escolhida.$$, $$SRD$$),
($$SRD_2014$$, $$guiding-bolt-2014$$, $$Guiding Bolt$$, $$Raio Guia$$, 1, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$1 rodada$$, $$Você lança um raio de luz em direção a uma criatura no alcance da magia. Realize um ataque mágico à distância contra o alvo. Em caso de acerto, ele sofre 4d6 pontos de dano Radiante, e a próxima jogada de ataque realizado contra ele antes do final do seu próximo turno tem Vantagem.   Usando Espaços de Magia de Círculo Superior.  O dano aumenta em 1d6 pontos para cada círculo de espaço de magia acima do 1º.$$, $$SRD$$),
($$SRD_2014$$, $$gust-of-wind-2014$$, $$Gust of Wind$$, $$Lufada de Vento$$, 2, $$Evocação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A legume seed.)$$, $$Concentração, até 1 minuto$$, $$Uma linha de vento forte, com 18 metros [60 ft.] de comprimento e 3 metros [10 ft.] de largura, é soprada a partir de você em uma direção à sua escolha, enquanto a magia durar. Cada criatura que comece seu próprio turno na linha deve ser bem-sucedida em uma salvaguarda de Força ou é empurrada 4,5 metros [15 ft.] para longe de você, a favor da linha de vento.  Qualquer criatura na linha deve gastar 3 metros [10 ft.] de deslocamento para cada 1,5 metro [5 ft.] que se movimentar na sua direção.  A lufada dispersa gases ou vapor e apaga velas, tochas e chamas semelhantes que estejam desprotegidas na área. Ela faz com que chamas protegidas, como as de lanternas, oscilem descontroladamente e tenham 50 por cento de chance de se extinguirem.  Com uma ação bônus em cada um dos seus turnos antes do final da magia, você pode mudar a direção na qual a linha sopra a partir de você.$$, $$SRD$$),
($$SRD_2014$$, $$hallow-2014$$, $$Hallow$$, $$Consagrar$$, 5, $$Evocação$$, $$24 horas$$, $$Toque$$, $$V, S, M (Herbs, oils, and incense worth at least 1,000 gp, which the spell consumes.)$$, $$Até ser dissipada$$, $$Você toca um ponto e infunde uma área em torno dele com poder sagrado (ou profano). A área pode ter um raio de até 18 metros [60 ft.], e a magia falha se o raio incluir uma área já sob o efeito de uma magia consagrar. A área afetada está sujeita aos efeitos a seguir.

Primeiro, celestiais, elementais, feéricos, ínferos e mortos-vivos não podem entrar na área, tampouco essas criaturas podem enfeitiçar, amedrontar ou possuir outras criaturas na área. Qualquer criatura enfeitiçada, amedrontada ou possuída por tais criaturas já não está mais sob quaisquer dessas condições ao entrar na área. Você pode excluir um ou mais desses tipos de criaturas deste efeito.

Segundo, você pode vincular um efeito adicional à área. Escolha o efeito da lista a seguir, ou escolha um efeito oferecido pelo DM. Alguns destes efeitos aplicam-se às criaturas na área; você pode determinar se o efeito se aplica a todas as criaturas, a criaturas que seguem um líder ou divindade específicos, ou a criaturas de um determinado tipo, como orcs e trolls. Quando uma criatura que deveria ser afetada entra na área da magia pela primeira vez durante um turno, ou inicia o próprio turno ali, deve fazer uma salvaguarda de Carisma. Se for bem-sucedida, a criatura ignora o efeito adicional até sair da área.

Coragem.  Criaturas afetadas não podem ser amedrontadas enquanto estiverem na área.

Descanso Eterno.  Cadáveres enterrados na área não podem ser transformados em mortos-vivos.

Escuridão.  Escuridão preenche a área. Luz normal, bem como luz mágica criada por feitiços de um círculo inferior ao do espaço de magia que você usou para conjurar esta magia não podem iluminar a área.

Idiomas.  Criaturas afetadas por esta magia podem se comunicar com qualquer outra criatura na área, mesmo se não compartilharem um idioma comum.

Interferência Extradimensional.  Criaturas afetadas por esta magia não podem se mover ou viajar usando teleporte ou meios extradimensionais ou interplanares.

Luz do Dia.  Luz plena preenche a área. Escuridão mágica criada por feitiços de um círculo inferior ao do espaço de magia que você usou para conjurar esta magia não pode extinguir a luz.

Medo.  Criaturas afetadas por esta magia ficam amedrontadas enquanto estiverem na área.

Proteção Contra Energia.  Criaturas afetadas na área têm resistência a um tipo de dano à sua escolha, exceto contundente, cortante e perfurante.

Silêncio.  Nenhum som pode emanar de dentro da área, e nenhum som pode adentrá-la.

Vulnerabilidade a Energia.  Criaturas afetadas na área têm vulnerabilidade a um tipo de dano à sua escolha, exceto contundente, cortante e perfurante.$$, $$SRD$$),
($$SRD_2014$$, $$hallucinatory-terrain-2014$$, $$Hallucinatory Terrain$$, $$Terreno Alucinatório$$, 4, $$Ilusão$$, $$10 minutos$$, $$90 metros$$, $$V, S, M (A stone, a twig, and a bit of green plant.)$$, $$24 horas$$, $$Você faz com que um terreno natural em um cubo de 45 metros [150-foot cube] no alcance da magia pareça, soe e cheire como outro tipo de terreno natural. Assim, campos abertos ou um caminho podem ser modificados para que se assemelhem a um pântano, montanha, fenda ou algum outro terreno difícil ou intransitável. Uma lagoa pode ser modificada para se parecer com um prado verdejante, um precipício com um declive suave, ou um barranco pedregoso com uma estrada larga e plana. Estruturas manufaturadas, equipamentos e criaturas dentro da área não mudam a aparência.

As características táteis do terreno não são alteradas, portanto criaturas entrando na área são propensas a ver através da ilusão. Se a diferença não for óbvia ao toque, uma criatura examinando cuidadosamente a ilusão pode tentar um teste de Inteligência (Investigação) contra a CD para evitar suas magias, assim desacreditando a magia. Uma criatura que perceba a ilusão pelo o que é ela é, verá uma imagem difusa, sobreposta ao terreno.$$, $$SRD$$),
($$SRD_2014$$, $$harm-2014$$, $$Harm$$, $$Moléstia$$, 6, $$Necromancia$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Você transmite uma doença virulenta a uma criatura à sua vista e dentro do alcance da magia. O alvo deve fazer uma salvaguarda de Constituição. Se falhar, sofre 14d6 pontos de dano necrótico, ou metade do dano se bem-sucedido. O dano não pode reduzir os pontos de vida do alvo a menos de 1. Se o alvo falhar na salvaguarda, o valor de seus pontos de vida máximos é reduzido durante 1 hora em uma quantidade equivalente ao dano necrótico sofrido. Qualquer efeito que remova uma doença permite que o valor dos pontos de vida máximos do alvo retorne ao normal, antes do tempo de encerramento desta magia.$$, $$SRD$$),
($$SRD_2014$$, $$haste-2014$$, $$Haste$$, $$Celeridade$$, 3, $$Transmutação$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A shaving of licorice root.)$$, $$Concentração, até 1 minuto$$, $$Escolha uma criatura voluntária, à sua vista e dentro do alcance da magia. Enquanto a magia durar, o alvo tem deslocamento dobrado, ganha +2 na CA, tem vantagem nas salvaguardas de Destreza e ganha uma ação adicional em cada um dos próprios turnos. Essa ação pode ser usada apenas como as ações Atacar (ataque armado, apenas), Correr, Desengajar, Esconder ou Usar um Objeto.

Quando a magia termina, o alvo é dominado por uma onda de letargia e não pode se mover ou executar ações até o final do próximo turno dele.$$, $$SRD$$),
($$SRD_2014$$, $$heal-2014$$, $$Heal$$, $$Cura Completa$$, 6, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Escolha uma criatura à sua vista e no alcance da magia. Uma onda de energia positiva a preenche, fazendo com que recupere 70 pontos de vida. Esta magia também põe fim a cegueira, surdez ou a qualquer doença que afete o alvo. Esta magia não tem efeito sobre constructos ou mortos-vivos.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 7º círculo ou superior, a quantidade de pontos de vida recuperados aumenta em 10 para cada círculo do espaço acima do 6º.$$, $$SRD$$),
($$SRD_2014$$, $$healing-word-2014$$, $$Healing Word$$, $$Palavra Curativa$$, 1, $$Evocação$$, $$1 ação bônus$$, $$18 metros$$, $$V$$, $$Instantânea$$, $$Uma criatura à sua escolha, à sua vista e no alcance da magia recupera Pontos de Vida iguais a 2d4 mais seu modificador de atributo de conjuração.   Usando Espaços de Magia de Círculo Superior.  A cura aumenta em 2d4 para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$heat-metal-2014$$, $$Heat Metal$$, $$Esquentar Metal$$, 2, $$Transmutação$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A piece of iron and a flame.)$$, $$Concentração, até 1 minuto$$, $$Escolha um objeto metálico manufaturado, como uma arma de metal ou uma armadura de metal pesada ou média, à sua vista e no alcance da magia. Você faz com que o objeto brilhe em um tom vermelho incandescente. Qualquer criatura que esteja em contato físico com o objeto sofre 2d8 pontos de dano ígneo no momento da conjuração. Enquanto a magia durar, você pode usar sua ação bônus em cada um dos seus turnos subsequentes para causar esse dano novamente.

Se uma criatura estiver segurando ou usando o objeto e sofrer o dano, ela deve ser bem-sucedida em uma salvaguarda de Constituição ou derruba o objeto, se puder. Caso não o faça, ela tem desvantagem nas jogadas de ataque e em testes de atributo até o início do próximo turno do conjurador desta magia.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$hellish-rebuke-2014$$, $$Hellish Rebuke$$, $$Repreensão Diabólica$$, 1, $$Evocação$$, $$1 reação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Você aponta o seu dedo e a criatura que lhe causou dano é momentaneamente cercada por chamas infernais. Ela deve fazer uma salvaguarda de Destreza. Se falhar, sofre 2d10 pontos de dano ígneo, ou metade do dano em caso de sucesso.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 1º.$$, $$SRD$$),
($$SRD_2014$$, $$heroes-feast-2014$$, $$Heroes' Feast$$, $$Banquete de Heróis$$, 6, $$Conjuração$$, $$10 minutos$$, $$9 metros$$, $$V, S, M (A gem-encrusted bowl worth at least 1,000gp, which the spell consumes.)$$, $$Instantânea$$, $$Você faz surgir um grande banquete, incluindo comida e bebida magníficas. O banquete leva 1 hora para ser consumido e desaparece no final desse tempo; os efeitos benéficos não aparecem até que essa hora se passe. Até doze outras criaturas podem partilhar o banquete.

Uma criatura que partilhe do banquete ganha vários benefícios. A criatura é curada de todas as doenças e envenenamentos, torna-se imune a veneno e a ficar amedrontada, e faz todas as salvaguardas de Sabedoria com vantagem. O valor dos pontos de vida máximos dela também aumenta em 2d10, ganhando esse mesmo número em pontos de vida. Estes benefícios duram 24 horas.$$, $$SRD$$),
($$SRD_2014$$, $$heroism-2014$$, $$Heroism$$, $$Heroísmo$$, 1, $$Encantamento$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você toca uma criatura voluntária que se torna imbuída de bravura. Até que a magia termine, a criatura é imune à condição Amedrontado e recebe Pontos de Vida Temporários igual ao seu modificador de atributo de conjuração no início de cada um dos turnos dela.   Usando Espaços de Magia de Círculo Superior.  Você pode escolher uma criatura adicional para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$hideous-laughter-2014$$, $$Hideous Laughter$$, $$Gargalhada Nefasta$$, 1, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S, M (Tiny tarts and a feather that is waved in the air.)$$, $$Concentração, até 1 minuto$$, $$Você escolhe uma criatura à sua vista e no alcance da magia, que passa a perceber tudo como hilariantemente engraçado, sofrendo ataques de riso, caso seja afetada pela magia. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou fica caído, incapacitado e incapaz de se levantar enquanto a magia durar. Uma criatura de Inteligência 4 ou menos não pode ser afetada.

Ao final de cada turno, e em cada ocasião que sofrer dano, o alvo pode tentar outra salvaguarda de Sabedoria. O alvo tem vantagem se a salvaguarda for disparada por dano sofrido. Em caso de sucesso, a magia se encerra.$$, $$SRD$$),
($$SRD_2014$$, $$hold-monster-2014$$, $$Hold Monster$$, $$Imobilizar Monstro$$, 5, $$Encantamento$$, $$1 ação$$, $$27 metros$$, $$V, S, M (A small piece of iron.)$$, $$Concentração, até 1 minuto$$, $$Escolha uma criatura à sua vista e no alcance da magia. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou fica paralisado enquanto a magia durar. Esta magia não tem efeito sobre mortos-vivos. No final de cada um dos turnos dele, o alvo pode fazer uma nova salvaguarda de Sabedoria. Em caso de sucesso, a magia se encerra sobre o alvo.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, você pode atingir uma criatura adicional para cada círculo do espaço acima do 5º. As criaturas devem estar a até 9 metros umas das outras quando você as atingir.$$, $$SRD$$),
($$SRD_2014$$, $$hold-person-2014$$, $$Hold Person$$, $$Imobilizar Pessoa$$, 2, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A small, straight piece of iron.)$$, $$Concentração, até 1 minuto$$, $$Escolha um humanoide à sua vista e no alcance da magia. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou fica paralisado enquanto a magia durar. No final de cada um dos turnos dele, o alvo pode fazer outra salvaguarda de Sabedoria. Em caso de sucesso, a magia se encerra sobre o alvo.   Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode atingir um humanoide adicional para cada círculo do espaço acima do 2º. Os humanoides devem estar a até de 9 metros [30 ft.] uns dos outros quando você os atingir.$$, $$SRD$$),
($$SRD_2014$$, $$holy-aura-2014$$, $$Holy Aura$$, $$Aura Sagrada$$, 8, $$Abjuração$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A tiny reliquary worth at least 1,000gp containing a sacred relic, such as a scrap of cloth from a saint's robe or a piece of parchment from a religious text.)$$, $$Concentração, até 1 minuto$$, $$Uma luz divina emana de você e se manifesta em um brilho suave por um raio de 9 metros [30 ft.] ao seu redor. Criaturas dentro do raio e à sua escolha emitem meia-luz em um raio de 1,5 metro [5 ft.] e têm vantagem em todas as salvaguardas, as demais criaturas têm desvantagem em jogadas de ataque contra as primeiras enquanto a magia durar. Além disso, quando um ínfero ou um morto-vivo atinge uma criatura afetada por esta magia com um ataque corpo a corpo, a aura cintila com uma luz brilhante. O atacante deve ser bem-sucedido em uma salvaguarda de Constituição ou fica cego enquanto a magia durar.$$, $$SRD$$),
($$SRD_2014$$, $$hunters-mark-2014$$, $$Hunter's Mark$$, $$Marca do Predador$$, 1, $$Adivinhação$$, $$1 ação bônus$$, $$27 metros$$, $$V$$, $$Concentração, até 1 hora$$, $$Você marca magicamente como sua presa uma criatura à sua vista e no alcance da magia. Até que a magia termine, você causa 1d6 pontos de dano Energético adicionais ao alvo sempre que o acertar com uma jogada de ataque. Você também tem Vantagem em qualquer teste de [[/check ability=wis skill=prc]] ou [[/check ability=wis skill=sur]] que realizar para encontrá-lo.  Se o alvo é reduzido a 0 Pontos de Vida antes que esta magia termine, você pode executar uma ação Bônus para mover a marca para uma nova criatura à sua vista e no alcance da magia.   Usando Espaços de Magia de Círculo Superior.  Your Concentration can last longer with a spell slot of level 3–4 (up to 8 hours) or 5+ (up to 24 hours).$$, $$SRD$$),
($$SRD_2014$$, $$hypnotic-pattern-2014$$, $$Hypnotic Pattern$$, $$Padrão Hipnótico$$, 3, $$Ilusão$$, $$1 ação$$, $$36 metros$$, $$S, M (A glowing stick of incense or a crystal vial filled with phosphorescent material.)$$, $$Concentração, até 1 minuto$$, $$Você cria um padrão distorcido de cores o qual serpenteia no ar dentro de um cubo de 9 metros de lado [30-foot cube], no alcance da magia. O padrão aparece por um momento e desaparece. Cada criatura na área, e que seja capaz de ver o padrão, deve fazer uma salvaguarda de Sabedoria. Se falhar, a criatura fica enfeitiçada enquanto a magia durar. Criaturas afetadas por esta magia estão incapacitadas e tem deslocamento igual a 0.  Uma criatura afetada por esta magia terá os efeitos encerrados sobre si caso venha a sofrer qualquer tipo de dano ou se alguém usar uma ação para sacudi-la, removendo-a de seu estupor.$$, $$SRD$$),
($$SRD_2014$$, $$ice-storm-2014$$, $$Ice Storm$$, $$Tempestade Glacial$$, 4, $$Evocação$$, $$1 ação$$, $$90 metros$$, $$V, S, M (A pinch of dust and a few drops of water.)$$, $$Instantânea$$, $$Uma saraivada de pedras de gelo bate no chão em um cilindro de 6 metros de raio por 12 metros de altura [20-foot-radius, 40-foot-tall cylinder], centrado em um ponto no alcance da magia. Cada criatura na área afetada deve fazer uma salvaguarda de Destreza. Se falhar, sofre 2d8 pontos de dano contundente e 4d6 pontos de dano gélido, ou metade do dano em caso de sucesso.

O granizo transforma a área da tempestade em terreno difícil até o final do seu próximo turno.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o dano contundente aumenta em 1d8 para cada círculo do espaço acima do 4º círculo.$$, $$SRD$$),
($$SRD_2014$$, $$identify-2014$$, $$Identify$$, $$Indentificar$$, 1, $$Adivinhação$$, $$1 minuto$$, $$Toque$$, $$V, S, M (A pearl worth at least 100gp and an owl feather.)$$, $$Instantânea$$, $$Escolha um objeto que você deve tocar durante a conjuração da magia. Se for um item mágico ou algum outro tipo de objeto imbuído de magia, você descobre as propriedades dele e como usá-las, se ele exige sintonização para ser usado e quantas cargas tem, caso as tenha. Você também descobre se alguma magia está afetando o objeto e que magia é essa. Se o item foi criado por uma magia, você também identifica qual magia o criou.  Se em vez disso você tocar uma criatura durante a conjuração, você descobre quais magias a estão afetando, caso estejam.$$, $$SRD$$),
($$SRD_2014$$, $$illusory-script-2014$$, $$Illusory Script$$, $$Escrita Ilusória$$, 1, $$Ilusão$$, $$1 minuto$$, $$Toque$$, $$S, M (A lead-based ink worth at least 10gp, which this spell consumes.)$$, $$10 dias$$, $$Você escreve em um pergaminho, papel ou algum material apropriado para escrita, infundindo-o com uma ilusão potente enquanto a magia durar.

Para você e quaisquer criaturas escolhidas quando a magia é conjurada a escrita parece com sua caligrafia normal e expressa qualquer significado de sua intenção quando o texto foi escrito. Para todos os demais, as palavras aparecem como se fossem escritas em um alfabeto · desconhecido ou mágico, tornando-as ininteligíveis. Se preferir, você pode fazer com que a escrita tenha a aparência de um texto completamente diferente, escrito em outra caligrafia e idioma, apesar de ser necessário que você conheça o idioma.

Caso a magia seja dissipada, tanto o texto original quanto o ilusório desaparecem.

Uma criatura com visão verdadeira pode ler a mensagem escondida.$$, $$SRD$$),
($$SRD_2014$$, $$imprisonment-2014$$, $$Imprisonment$$, $$Aprisionamento$$, 9, $$Abjuração$$, $$1 minuto$$, $$9 metros$$, $$V, S, M (A vellum depiction or a carved statuette in the likeness of the target, and a special component that varies according to the version of the spell you choose, worth at least 500gp per Hit Die of the target.)$$, $$Até ser dissipada$$, $$Você cria um dispositivo de retenção mágica para aprisionar uma criatura à sua vista e no alcance da magia. O alvo deve fazer uma salvaguarda de Sabedoria. Se falhar, fica preso pela magia; se for bem-sucedido, fica imune a esta magia caso você a conjure novamente. A criatura não precisa respirar, comer ou beber, e não envelhece enquanto estiver afetada por esta magia. Magias de adivinhação não podem localizar ou perceber o alvo.

Ao conjurar esta magia, você escolhe uma das seguintes formas de aprisionamento.

Acorrentar . Pesadas correntes firmemente enraizadas ao chão prendem o alvo no lugar. O alvo fica contido enquanto a magia durar, e não pode mover-se ou ser movido por quaisquer meios antes disso. O componente especial para esta versão da magia é uma corrente fina feita de algum metal precioso.

Contenção Reduzida . O alvo é encolhido até uma altura de 2,5 centímetros [1 inch] e fica preso dentro de uma pedra preciosa ou objeto similar. Luz pode passar através da pedra preciosa normalmente (permitindo que o alvo possa ver o que há fora e que outras criaturas de fora possam vê-lo), porém nada mais pode passar, mesmo por meio de teleporte ou viagem planar. A pedra preciosa não pode ser lapidada ou quebrada enquanto a magia permanecer em vigor. O componente especial para esta versão da magia é uma grande gema transparente, como uma safira, diamante ou rubi.

Enterrar . O alvo é enterrado bem fundo no solo em uma esfera de força mágica grande o suficiente para contê-lo. Nada pode passar através da esfera, nem qualquer criatura pode teleportar ou usar viagem planar para entrar ou sair dela. O componente especial para esta versão da magia é um pequeno orbe de mitral.

Prisão Cercada . A magia transporta o alvo para um minúsculo semiplano protegido contra teleporte e viagens planares. O semiplano pode ser um labirinto, uma gaiola, uma torre ou qualquer estrutura confinada ou área semelhante, à sua escolha. O componente especial para esta versão da magia é uma representação em miniatura da prisão feita em jade.

Torpor . O alvo fica inconsciente e não pode ser despertado. O componente especial para esta versão da magia consiste em raras ervas soníferas.

Terminando a Magia . Durante a conjuração desta magia, qualquer que seja a versão dela, você pode especificar uma condição que fará com que ela termine e o alvo seja liberado. A condição pode ser tão específica ou tão elaborada quanto você desejar, mas o DM deve concordar que a condição seja razoável e que tenha uma probabilidade de vir a acontecer. As condições podem ser baseadas no nome, identidade ou divindade de uma criatura, mas seja como for, deve ser baseada em ações ou qualidades observáveis e não em coisas intangíveis como nível, classe ou pontos de vida.

Uma magia Dissipar Magia pode encerrar esta magia somente se for conjurada como uma magia de 9º círculo, tendo como alvo seja a prisão ou o componente especial usado para criá-lo.

Você pode usar um determinado componente especial para criar apenas uma prisão de cada vez. Se você conjurar a magia novamente usando o mesmo componente, o alvo da primeira conjuração é imediatamente liberado de sua prisão.$$, $$SRD$$),
($$SRD_2014$$, $$incendiary-cloud-2014$$, $$Incendiary Cloud$$, $$Nuvem Incendiária$$, 8, $$Conjuração$$, $$1 ação$$, $$45 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Uma nuvem rodopiante de fumaça que atira brasas quentes aparece em uma esfera com raio de 6 metros [20-foot-radius sphere], centrada em um ponto à sua escolha e no alcance da magia. A nuvem se alastra, contornando os cantos e a área afetada fica totalmente obscurecida. Ela permanece enquanto a magia durar ou até que um vento de velocidade moderada (de ao menos 15 quilômetros [10 miles] por hora) ou maior a disperse.

Quando a nuvem aparece, cada criatura dentro dela deve fazer uma salvaguarda de Destreza. Se falhar, sofre 10d8 pontos de dano ígneo, ou metade do dano em caso de sucesso. Uma criatura deve fazer esta salvaguarda quando entra na área da magia pela primeira vez ou inicia o pró­prio turno ali.

A nuvem se distancia 3 metros [10 ft.] de você em uma direção à sua escolha no início de cada um de seus turnos.$$, $$SRD$$),
($$SRD_2014$$, $$inflict-wounds-2014$$, $$Inflict Wounds$$, $$Infligir Ferimentos$$, 1, $$Necromancia$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Instantânea$$, $$Faça um ataque mágico corpo a corpo contra uma criatura ao seu alcance. Se acertar, o alvo sofre 3d10 pontos de dano necrótico.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 1º.$$, $$SRD$$),
($$SRD_2014$$, $$insect-plague-2014$$, $$Insect Plague$$, $$Praga de Insetos$$, 5, $$Conjuração$$, $$1 ação$$, $$90 metros$$, $$V, S, M (A few grains of sugar, some kernels of grain, and a smear of fat.)$$, $$Concentração, até 10 minutos$$, $$Um enxame de gafanhotos vorazes preenche uma esfera com raio de 6 metros [20 ft.], centrada em um ponto à sua escolha e no alcance da magia. A esfera de insetos se alastra, contornando os cantos. Enquanto a magia durar, a área afetada torna-se parcialmente obscurecida e terreno difícil.

Quando o enxame surge, cada criatura no local do efeito deve ser bem-sucedida em uma salvaguarda de Constitui­ção. Se falhar, sofre 4d10 pontos de dano perfurante, ou metade do dano em caso de sucesso. Uma criatura também deve fazer esta salvaguarda ao entrar pela primeira vez, ou ao terminar o próprio turno na área da magia.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 5º.$$, $$SRD$$),
($$SRD_2014$$, $$instant-summons-2014$$, $$Instant Summons$$, $$Convocação Instantânea$$, 6, $$Conjuração$$, $$1 minuto$$, $$Toque$$, $$V, S, M (A sapphire worth 1,000 gp.)$$, $$Até ser dissipada$$, $$Você toca um objeto pesando não mais do que 5 quilos [10 pounds], cuja maior dimensão seja de 1,8 metro [6 ft.] ou menor. Esta magia deixa uma marca invisível na superfície do objeto e, de maneira invisível, inscreve o nome do item na safira que você usou como componente material. Cada vez que conjurar esta magia, você deve usar uma safira diferente.

Em qualquer momento posterior, você pode usar sua ação para dizer o nome do item e esmagar a safira. O item aparece imediatamente na sua mão, independentemente de qualquer distância física ou planar, o que encerra a magia.

Se alguma outra criatura estiver segurando ou transportando o item, esmagar a safira não o transporta até você, em vez disso você descobre quem é a criatura de posse do objeto e, aproximadamente, onde ela se encontra naquele momento.

Dissipar Magia ou um efeito similar aplicado com sucesso na safira encerra o efeito desta magia.$$, $$SRD$$),
($$SRD_2014$$, $$invisibility-2014$$, $$Invisibility$$, $$Invisibilidade$$, 2, $$Ilusão$$, $$1 ação$$, $$Toque$$, $$V, S, M (An eyelash encased in gum arabic.)$$, $$Concentração, até 1 hora$$, $$Uma criatura que você tocar torna-se invisível enquanto a magia durar. Qualquer coisa que o alvo estiver usando ou carregando torna-se invisível enquanto estiver em sua posse. A magia se encerra quando o alvo efetuar um ataque ou conjurar uma magia.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode atingir uma criatura adicional para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$irresistible-dance-2014$$, $$Irresistible Dance$$, $$Dança Irresistível$$, 6, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V$$, $$Concentração, até 1 minuto$$, $$Escolha uma criatura à sua vista, no alcance da magia. O alvo começa a dançar comicamente onde estiver: balançando-se, batendo os pés e se contorcendo enquanto a magia durar. Criaturas que não podem ser enfeitiçadas são imunes a esta magia.

Uma criatura sob o efeito da magia deve usar todo o movimento para dançar sem sair do próprio espaço, além de ter desvantagem em salvaguardas de Destreza e jogadas de ataque. Enquanto o alvo estiver afetado por esta magia, outras criaturas têm vantagem nas jogadas de ataque contra ele. Usando uma ação, uma criatura afetada pode fazer uma salvaguarda de Sabedoria para recuperar o controle sobre si mesma. Em caso de sucesso, a magia termina.$$, $$SRD$$),
($$SRD_2014$$, $$jump-2014$$, $$Jump$$, $$Jump$$, 1, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (A grasshopper's hind leg.)$$, $$1 minuto$$, $$You touch a willing creature. Once on each of its turns until the spell ends, that creature can jump up to 30 feet by spending 10 feet of movement.   Usando Espaços de Magia de Círculo Superior. Você pode escolher uma criatura adicional para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$knock-2014$$, $$Knock$$, $$Arrombar$$, 2, $$Transmutação$$, $$1 ação$$, $$18 metros$$, $$V$$, $$Instantânea$$, $$Escolha um objeto à sua vista e no alcance da magia. O objeto pode ser uma porta, uma caixa, um baú, um par de algemas, um cadeado ou outro objeto que contenha um meio mundano ou mágico que impeça o acesso.

Um alvo que seja mantido fechado por uma fechadura mundana ou que esteja emperrado ou obstruído torna-se destrancado, desemperrado ou desobstruído. Se o objeto possui várias fechaduras, apenas uma delas é destrancada.

Se você escolher um alvo mantido fechado com tranca arcana, os efeitos sobre ele ficam suprimidos por 10 minutos, durante os quais o alvo pode ser aberto e fechado normalmente.

Ao conjurar a magia, um estrondo, audível a até 90 metros [300 ft.], emana do objeto escolhido como alvo.$$, $$SRD$$),
($$SRD_2014$$, $$legend-lore-2014$$, $$Legend Lore$$, $$Lendas e Histórias$$, 5, $$Adivinhação$$, $$10 minutos$$, $$Pessoal$$, $$V, S, M (Incense worth at least 250 gp, which the spell consumes, and four ivory strips worth at least 50 gp each.)$$, $$Instantânea$$, $$Nomeie ou descreva uma pessoa, local ou objeto. A magia traz à sua mente um breve resumo de conhecimento significativo sobre aquilo que você nomeou. O conhecimento pode consistir de contos atuais, histórias esquecidas ou até mesmo conhecimento secreto que nunca foi amplamente sabido. Se aquilo que nomeou não for de importância lendária, você não obtém nenhuma informação. Quanto mais informação você já tiver sobre a coisa, mais precisa e detalhada é a informação que recebe.  Essa informação é precisa, mas pode ser expressa em linguagem figurada. Por exemplo, se você tem um misterioso machado mágico na mão, a magia pode produzir esta informação: "Ai do malfeitor cuja mão tocar o machado, pois mesmo o cabo dele decepa a mão dos ímpios. Apenas um verdadeiro Filho da Pedra, um adorador de Moradin e por ele amado poderá evocar os verdadeiros poderes do machado, e apenas com a palavra sagrada Rudnogg nos lábios".$$, $$SRD$$),
($$SRD_2014$$, $$lesser-restoration-2014$$, $$Lesser Restoration$$, $$Lesser Restoration$$, 2, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Instantânea$$, $$You touch a creature and end one condition on it: &Reference[blinded], &Reference[deafened], &Reference[paralyzed], or &Reference[poisoned].$$, $$SRD$$),
($$SRD_2014$$, $$levitate-2014$$, $$Levitate$$, $$Levitate$$, 2, $$Transmutação$$, $$1 ação$$, $$18 metros$$, $$V, S, M (Either a small leather loop or a piece of golden wire bent into a cup shape with a long shank on one end.)$$, $$Concentração, até 10 minutos$$, $$One creature or loose object of your choice that you can see within range rises vertically up to 20 feet and remains suspended there for the duration. The spell can levitate an object that weighs up to 500 pounds. An unwilling creature that succeeds on a Constitution saving throw is unaffected.  The target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target's altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can take a Magic action to move the target, which must remain within the spell's range.  When the spell ends, the target floats gently to the ground if it is still aloft.$$, $$SRD$$),
($$SRD_2014$$, $$light-2014$$, $$Light$$, $$Luz$$, 0, $$Evocação$$, $$1 ação$$, $$Toque$$, $$V, M (A firefly or phosphorescent moss.)$$, $$1 hora$$, $$Você toca um objeto que não seja maior do que 3 metros [10 ft.] em qualquer dimensão. Até o fim da magia, o objeto emite luz plena em um raio de 6 metros [20-foot radius] e cria meia-luz por 6 metros [20 ft.] adicionais. Essa luz pode ser da cor de sua preferência. Cobrir completamente o objeto afetado com algo opaco bloqueia a luz. A magia termina se você conjurá-la novamente ou se a dispensar com uma ação.  Caso você designe como alvo um objeto que esteja sendo carregado ou usado por uma criatura hostil, a criatura deve ser bem-sucedida em uma salvaguarda de Destreza para evitar a magia.$$, $$SRD$$),
($$SRD_2014$$, $$lightning-bolt-2014$$, $$Lightning Bolt$$, $$Relâmpago$$, 3, $$Evocação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A bit of fur and a rod of amber, crystal, or glass.)$$, $$Instantânea$$, $$Um raio formando uma linha de 30 metros [100 ft.] de comprimento por 1,5 metro [5 ft.] de largura dispara a partir de você em uma direção à sua escolha. Cada criatura na linha deve fazer uma salvaguarda de Destreza. Se falhar, sofre 8d6 pontos de dano elétrico, ou metade do dano em caso de sucesso.

O raio incendeia objetos inflamáveis na área que não estejam sendo usados ou carregados.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 3º.$$, $$SRD$$),
($$SRD_2014$$, $$locate-animals-or-plants-2014$$, $$Locate Animals or Plants$$, $$Localizar Animais ou Plantas$$, 2, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A bit of fur from a bloodhound.)$$, $$Instantânea$$, $$Descreva ou nomeie um tipo específico de animal ou planta. Concentrando-se na voz da natureza ao seu redor, você descobre a direção e a distância (até 7,5 quilômetros [5 miles]) em que a criatura ou planta mais próxima daquele tipo se encontra, caso exista alguma na área.$$, $$SRD$$),
($$SRD_2014$$, $$locate-creature-2014$$, $$Locate Creature$$, $$Localizar Criatura$$, 4, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A bit of fur from a bloodhound.)$$, $$Concentração, até 1 hora$$, $$Descreva ou nomeie uma criatura que lhe seja familiar. Você sente a direção do local onde ela se encontra, caso esteja a, no máximo, 300 metros [1000 ft.] de distância. Se a criatura estiver se movendo, você sabe em que direção.  Esta magia pode localizar uma criatura específica que você conheça, ou a criatura mais próxima de um tipo específico (como um humano ou unicórnio), contanto que você já tenha visto tal criatura de perto - a até 9 metros [30 ft.] - ao menos uma vez. Se a criatura que você descreveu ou nomeou está com uma forma diferente, como sob o efeito da magia Polimorfia, esta magia não a localiza.  Esta magia também não pode localizar uma criatura se água corrente, com pelo menos 3 metros [10 ft.] de largura, bloquear o caminho direto entre você e ela.$$, $$SRD$$),
($$SRD_2014$$, $$locate-object-2014$$, $$Locate Object$$, $$Localizar Objeto$$, 2, $$Adivinhação$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (A forked twig.)$$, $$Concentração, até 10 minutos$$, $$Descreva ou nomeie um objeto que lhe seja familiar. Você sente a direção do local onde ele se encontra, caso esteja a, no máximo, 300 metros [1000 ft.] de distância. Se o objeto estiver se movendo, você sabe em que direção.  A magia pode localizar um objeto específico que você conheça, desde que você já o tenha visto de perto - a até 9 metros [30 ft.] - ao menos uma vez. Se preferir, a magia pode localizar um objeto de um tipo específico, como certo tipo de traje, joia, mobília, ferramenta ou arma.  Esta magia não pode localizar um objeto se qualquer espessura de chumbo, até mesmo uma folha fina, bloquear o caminho direto entre você ele.$$, $$SRD$$),
($$SRD_2014$$, $$longstrider-2014$$, $$Longstrider$$, $$Passos Largos$$, 1, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (A pinch of dirt.)$$, $$1 hora$$, $$Você toca uma criatura. O deslocamento do alvo aumenta em 3 metros até a magia terminar.   Usando Espaços de Magia de Círculo Superior.  Você pode escolher uma criatura adicional para cada círculo de espaço de magia acima de 1.$$, $$SRD$$),
($$SRD_2014$$, $$mage-armor-2014$$, $$Mage Armor$$, $$Armadura Arcana$$, 1, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (A piece of cured leather.)$$, $$8 horas$$, $$Você toca uma criatura voluntária que não está usando armadura. Até que a magia termine, a CA base do alvo se torna 13 mais o modificador de Destreza dele. A magia se encerra se o alvo vestir uma armadura.$$, $$SRD$$),
($$SRD_2014$$, $$mage-hand-2014$$, $$Mage Hand$$, $$Mãos Mágicas$$, 0, $$Conjuração$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$1 minuto$$, $$Uma mão espectral flutuante aparece em um ponto que você escolher no alcance da magia. A mão permanece pela duração. A mão desaparece se estiver a mais de 9 metros de você ou se você conjurar esta magia novamente.  Ao conjurar a magia, você pode usar a mão para manipular um objeto, abrir uma porta ou um recipiente destrancado, guardar ou recolher itens de recipientes abertos, ou despejar o conteúdo de um frasco.  Como uma ação Usar Magia em seus próximos turnos, você pode controlar a mão novamente. Como parte dessa ação, você pode mover a mão até 9 metros.  A mão não pode atacar, ativar itens mágicos ou carregar mais de 5 quilos.$$, $$SRD$$),
($$SRD_2014$$, $$magic-circle-2014$$, $$Magic Circle$$, $$Círculo Mágico$$, 3, $$Abjuração$$, $$1 minuto$$, $$3 metros$$, $$V, S, M (Holy water or powdered silver and iron worth at least 100 gp, which the spell consumes.)$$, $$1 hora$$, $$Você cria um cilindro de 3 metros de raio e 6 metros de altura [10-foot-radius, 20-foot-tall cylinder] feito de energia mágica, centrado em um ponto no solo à sua vista e no alcance da magia. Runas brilhantes aparecem onde quer que o cilindro toque, seja o solo ou outra superfície.

Escolha um ou mais dentre os seguintes tipos de criaturas: celestiais, elementais, feéricos, ínferos ou mortos-vivos. O círculo afeta criaturas do(s) tipo(s) escolhido(s) dos seguintes modos:

A criatura não pode entrar voluntariamente no cilindro por meios não-mágicos. Caso tente usar teleporte ou viagem interplanar para fazê-lo, ela precisa primeiro ser bem-sucedida em uma salvaguarda de Carisma.

A criatura tem desvantagem nas jogadas de ataque contra alvos dentro do cilindro.

Alvos dentro do cilindro não podem ser amedrontados, enfeitiçados ou possuídos pela criatura.

Ao conjurar esta magia, você pode escolher que ela funcione na direção reversa, evitando que uma criatura do tipo especificado saia do cilindro, protegendo alvos fora dele.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, a duração aumenta em 1 hora para cada círculo do espaço acima do 3º.$$, $$SRD$$),
($$SRD_2014$$, $$magic-jar-2014$$, $$Magic Jar$$, $$Receptáculo Arcano$$, 6, $$Necromancia$$, $$1 minuto$$, $$Pessoal$$, $$V, S, M (A gem, crystal, reliquary, or some other ornamental container worth at least 500 gp.)$$, $$Até ser dissipada$$, $$Seu corpo cai em estado catatônico enquanto sua alma sai dele e entra no receptáculo que você usou como componente material da magia. Enquanto sua alma habitar o receptáculo, você percebe seus arredores como se estivesse no lugar do receptáculo. Você não pode se mover ou usar reações. A única ação que você pode executar é projetar a sua alma a até 30 metros [100 ft.] do receptáculo, seja retornando para o seu corpo vivo (e encerrando a magia) ou tentando possuir um corpo humanoide.

Você pode tentar possuir qualquer criatura humanoide a até 30 metros [100 ft.] do seu alcance e que esteja à sua vista (criaturas protegidas pela magia Proteção Contra o Bem e o Mal ou Círculo Mágico não podem ser possuídas). O alvo deve fazer uma salvaguarda de Carisma. Se falhar,sua alma projeta-se do receptáculo para dentro do corpo do alvo, expulsando a alma dele, que agora ficará aprisionada no receptáculo. Em caso de sucesso, o alvo resiste aos seus esforços para possuí-lo, e você não pode tentar fazê-lo novamente por 24 horas.

Uma vez que possua o corpo de uma criatura, você o controla. Suas estatísticas de jogo são substituídas pelas da criatura, apesar de você manter seu alinhamento e seus valores de Inteligência, Sabedoria e Carisma. Você também mantém os benefícios das suas próprias características de classe. Se o alvo tiver níveis de classe, você não pode usar nenhuma das características de classe dele.

Enquanto isso, a alma da criatura possuída pode perceber os arredores, a partir do receptáculo, usando seus próprios sentidos, mas não pode se mover ou executar ações.

Enquanto estiver possuindo um corpo, você pode usar uma das suas ações para retornar do corpo do hospedeiro para o receptáculo, se este estiver a até 30 metros [100 ft.] de distância, devolvendo a alma do hospedeiro para o corpo dele. Se o corpo do hospedeiro morrer enquanto você estiver nele, a criatura morre e você deve fazer uma salvaguarda de Carisma contra a CD do seu próprio atributo de conjuração. Em caso de sucesso e o receptáculo estiver a até 30 metros [100 ft.] de distância, sua alma retorna a ele. Caso contrário, você morre.

Se o receptáculo for destruído ou a magia terminar, sua alma retorna imediatamente para seu próprio corpo. Se o seu corpo estiver a mais de 30 metros [100 ft.] de você ou se ele estiver morto quando sua alma tentar retornar para ele, você morre. Se a alma de outra criatura estiver no receptáculo quando ele for destruído, ela retorna para o próprio corpo se ele estiver vivo e a até 30 metros [100 ft.] de distância. Caso contrário, a criatura morre.

Quando a magia termina, o receptáculo é destruído.$$, $$SRD$$),
($$SRD_2014$$, $$magic-missile-2014$$, $$Magic Missile$$, $$Mísseis Mágicos$$, 1, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Instantânea$$, $$Você cria três dardos brilhantes feitos de pura energia mágica. Cada dardo acerta uma criatura à sua escolha, à sua vista e no alcance da magia. Um dardo causa 1d4 + 1 pontos de dano Energético ao alvo. Os dardos acertam ao mesmo tempo, e você pode direcioná-los para uma mesma criatura ou várias.   Usando Espaços de Magia de Círculo Superior.  A magia cria um dardo adicional para cada círculo de espaço de magia acima de 1.  [[2 + @item.level]]{Dardos Nível [[lookup @item.level]]}$$, $$SRD$$),
($$SRD_2014$$, $$magic-mouth-2014$$, $$Magic Mouth$$, $$Boca Encantada$$, 2, $$Ilusão$$, $$1 minuto$$, $$9 metros$$, $$V, S, M (A honeycomb and jade dust of at least 10 inches, the spell consumes.)$$, $$Até ser dissipada$$, $$Você implanta uma mensagem em um objeto que esteja no alcance da magia. Essa mensagem é revelada quando uma circunstância de disparo ocorrer. Escolha um objeto à sua vista e que não esteja sendo usado ou carregado por outra criatura. Fale, então, a mensagem, que deve ter 25 palavras ou menos, embora ela possa ser emitida ao longo de um período de até 10 minutos. Por fim, determine a circunstância de disparo para magia revelar a mensagem.  Quando tal circunstância ocorrer, uma boca encantada aparece no objeto e recita a mensagem com a sua voz e no mesmo volume que você falou. Se o objeto escolhido tiver uma boca ou algo que se assemelhe (por exemplo, a boca de uma estátua), a boca encantada se sobrepõe de forma a parecer que as palavras saem da boca do próprio objeto. Ao conjurar a magia, você determina se ela se encerra após entregar a mensagem ou se permanece para repetir o conteúdo sempre que a circunstância de disparo ocorrer.  A circunstância de disparo pode ser tão abrangente ou específica quanto você quiser, mas deve ser baseada em condições visuais ou auditivas que ocorram a até 9 metros [30 ft.] do objeto. Por exemplo, você pode instruir a boca a falar sempre que uma criatura se aproxime a até 9 metros [30 ft.] do objeto, ou quando um sino de prata soar a até 9 metros [30 ft.] de distância do objeto.$$, $$SRD$$),
($$SRD_2014$$, $$magic-weapon-2014$$, $$Magic Weapon$$, $$Arma Mágica$$, 2, $$Transmutação$$, $$1 ação bônus$$, $$Toque$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Você toca uma arma não-mágica. Enquanto a magia durar, essa arma se torna uma arma mágica com bônus de +1 para jogadas de ataque e dano.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o bônus aumenta para +2. Quando você usa um espaço de magia de 6º círculo ou superior, o bônus aumenta para +3.$$, $$SRD$$),
($$SRD_2014$$, $$magnificent-mansion-2014$$, $$Magnificent Mansion$$, $$Mansão Magnífica$$, 7, $$Conjuração$$, $$1 minuto$$, $$90 metros$$, $$V, S, M (A miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp.)$$, $$24 horas$$, $$Você conjura uma habitação extradimensional, no alcance da magia e que permanece enquanto esta durar. Você escolhe onde a única entrada está localizada. A entrada brilha fracamente e possui 1,5 metro [5 ft.] de largura e 3 metros [10 ft.] de altura. Você e qualquer criatura que designar ao conjurar a magia podem entrar na habitação extradimensional enquanto o portal permanecer aberto. Você pode abrir ou fechar o portal se estiver a até 9 metros [30 ft.] dele. Quando está fechado, o portal é invisível.

Além do portal, existe um magnífico saguão com numerosas câmaras além dele. O ambiente é limpo, fresco e aquecido.

Você pode criar qualquer projeto que desejar, mas o espaço não pode exceder 50 cubos, cada cubo tendo 3 metros [10 ft.] de lado. O lugar é mobiliado e decorado como você escolher. Ele contém comida o suficiente para servir um banquete de nove pratos para até 100 pessoas. Uma equipe de 100 servos semi transparentes auxiliam a todos os que entram. Você decide a aparência visual desses servos e seus trajes. Eles são completamente obedientes às suas ordens. Cada servo pode realizar qualquer tarefa que um servo humano normal poderia executar, mas não podem atacar ou executar qualquer ação que possa diretamente ferir outra criatura. Assim sendo, os servos podem buscar coisas, limpar, consertar, dobrar roupas, acender o fogo, servir comida, oferecer vinho e assim por diante. Os servos podem ir a qualquer lugar da mansão, mas não podem deixá-la. Mobiliário e outros objetos criados por esta magia dissipam-se em fumaça se forem retirados da mansão. Quando a magia termina, quaisquer criaturas dentro do espaço extradimensional são expelidas em espaços abertos o mais próximo da entrada.$$, $$SRD$$),
($$SRD_2014$$, $$major-image-2014$$, $$Major Image$$, $$Imagem Maior$$, 3, $$Ilusão$$, $$1 ação$$, $$36 metros$$, $$V, S, M (A bit of fleece.)$$, $$Concentração, até 10 minutos$$, $$Você cria a imagem de um objeto, criatura ou algum fenômeno visível que não seja maior do que um cubo de 6 metros [20-foot cube]. A imagem surge em um ponto à sua vista dentro do alcance da magia e permanece enquanto a magia durar. Ela parece ser real, incluindo sons, cheiros e temperatura apropriados à coisa retratada. Você não pode criar calor ou frio suficientes a ponto de causar dano, um som tão alto que cause dano trovejante ou que deixe uma criatura surda, ou um odor tão forte que cause enjoo (como o fedor de um troglodita).  Enquanto você estiver no alcance da ilusão, você pode usar sua ação para fazer a imagem se mover para qualquer outro local dentro do alcance da magia. À medida que a imagem muda de lugar, é possível alterar a aparência dela para que os movimentos pareçam naturais. Por exemplo, se você criar a imagem de uma criatura e movê-la, é possível alterar a imagem para que ela pareça estar andando. De forma semelhante, é possível fazer a ilusão emitir sons diferentes em momentos distintos, possibilitando inclusive que ela participe de uma conversa, por exemplo.  Interação física com a imagem revelará que se trata de uma ilusão porque coisas podem passar através dela. Uma criatura que usar sua ação para examinar a imagem, pode determinar que é uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD para evitar sua magia. Se uma criatura discernir a ilusão pelo que ela é, a criatura enxerga através da imagem e qualquer som emitido torna-se abafado para a criatura.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior, ela dura até ser dissipada, não necessitando de concentração.$$, $$SRD$$),
($$SRD_2014$$, $$mass-cure-wounds-2014$$, $$Mass Cure Wounds$$, $$Curar Ferimentos em Massa$$, 5, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Uma onda de energia curativa banha uma área a partir de um ponto à sua escolha e no alcance da magia. Escolha até seis criaturas em uma esfera com raio de 9 metros [30 ft.] e centrada neste ponto. Cada alvo recupera pontos de vida equivalente a 3d8 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou superior,, a cura aumenta em 1d8 para cada círculo do espaço acima do 5º.$$, $$SRD$$),
($$SRD_2014$$, $$mass-heal-2014$$, $$Mass Heal$$, $$Cura Completa em Massa$$, 9, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Uma onda de energia curativa flui a partir de você para todas as criaturas feridas ao seu redor. Você restaura até 700 pontos de vida, divididos como desejar entre qualquer número de criaturas à sua vista e no alcance da magia. Criaturas curadas por esta magia também são curadas de todas as doenças e quaisquer efeitos que as deixem cegas ou surdas. Esta magia não tem efeito sobre mortos-vivos ou constructos.$$, $$SRD$$),
($$SRD_2014$$, $$mass-healing-word-2014$$, $$Mass Healing Word$$, $$Palavra Curativa em Massa$$, 3, $$Evocação$$, $$1 ação bônus$$, $$18 metros$$, $$V$$, $$Instantânea$$, $$Conforme você diz palavras de restauração, até seis criaturas à sua escolha, à sua vista e no alcance da magia, recuperam uma quantidade de pontos de vida igual a 1d4 + seu modificador de atributo de conjuração. Essa magia não tem efeito sobre mortos-vivos ou constructos.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 4º círculo ou superior, a cura aumenta em 1d4 para cada círculo do espaço acima do 3º.$$, $$SRD$$),
($$SRD_2014$$, $$mass-suggestion-2014$$, $$Mass Suggestion$$, $$Sugestão em Massa$$, 6, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V, M (A snake's tongue and either a bit of honeycomb or a drop of sweet oil.)$$, $$24 horas$$, $$Você sugere um curso de ação (limitado a uma sentença ou duas) e magicamente influencia até doze criaturas à sua escolha, à sua vista e no alcance da magia, que possam ouvi-lo e compreendê-lo. Criaturas que não podem ser enfeitiçadas são imunes a este efeito. A sugestão precisa ser dita de uma forma que faça o curso de ação parecer razoável. Pedir à criatura que se esfaqueie, jogue-se contra uma lança, imole-se ou faça algum outro ato evidentemente danoso, automaticamente cancela o efeito da magia.

Cada alvo deve fazer uma salvaguarda de Sabedoria. Se falhar, ele seguirá os atos sugeridos da melhor forma, dentro das suas próprias habilidades. O curso de ação sugerido é seguido enquanto a magia durar. Se ele puder ser completado em um período menor, a magia se encerra assim que isso ocorrer.

Você também pode especificar condições que ativarão uma atividade especial enquanto a magia durar. Por exemplo, pode ser sugerido que um grupo de soldados dê todo o dinheiro em sua posse ao primeiro mendigo que encontrar. Se a condição não for realizada antes do fim dos efeitos da magia, a atividade não é concluída.

Se você ou algum de seus companheiros causar dano a uma criatura afetada por esta magia, esta se encerra.

Em Círculos Superiores.  Ao conjurar esta magia com um espaço de magia de 7º círculo, a duração será 10 dias. Usando um espaço de magia de 8º círculo, a duração será 30 dias. Ao usar um espaço de magia de 9º círculo, a duração será um ano e um dia.$$, $$SRD$$),
($$SRD_2014$$, $$maze-2014$$, $$Maze$$, $$Labirinto$$, 8, $$Conjuração$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Concentração, até 10 minutos$$, $$Você bane uma criatura à sua vista e no alcance da magia, para um semiplano labiríntico. O alvo permanece nesse lugar enquanto a magia durar ou até escapar do labirinto.

Ele pode usar uma ação para tentar escapar. Para fazê-lo, é necessário ser bem-sucedido em um teste de Inteligência com CD 20. Em caso de sucesso, ele escapa e a magia se encerra (um minotauro ou demônio goristro têm sucesso automático).

Quando esta magia termina, o alvo reaparece no espaço que estava ou, se esse espaço estiver ocupado, no espaço desocupado mais próximo.$$, $$SRD$$),
($$SRD_2014$$, $$meld-into-stone-2014$$, $$Meld Into Stone$$, $$Mesclar-se às Rochas$$, 3, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$8 horas$$, $$Você pisa em um objeto ou superfície de pedra grande o suficiente para conter o seu corpo totalmente, mesclando a si mesmo e a todo o equipamento que estiver carregando enquanto a magia durar. Usando seu movimento, você pisa na pedra, tornando sua presença totalmente invisível ou indetectável por sentidos não-mágicos.

Enquanto fundido à rocha, você não pode ver o que acontece fora dela, e quaisquer testes de Sabedoria (Percepção) que você fizer para ouvir sons do lado de fora são feitos com desvantagem. Você permanece ciente da passagem do tempo e pode conjurar magias em si mesmo enquanto mesclado à pedra. Você pode usar seu movimento para sair da pedra a qual se mesclou, encerrando a magia. Exceto isso, você não pode se mover.

Dano físico menor causado à rocha não lhe fere, mas a destruição parcial ou mudança no formato desta (de maneira que você não caiba mais dentro dela) o expele, causando 6d6 pontos de dano contundente. A completa destruição da pedra (ou transformação dela em uma substância diferente) também o expele, causando-lhe 50 pontos de dano contundente. Se expelido, você fica caído no espaço desocupado mais próximo de onde entrou na rocha.$$, $$SRD$$),
($$SRD_2014$$, $$mending-2014$$, $$Mending$$, $$Reparar$$, 0, $$Transmutação$$, $$1 minuto$$, $$Toque$$, $$V, S, M (Two lodestones.)$$, $$Instantânea$$, $$Essa magia repara uma única ruptura ou rasgo em um objeto que você tocar, como um elo de corrente quebrado, partes de uma chave partida, uma capa rasgada ou um odre furado. Se a ruptura ou rasgo não ultrapassar 30 centímetros em qualquer dimensão, ela é reparada sem deixar vestígios do dano anterior.  Essa magia pode reparar fisicamente um item mágico, mas não pode restaurar a magia de tal objeto.$$, $$SRD$$),
($$SRD_2014$$, $$message-2014$$, $$Message$$, $$Mensagem$$, 0, $$Transmutação$$, $$1 ação$$, $$36 metros$$, $$V, S, M (A short piece of copper wire.)$$, $$1 rodada$$, $$Você aponta seu dedo para uma criatura no alcance da magia e sussurra uma mensagem. O alvo (e somente ele) ouve a sua mensagem e pode responder ao sussurrar uma réplica que apenas você será capaz de ouvir.

Você pode conjurar esta magia através de objetos sólidos se for familiar com o alvo e souber que ele está atrás da barreira. Silêncio mágico, 30 centímetros [1 foot] de pedra, 3 centímetros [1 inch] de metal comum, uma folha fina de chumbo ou 90 centímetros [3 ft.] de madeira bloqueia a magia. A magia não precisa seguir uma linha reta, podendo viajar livremente ao redor de cantos ou através de aberturas.$$, $$SRD$$),
($$SRD_2014$$, $$meteor-swarm-2014$$, $$Meteor Swarm$$, $$Chuva de Meteoros$$, 9, $$Evocação$$, $$1 ação$$, $$2 km$$, $$V, S$$, $$Instantânea$$, $$Esferas em chamas, feitas de pura brasa, atingem o solo em quatro pontos diferentes à sua vista e dentro do alcance da magia. A esfera se alastra, contornando os cantos. Cada criatura em um raio de 12 metros [40 ft.], centrado em cada ponto escolhido, precisa fazer uma salvaguarda de Destreza. Se falhar, sofre 20d6 pontos de dano ígneo e 20d6 pontos de dano contundente, ou metade do dano em caso de sucesso. Uma criatura na área afetada por mais de uma esfera, sofre os efeitos de apenas uma.

A magia danifica objetos na área e inflama objetos que não estão sendo usados ou carregados.$$, $$SRD$$),
($$SRD_2014$$, $$mind-blank-2014$$, $$Mind Blank$$, $$Limpar a Mente$$, 8, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$24 horas$$, $$Enquanto a magia durar, uma criatura voluntária que você toque fica imune a dano psíquico, a qualquer efeito capaz de sentir suas emoções ou ler seus pensamentos, a magias de adivinhação e à condição enfeitiçado. A magia pode até mesmo evitar a magia Desejo e magias ou efeitos de poder semelhante usadas para afetar a mente do alvo ou para obter informação sobre ele.$$, $$SRD$$),
($$SRD_2014$$, $$minor-illusion-2014$$, $$Minor Illusion$$, $$Ilusão Menor$$, 0, $$Ilusão$$, $$1 ação$$, $$9 metros$$, $$S, M (A bit of fleece.)$$, $$1 minuto$$, $$Você cria um som ou uma imagem de um objeto no alcance da magia que permanece pela duração da magia. Veja as descrições abaixo para os efeitos de cada um. A ilusão encerra se você conjurar essa magia novamente.  Uma criatura pode perceber a ilusão ao executar a ação estudar para examinar o som ou a imagem e ser bem-sucedida em um teste de [[/check ability=int skill=inv dc=@attributes.spell.dc]] contra a CD para evitar sua magia. A ilusão se torna desbotada para uma criatura que consiga discerni-la.   Som.  Se você criar um som, o volume pode variar de um sussurro a um grito. Pode ser sua voz, a voz de outra pessoa, o rugido de um leão, o bater de tambores ou qualquer outro som que você escolher. O som continua ininterrupto pela duração da magia, ou você pode criar sons distintos em diferentes momentos antes que a magia termine.   Imagem.  Se você criar a imagem de um objeto — como uma cadeira, pegadas enlameadas ou um pequeno baú — ela não pode ter dimensões superiores a um cubo de 1,5 metro de lados. A imagem não pode gerar som, luz, cheiro ou qualquer outro efeito sensorial. A interação física com a imagem demonstra que se trata de uma ilusão, pois os objetos podem atravessá-la.$$, $$SRD$$),
($$SRD_2014$$, $$mirage-arcane-2014$$, $$Mirage Arcane$$, $$Miragem Arcana$$, 7, $$Ilusão$$, $$10 minutos$$, $$Visão$$, $$V, S$$, $$10 dias$$, $$Você faz o terreno em uma área de até 1,5 quilômetro quadrado parecer, soar, cheirar e até passar a sensação de que é outro tipo de terreno. O formato geral do terreno, entretanto, se mantém. Campos abertos ou uma estrada podem ser modificados para se parecerem com um pântano, colina, fenda ou algum outro tipo de terreno difícil ou intransponível. Uma lagoa pode ser modificada para se parecer com um prado verdejante, um precipício com um suave declive ou um barranco pedregoso com uma estrada larga e plana.

Da mesma forma, você pode alterar a aparência das estruturas ou adicioná-las onde nenhuma está presente. A magia não disfarça, oculta ou adiciona criaturas.

A ilusão inclui elementos audíveis, visuais, táteis e olfativos, de modo que pode tornar terreno limpo em terreno difícil (ou vice versa) ou, de outra forma, impedir movimento através da área. Qualquer pedaço do terreno ilusório (como uma rocha ou galho) que seja removido da área da magia desaparece imediatamente.

Criaturas com visão verdadeira podem ver através da ilusão, enxergando a forma real do terreno; porém, todos os outros elementos visuais se mantém, de modo que, mesmo ciente da presença da ilusão, ela ainda pode interagir fisicamente com seus efeitos.$$, $$SRD$$),
($$SRD_2014$$, $$mirror-image-2014$$, $$Mirror Image$$, $$Reflexos$$, 2, $$Ilusão$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$1 minuto$$, $$Três duplicatas ilusórias de você aparecem no seu espaço. Até a magia acabar, as duplicatas se movem com você e copiam as suas ações, trocando de posição, tornando impossível rastrear qual imagem é real. Você pode usar sua ação para dissipar as duplicatas ilusórias.

Cada vez que uma criatura mirar você com um ataque enquanto a magia durar, role um d20 para determinar se o ataque, em vez de você, mira uma das suas duplicatas.

Se você tiver três duplicatas, você deve rolar um 6 ou maior para mudar o alvo do ataque para uma duplicata. Com duas duplicatas, você deve rolar um 8 ou maior. Com uma duplicata, você deve rolar um 11 ou maior.

A CA de uma duplicata é igual a 10 + seu modificador de Destreza. Se um ataque atingir uma duplicata, ela é destruída. Uma duplicata só pode ser destruída por um ataque que a atinja. Ela ignora todos os outros danos e efeitos. A magia acaba quando todas as três duplicatas forem destruídas.

Uma criatura não pode ser afetada por essa magia se não puder enxergar, se ela contar com outros sentidos além da visão, como percepção às cegas, ou se ela puder perceber ilusões como falsas, como com visão verdadeira.$$, $$SRD$$),
($$SRD_2014$$, $$mislead-2014$$, $$Mislead$$, $$Despistar$$, 5, $$Ilusão$$, $$1 ação$$, $$Pessoal$$, $$S$$, $$Concentração, até 1 hora$$, $$Você se torna invisível ao mesmo tempo em que uma duplicata ilusória aparece onde você está. A duplicata permanece enquanto a magia durar, porém a invisibilidade se encerra se você atacar ou conjurar uma magia.

Você pode usar sua ação para mover sua duplicata ilusória a até o dobro do seu deslocamento e fazê-la gesticular, falar e se comportar da maneira que você escolher.

Você pode ver através dos olhos e ouvir através dos ouvidos da duplicata como se estivesse onde ela está. Em cada um de seus turnos, com uma ação bônus, você pode mudar dos sentidos dela para os seus, ou voltar para os dela. Enquanto estiver usando os sentidos de sua duplicata, você está cego e surdo em relação aos seus arredores.$$, $$SRD$$),
($$SRD_2014$$, $$misty-step-2014$$, $$Misty Step$$, $$Passo Nebuloso$$, 2, $$Conjuração$$, $$1 ação bônus$$, $$Pessoal$$, $$V$$, $$Instantânea$$, $$Brevemente cercado por uma névoa prateada, você se teleporta até 9 metros para um espaço desocupado à sua vista.$$, $$SRD$$),
($$SRD_2014$$, $$modify-memory-2014$$, $$Modify Memory$$, $$Modificar Memória$$, 5, $$Encantamento$$, $$1 ação$$, $$9 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você tenta reformular as memórias de outra criatura. Uma criatura à sua vista deve fazer uma salvaguarda de Sabedoria. Se você estiver lutando contra a criatura, ela tem vantagem na salvaguarda. Se falhar, o alvo se torna enfeitiçado por você enquanto a magia durar. Um alvo enfeitiçado está incapacitado e inconsciente dos seus arredores, apesar de ainda poder ouvir você. Se ele sofrer qualquer dano ou for alvo de outra magia, esta magia se encerra e nenhuma das memórias do alvo é modificada.

Enquanto o alvo estiver enfeitiçado, você pode afetar as memórias de um evento que ele experimentou nas últimas 24 horas e que não tenha durado mais do que 10 minutos. Você pode eliminar permanentemente todas as memórias do evento, permitir que o alvo relembre do evento com perfeita clareza de detalhes, mudar as memórias dos detalhes do evento ou criar uma memória de algum outro evento.

Você deve falar com o alvo para descrever como as memórias dele são afetadas, e ele deve ser capaz de entender seu idioma para a memória modificada se enraizar. A mente dele preenche quaisquer lacunas de detalhes da sua descrição. Se a magia se encerrar antes de você terminar de descrever a memória modificada, a memória da criatura não é alterada. Caso contrário, as memórias modificadas se instalam quando a magia se encerrar.

Uma memória modificada não necessariamente afeta a maneira como o alvo habitualmente se comporta, principalmente se a memória entrar em contradição com as inclinações naturais, alinhamento ou crenças dela. Uma memória modificada ilógica, como implantar uma memória de quanto a criatura gosta de se banhar com ácido, é descartada, talvez como se fosse um sonho ruim. O DM pode julgar uma memória modificada com sendo demasiadamente absurda para afetar o alvo de maneira significativa.

Uma magia Remover Maldição ou Restauração Maior conjurada no alvo restaura a memória original da criatura.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 6º círculo ou maior, você pode alterar as memórias do alvo de um evento que aconteceu a até 7 dias atrás (6º círculo), 30 dias atrás (7º círculo), 1 ano atrás (8º círculo), ou qualquer período no passado da criatura (9º círculo).$$, $$SRD$$),
($$SRD_2014$$, $$moonbeam-2014$$, $$Moonbeam$$, $$Raio Lunar$$, 2, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S, M (Several seeds of any moonseed plant and a piece of opalescent feldspar.)$$, $$Concentração, até 1 minuto$$, $$Um feixe pálido de luz prateada brilha em um cilindro de 1,5 metro de raio e 12 metros de altura [5-foot-radius, 40-foot-high cilinder], centrado em um ponto no alcance da magia. O cilindro é preenchido por meia-luz enquanto a magia durar.

Quando uma criatura entra pela primeira vez ou inicia o próprio turno na área da magia, ela será engolfada em chamas fantasmagóricas que causam dor lancinante, e deve fazer uma salvaguarda de Constituição. Se falhar, sofre 2d10 pontos de dano radiante, ou metade do dano em caso de sucesso.

Um metamorfo faz esta salvaguarda com desvantagem. Se falhar, ele também reverte para própria forma original, permanecendo incapaz de assumir uma forma diferente até sair da luz da magia.

Em cada um de seus turnos após conjurar esta magia, você pode usar uma ação para mover o feixe a até 18 metros [60 ft.] em qualquer direção.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$move-earth-2014$$, $$Move Earth$$, $$Mover Terra$$, 6, $$Transmutação$$, $$1 ação$$, $$36 metros$$, $$V, S, M (An iron blade and a small bag containing a mixture of soils--clay, loam, and sand.)$$, $$Concentração, até 2 horas$$, $$Escolha uma área de terreno não maior do que 12 metros [40 ft.] de lado no alcance da magia. Você pode remodelar terra, areia ou argila na área, da maneira que quiser e enquanto a magia durar. Você pode aumentar ou diminuir as elevações da área, criar ou encher um fosso, erguer ou achatar uma muralha ou formar um pilar. A extensão das alterações não pode exceder metade da maior dimensão da área. Sendo assim, caso afete um quadrado de 12 metros [40 ft.], você pode criar um pilar de até 6 metros [20 ft.] de altura, erguer ou abaixar elevações de até 6 metros [20 ft.] no quadrado, cavar um fosso de até 6 metros [20 ft.] e daí por diante. As mudanças levam 10 minutos para sejam totalmente concluídas.

Ao final de cada 10 minutos concentrado na magia, você pode escolher uma nova área de terreno para afetar.

Como a transformação no terreno ocorre lentamente, criaturas na área normalmente não ficam presas nem sofrem dano pela movimentação do solo.

Esta magia não pode manipular rocha natural ou construções de pedra. Pedras e estruturas se movimentam para se acomodar ao novo terreno. Se a maneira como você mudar o terreno causar a instabilidade de estruturas na área, elas podem colapsar.

Da mesma forma, esta magia não afeta diretamente o crescimento de plantas. A terra movida carrega as plantas junto com ela.$$, $$SRD$$),
($$SRD_2014$$, $$nondetection-2014$$, $$Nondetection$$, $$Indetectável$$, 3, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (A pinch of diamond dust worth 25 gp sprinkled over the target, which the spell consumes.)$$, $$8 horas$$, $$Enquanto a magia durar, você oculta um alvo que você toque de magias de adivinhação. O alvo pode ser uma criatura voluntária, um local ou um objeto que não ultrapasse 3 metros em qualquer dimensão. O alvo não pode ser afetado por qualquer magia de adivinhação ou percebido por sensores mágicos de vidência.$$, $$SRD$$),
($$SRD_2014$$, $$pass-without-trace-2014$$, $$Pass Without Trace$$, $$Passo sem Rastro$$, 2, $$Abjuração$$, $$1 ação$$, $$Pessoal$$, $$V, S, M (Ashes from a burned leaf of mistletoe and a sprig of spruce.)$$, $$Concentração, até 1 hora$$, $$Um véu de sombras e silêncio irradia de você, mascarando você e seus aliados contra detecção. Enquanto a magia durar, cada criatura à sua escolha no alcance de 9 metros [30 ft.] (incluindo você) tem um bônus de +10 nos testes de Destreza (Furtividade) e não pode ser rastreada a não ser por meios mágicos. Uma criatura com este bônus não deixa rastros ou outros traços de sua passagem.$$, $$SRD$$),
($$SRD_2014$$, $$passwall-2014$$, $$Passwall$$, $$Criar Passagem$$, 5, $$Transmutação$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A pinch of sesame seeds.)$$, $$1 hora$$, $$Uma passagem surge numa superfície de madeira, argamassa ou pedra (como uma parede, teto ou chão) escolhida, à sua vista, no alcance da magia e permanece enquanto esta durar. Você escolhe a dimensão da abertura: até 1,5 metro [5 ft.] de largura, 2,5 metros [8 ft.] de altura e 6 metros [20 ft.] de profundidade. A passagem não cria instabilidade na estrutura ao redor dela.

Ao desaparecer, qualquer criatura ou objeto que estiver dentro da passagem criada pela magia é expelido com segurança para um espaço desocupado na superfície na qual você conjurou a magia.$$, $$SRD$$),
($$SRD_2014$$, $$phantasmal-killer-2014$$, $$Phantasmal Killer$$, $$Assassino Fantasmagórico$$, 4, $$Ilusão$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Você se conecta aos pesadelos de uma criatura à sua vista e dentro do alcance da magia. A criatura é assolada por uma manifestação ilusória dos próprios medos mais profundos, visível apenas para ela. O alvo deve fazer uma salvaguarda de Sabedoria. Se falhar, fica amedrontado enquanto a magia durar. No final de cada turno do alvo, enquanto a magia durar, ele deve fazer uma salvaguarda de Sabedoria. Se falhar, sofre 4d10 pontos de dano psíquico; se for bem-sucedido, a magia termina.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 4º.$$, $$SRD$$),
($$SRD_2014$$, $$phantom-steed-2014$$, $$Phantom Steed$$, $$Montaria Fantasmagórica$$, 3, $$Ilusão$$, $$1 minuto$$, $$9 metros$$, $$V, S$$, $$1 hora$$, $$Uma criatura Grande, quase real, similar a um cavalo, aparece no solo, surgindo num espaço desocupado à sua escolha e no alcance da magia. Você decide a aparência da montaria, mas ela é equipada com sela, estribo e arreio. Qualquer equipamento criado pela magia desaparece em uma nuvem de fumaça se movido a mais de 3 metros [10 ft.] de distância da mesma.  Enquanto a magia durar,uma criatura à sua escolha pode fazer uso da montaria. Utilize as estatísticas de um cavalo de montaria, exceto por seu deslocamento de 30 metros [100 ft.] e por poder viajar 16 quilômetros [10 miles] em uma hora ou 20 quilômetros [13 miles] em trote rápido. Quando a magia termina, a montaria desaparece gradualmente, dando ao cavaleiro 1 minuto para desmontar. A magia se encerra se você dispensa a montaria ou se ela sofrer qualquer dano.$$, $$SRD$$),
($$SRD_2014$$, $$planar-ally-2014$$, $$Planar Ally$$, $$Aliado Extraplanar$$, 6, $$Conjuração$$, $$10 minutos$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Você suplica a uma entidade extraplanar por ajuda. Você precisa conhecer a entidade, que pode ser: uma divindade, um primordial, um príncipe demônio ou algum outro ser de poder cósmico. A entidade envia um celestial, um elemental ou um ínfero leal a ela para ajudá-lo, fazendo com que a criatura apareça em um espaço desocupado no alcance da magia. Se souber o nome de uma criatura específica, você pode dizer esse nome ao conjurar esta magia, solicitando por essa criatura em particular, embora outra criatura ainda possa ser enviada (à escolha do DM).

Ao aparecer, a criatura enviada não se encontra obrigada a comportar-se de uma forma específica. Você pode pedir para a criatura executar um serviço em troca de pagamento, mas ela não é obrigada a fazê-lo. A tarefa requisitada pode variar, desde coisas simples ("carregue-nos através do abismo" ou "lute conosco em uma batalha") até as mais complexas ("espione nossos inimigos" ou "proteja-nos durante a nossa incursão na masmorra"). Você deve ser capaz de comunicar-se com a criatura para negociar pelos serviços dela.

O pagamento é variável. Um celestial pode exigir uma doação considerável de ouro ou itens mágicos para um templo aliado, enquanto um demônio pode exigir o sacrifício de uma vida ou presentes na forma de tesouros. Algumas criaturas podem trocar o serviço delas por uma missão a ser realizada por você.

Como regra geral, uma tarefa que possa ser medida em minutos requer um pagamento estimado em 100 PO por minuto. Uma tarefa medida em horas requer 1.000 PO por hora. E uma tarefa medida em dias (até 10) requer 10.000 PO por dia. O DM pode ajustar estes pagamentos baseados nas circunstâncias sob as quais você conjura a magia. Se a tarefa estiver em concordância com o alinhamento da criatura, o pagamento pode ser reduzido pela metade ou mesmo desnecessário. Tarefas inofensivas normalmente exigem apenas metade do pagamento sugerido, enquanto tarefas especialmente perigosas podem exigir um presente maior. Criaturas raramente aceitam tarefas que pareçam suicidas.

Após concluir a tarefa ou quando a duração do serviço combinado expirar, a criatura se reportará a você - caso seja apropriado e possível em relação à tarefa -, retornando, então, para o plano de origem dela. Se você for incapaz de chegar a um acordo sobre o valor do serviço, a criatura retorna imediatamente para o plano de origem dela.

Uma criatura alistada junta-se ao seu grupo, contando como um membro e recebendo uma parte dos pontos de experiência ganhos.$$, $$SRD$$),
($$SRD_2014$$, $$planar-binding-2014$$, $$Planar Binding$$, $$Âncora Planar$$, 5, $$Abjuração$$, $$1 hora$$, $$18 metros$$, $$V, S, M (A jewel worth at least 1,000 gp, which the spell consumes.)$$, $$24 horas$$, $$Com essa magia, você tenta forçar um celestial, um elemental, um feérico ou um ínfero a servi-lo. A criatura deve estar dentro do alcance da magia durante todo o tempo de conjuração (normalmente, a criatura é convocada primeiro para o centro de um círculo mágico invertido para mantê-la presa, enquanto esta magia é conjurada). Após a conclusão da conjuração, a criatura deve fazer uma salvaguarda de Carisma. Se falhar, fica destinada a lhe servir enquanto a magia durar. Se a criatura foi convocada ou criada por outra magia, a duração daquela é estendida para coincidir com a duração desta magia.

Uma criatura ancorada deve seguir suas instruções tanto quanto possível. Você pode ordenar a criatura a acompanhá-lo em uma aventura, a vigiar um local ou a entregar uma mensagem. A criatura obedece suas instruções à risca, mas se for hostil a você, ela se esforça para distorcer suas palavras de modo a atingir os próprios objetivos. Se a criatura concluir suas instruções antes de terminado o efeito da magia, ela vai até você para relatar o fato. Se você estiver em um plano de existência diferente, ela retorna ao lugar onde você a ancorou, lá permanecendo enquanto a magia durar.

Em Círculos Superiores.  Ao conjurar esta magia usando espaço de magia de círculo superior, a duração aumenta para 10 dias com um espaço de 6º círculo, para 30 dias com um espaço de 7º círculo, para 180 dias com um espaço de 8º círculo e para um ano e um dia com um espaço de magia de 9º círculo.$$, $$SRD$$),
($$SRD_2014$$, $$plane-shift-2014$$, $$Plane Shift$$, $$Transição Planar$$, 7, $$Conjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (A forked, metal rod worth at least 250 gp, attuned to a particular plane of existence.)$$, $$Instantânea$$, $$Você e até oito criaturas voluntárias que deem as mãos em um círculo são transportadas para um plano de existência diferente. Você pode especificar um destino, em termos gerais, como a Cidade de Bronze no Plano Elemental do Fogo ou o palácio de Dispáter no segundo nível dos Nove Infernos, e você aparece dentro ou perto do destino. Se estiver tentando chegar até a Cidade de Bronze, por exemplo, você pode chegar na Rua de Aço, diante do Portão de Cinzas, ou pode ver a cidade do outro lado do Mar de Fogo, a critério do DM.  Se preferir, e conhecer a sequência de símbolos de um círculo de teleporte em outro plano de existência, esta magia pode levá-lo a este círculo. Se o círculo de teleporte for muito pequeno para conter todas as criaturas que forem transportadas, elas aparecem no local desocupado mais próximo do círculo.  Você pode usar essa magia para banir uma criatura involuntária para outro plano. Escolha uma criatura no alcance da magia e faça um ataque mágico corpo a corpo contra ela. Se acertar, a criatura deve fazer uma salvaguarda de Carisma. Se falhar, ela é transportada para um local aleatório no plano de existência que você especificar. Uma criatura transportada desta forma deve encontrar o caminho de volta para o plano de existência em que você se encontre.$$, $$SRD$$),
($$SRD_2014$$, $$plant-growth-2014$$, $$Plant Growth$$, $$Plant Growth$$, 3, $$Transmutação$$, $$1 ação$$, $$45 metros$$, $$V, S$$, $$Instantânea$$, $$Casting Time:  Action (Overgrowth) or 8 hours (Enrichment)  This spell channels vitality into plants. The casting time you use determines whether the spell has the Overgrowth or the Enrichment effect below.   Overgrowth.  Choose a point within range. All normal plants in a 100-foot-radius Sphere centered on that point become thick and overgrown. A creature moving through that area must spend 4 feet of movement for every 1 foot it moves. You can exclude one or more areas of any size within the spell's area from being affected.   Enrichment.  All plants in a half-mile radius centered on a point within range become enriched for 365 days. The plants yield twice the normal amount of food when harvested. They can benefit from only one  Plant Growth  per year.$$, $$SRD$$),
($$SRD_2014$$, $$poison-spray-2014$$, $$Poison Spray$$, $$Poison Spray$$, 0, $$Conjuração$$, $$1 ação$$, $$3 metros$$, $$V, S$$, $$Instantânea$$, $$You spray toxic mist at a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d12 Poison damage.   Aprimoramento de Truque.  The damage increases by 1d12 when you reach levels 5 (2d12), 11 (3d12), and 17 (4d12).$$, $$SRD$$),
($$SRD_2014$$, $$polymorph-2014$$, $$Polymorph$$, $$Polymorph$$, 4, $$Transmutação$$, $$1 ação$$, $$18 metros$$, $$V, S, M (A caterpillar cocoon.)$$, $$Concentração, até 1 hora$$, $$You attempt to transform a creature that you can see within range into a Beast. The target must succeed on a Wisdom saving throw or shape-shift into a Beast form for the duration. That form can be any Beast you choose that has a Challenge Rating equal to or less than the target's (or the target's level if it doesn't have a Challenge Rating). The target's game statistics are replaced by the stat block of the chosen Beast, but the target retains its alignment, personality, creature type, Hit Points, and Hit Point Dice. See appendix B for a sample of Beast stat blocks.  The target gains a number of Temporary Hit Points equal to the Hit Points of the Beast form. These Temporary Hit Points vanish if any remain when the spell ends. The spell ends early on the target if it has no Temporary Hit Points left.  The target is limited in the actions it can perform by the anatomy of its new form, and it can't speak or cast spells.  The target's gear melds into the new form. The creature can't use or otherwise benefit from any of that equipment.$$, $$SRD$$),
($$SRD_2014$$, $$power-word-kill-2014$$, $$Power Word Kill$$, $$Power Word Kill$$, 9, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V$$, $$Instantânea$$, $$You compel one creature you can see within range to die. If the target has 100 Hit Points or fewer, it dies. Otherwise, it takes 12d12 Psychic damage.$$, $$SRD$$),
($$SRD_2014$$, $$power-word-stun-2014$$, $$Power Word Stun$$, $$Power Word Stun$$, 8, $$Encantamento$$, $$1 ação$$, $$18 metros$$, $$V$$, $$Instantânea$$, $$You overwhelm the mind of one creature you can see within range. If the target has 150 Hit Points or fewer, it has the Stunned condition. Otherwise, its Speed is 0 until the start of your next turn.  The &Reference[Stunned apply=false] target makes a [[/save ability=con dc=@attributes.spell.dc]] saving throw at the end of each of its turns, ending the condition on itself on a success.$$, $$SRD$$),
($$SRD_2014$$, $$prayer-of-healing-2014$$, $$Prayer of Healing$$, $$Oração de Cura$$, 2, $$Evocação$$, $$10 minutos$$, $$9 metros$$, $$V$$, $$Instantânea$$, $$Escolha até seis criaturas à sua vista e no alcance da magia. Elas recuperam uma quantidade de pontos de vida igual a 2d8 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, a cura aumenta em 1d8 para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$prestidigitation-2014$$, $$Prestidigitation$$, $$Prestidigitação arcana$$, 0, $$Transmutação$$, $$1 ação$$, $$3 metros$$, $$V, S$$, $$1 hora$$, $$Você cria um efeito mágico dentro da distância da magia. Escolha o efeito dentre as opções abaixo. Se você conjurar esta magia várias vezes, é possível ter três de seus efeitos não instantâneos ativos ao mesmo tempo.   Efeito Sensorial.  Você cria um efeito sensorial instantâneo e inofensivo, como uma chuva de faíscas, um sopro de vento, notas musicais suaves ou um odor estranho.   Brincar com Fogo.  Você instantaneamente acende ou apaga uma vela, uma tocha ou uma pequena fogueira.   Limpo ou sujo.  Você limpa ou suja instantaneamente um objeto com menos de 30 centímetros de lado.   Sensação Menor.  Você esfria, aquece ou dá sabor a um material não vivo com menos de 30 centímetros cúbicos por 1 hora.   Marca Mágica  Você faz aparecer uma cor, uma pequena marca ou um símbolo em um objeto ou superfície por 1 hora.   Criação Menor.  Você cria uma bugiganga não mágica ou uma imagem ilusória que caiba em sua mão. Ela dura até o fim do seu próximo turno. Uma bugiganga não pode causar dano e não tem valor monetário.$$, $$SRD$$),
($$SRD_2014$$, $$prismatic-spray-2014$$, $$Prismatic Spray$$, $$Rajada Prismática$$, 7, $$Evocação$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$Instantânea$$, $$Oito raios de luz multicoloridos saem da sua mão. Cada raio possui uma cor única, com poder e propósito diferente. Cada criatura em um cone de 18 metros [60 ft.] deve fazer uma salvaguarda de Destreza. Para cada alvo, jogue 1d8 para determinar que raio a afeta.

1. Vermelho . Se falhar, o alvo sofre 10d6 pontos de dano ígneo, ou metade do dano em caso de sucesso.

2. Laranja . Se falhar, o alvo sofre 10d6 pontos de dano ácido, ou metade do dano em caso de sucesso.

3. Amarelo . Se falhar, o alvo sofre 10d6 pontos de dano elétrico, ou metade do dano em caso de sucesso.

4. Verde . Se falhar, o alvo sofre 10d6 pontos de dano venenoso, ou metade do dano em caso de sucesso.

5. Azul . Se falhar, o alvo sofre 10d6 pontos de dano gélido, ou metade do dano em caso de sucesso.

6. Índigo . Se falhar, o alvo está contido. Ele deve, então, fazer uma salvaguarda de Constituição ao final de cada um de seus turnos. Com três sucessos, a magia se encerra. Se falhar três vezes, ele é transformado permanentemente em pedra e se sujeita à condição de petrificado. Os sucessos e falhas não precisam ser consecutivos; mantenha registro de ambos até que o alvo tenha três de um tipo.

7. Violeta . Se falhar, o alvo está cego. Ela deve, então, fazer uma salvaguarda de Sabedoria no começo de seu próximo turno. Um sucesso encerra a cegueira. Se falhar, a criatura é transportada para outro plano de existência à escolha do DM e não está mais cega (normalmente, uma criatura que está em um plano que não é o seu plano natural é banida para casa, enquanto outras criaturas são geralmente lançadas nos Planos Astral ou Etéreo).

8. Especial . O alvo é atingido por dois raios. Jogue mais duas vezes, jogando novamente quaisquer 8.$$, $$SRD$$),
($$SRD_2014$$, $$prismatic-wall-2014$$, $$Prismatic Wall$$, $$Muralha Prismática$$, 9, $$Abjuração$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$10 minutos$$, $$Uma superfície cintilante e multicolorida de luz forma uma muralha vertical e opaca de até 27 metros [90 ft.] de comprimento, 9 metros [30 ft.] de altura e 2,5 centímetros [1 inch] de espessura, centrada em um ponto à sua vista, no alcance da magia. Se preferir, você pode moldar a muralha em uma esfera de até 30 metros [100 ft.] de diâmetro, centrada em um ponto à sua escolha, no alcance da magia. A muralha permanece no lugar pela duração da magia. Se você posicionar a muralha de modo que esta passe por um espaço ocupado por uma criatura, a magia falha, e sua ação e o espaço de magia são perdidos.

A muralha emite luz plena por 30 metros [100 ft.] e meia-luz por mais 30 metros [100 ft.]. Você e as criaturas designadas no momento da conjuração podem passar pela muralha e ficar próximas a esta, sem sofrer dano. Se outra criatura que pode ver a muralha se mover a até 6 metros [20 ft.] dela ou começar o turno lá, precisa ser bem-sucedida em uma salvaguarda de Constituição ou fica cega durante 1 minuto.

A muralha tem sete camadas, cada uma de uma cor diferente. Quando uma criatura tenta tocá-la ou passar por ela, o fará uma camada por vez. À cada camada (cor), a criatura precisa fazer uma salvaguarda de Destreza ou será afetada pelas propriedades daquela camada, conforme descrito adiante.

A muralha pode ser destruída, uma camada por vez, na ordem do vermelho para o violeta e de um modo específico para cada uma das camadas. Uma vez que uma camada é destruída, permanece desse modo pela duração da magia. Campo Antimagia não tem efeito sobre a muralha, e Dissipar Magia afeta apenas a camada violeta.

1. Vermelho . Se falhar, a criatura sofre 10d6 pontos de dano ígneo, ou metade do dano em caso de sucesso. Enquanto esta camada estiver ativa, ataques à distância não-mágicos não podem atravessar a muralha. Esta camada é destruída caso sofra ao menos 25 pontos de dano gélido.

2. Laranja . Se falhar, a criatura sofre 10d6 pontos de dano ácido, ou metade do dano em caso de sucesso. Enquanto esta camada estiver ativa, ataques mágicos à distância não podem atravessar a muralha. Esta camada pode ser destruída por um vento forte.

3. Amarelo . Se falhar, a criatura sofre 10d6 pontos de dano elétrico, ou metade do dano em caso de sucesso. Esta camada é destruída caso sofra ao menos 60 pontos de dano energético.

4. Verde . Se falhar, a criatura sofre 10d6 pontos de dano venenoso, ou metade do dano em caso de sucesso. Uma magia Criar Passagem ou outra magia de mesmo círculo ou superior que puder abrir uma porta em uma superfície sólida, destrói esta camada.

5. Azul . Se falhar, a criatura sofre 10d6 pontos de dano gélido, ou metade do dano em caso de sucesso. Esta camada é destruída caso sofra ao menos 25 pontos de dano ígneo.

6. Anil . Se falhar, a criatura é contida. Ela deve, então, fazer uma salvaguarda de Constituição ao final de cada um dos próprios turnos. Se falhar três vezes, a criatura é transformada permanentemente em pedra e está sujeita à condição de petrificada. Se obter três sucessos, a magia se encerra. Os sucessos e falhas não precisam ser consecutivos; mantenha a contagem de ambos até que a criatura tenha três de um tipo.

Enquanto esta camada estiver ativa, magias não podem atravessar a muralha. Esta camada é destruída por luz plena emanada pela magia Luz do Dia ou uma magia similar do mesmo círculo ou superior.

7. Violeta . Se falhar, a criatura fica cega. Ela deve, então, fazer uma salvaguarda de Sabedoria no começo de seu próximo turno. Um sucesso encerra a cegueira. Se falhar, a criatura é transportada para outro plano à escolha do DM e não está mais cega (tipicamente, uma criatura que está em um plano que não é o de origem dela, é banida de volta, enquanto outras criaturas são normalmente lançadas nos Planos Astral ou Etéreo). Esta camada é destruída por Dissipar Magia ou magia semelhante de mesmo círculo ou superior, que seja capaz de encerrar magias ou efeitos mágicos.$$, $$SRD$$),
($$SRD_2014$$, $$private-sanctum-2014$$, $$Private Sanctum$$, $$Santuário Particular$$, 4, $$Abjuração$$, $$10 minutos$$, $$36 metros$$, $$V, S, M (A thin sheet of lead, a piece of opaque glass, a wad of cotton or cloth, and powdered chrysolite.)$$, $$24 horas$$, $$Você transforma uma área no alcance da magia em um local magicamente seguro. Pode ser um cubo de lado tão pequeno quanto 1,5 metro [5 ft.] ou tão grande quanto 30 metros [100 ft.]. A magia permanece pela duração ou até que você a encerre com uma ação.

Ao conjurar a magia, você decide qual tipo de segurança ela fornece, escolhendo quantas desejar entre as seguintes propriedades:

Sons não podem atravessar a barreira na borda da área protegida.

A borda tem aparência escura e opaca, impedindo a visão (incluindo visão no escuro) através dela.

Sensores criados por adivinhação não podem surgir dentro da área protegida, ou passar pelo perímetro.

Criaturas na área não podem ser alvos de magias de adivinhação.

Nada pode se teleportar para dentro da área protegida.

Viagem planar é bloqueada no interior do local.

Conjurar esta magia no mesmo lugar todo dia por um ano torna o seu efeito permanente.

Em Círculos Superiores . Ao conjurar esta magia usando um espaço de magia de 5º círculo ou superior, você pode aumentar o tamanho do cubo em 30 metros [100 ft.] para cada círculo do espaço acima do 4º. Então, você poderia proteger um cubo que não tenha mais que 60 metros [200 ft.] em um dos lados, usando um espaço de magia de 5º círculo.$$, $$SRD$$),
($$SRD_2014$$, $$produce-flame-2014$$, $$Produce Flame$$, $$Criar Chamas$$, 0, $$Conjuração$$, $$1 ação$$, $$Pessoal$$, $$V, S$$, $$10 minutos$$, $$Uma chama bruxuleante surge em sua mão e permanece lá pela duração da magia. Enquanto estiver lá, a chama não emite calor, não queima nada, e emite Luz Plena em um raio de 6 metros e Meia-luz por mais 6 metros. A magia se encerra se você a conjurar novamente.  Até que a magia termine, você pode executar uma ação Usar Magia para arremessar a chama em uma criatura ou objeto a até 18 metros de você. Realize um ataque mágico à distância. Em caso de acerto, o alvo sofre 1d8 pontos de dano Ígneo.   Aprimoramento de Truque.  O dano aumenta em 1d8 quando você atinge os níveis 5 (2d8), 11 (3d8) e 17 (4d8).$$, $$SRD$$),
($$SRD_2014$$, $$programmed-illusion-2014$$, $$Programmed Illusion$$, $$Ilusão Programada$$, 6, $$Ilusão$$, $$1 ação$$, $$36 metros$$, $$V, S, M (A bit of fleece and jade dust worth at least 25 gp.)$$, $$Até ser dissipada$$, $$Você cria a ilusão de um objeto, criatura ou outro fenômeno visível no alcance da magia e que é ativado quando uma condição específica ocorre. O efeito ilusório é imperceptível até ser ativado. A ilusão não pode ser maior do que um cubo de 9 metros [30 ft.]. Ao conjurar essa magia você decide como a ilusão se comporta e que sons ela faz. A encenação programada pode durar até 5 minutos.

Quando a condição que você especificou ocorrer, a ilusão surge e age da maneira que você descreveu. Uma vez terminada a encenação, a ilusão desaparece e permanece dormente por 10 minutos. Após esse tempo, a ilusão pode ser ativada novamente.

A condição de ativação pode ser tão específica ou genérica quanto você desejar, no entanto deve basear-se em condições visuais ou sonoras que ocorram a até 9 metros [30 ft.] da área. Por exemplo, você poderia criar uma ilusão de si mesmo para avisar outros que tentem abrir uma porta com armadilha ou poderia programar a ilusão para ser ativada apenas quando uma criatura disser uma determinada palavra ou frase.

Interação física com a imagem revela que se trata de uma ilusão, pois coisas podem passar através dela. Uma criatura que gaste uma ação para examinar a imagem, pode perceber o caráter ilusório desta com um teste bem-sucedido de Inteligência (Investigação) contra a CD para evitar sua magia. Se uma criatura discernir a ilusão pelo que ela é, a criatura pode ver através da imagem, e qualquer som que a ilusão faça se torna abafado para a criatura.$$, $$SRD$$),
($$SRD_2014$$, $$project-image-2014$$, $$Project Image$$, $$Projetar Imagem$$, 7, $$Ilusão$$, $$1 ação$$, $$750 km$$, $$V, S, M (A small replica of you made from materials worth at least 5 gp.)$$, $$Concentração, até 24 horas$$, $$Você cria uma cópia ilusória de si mesmo, que permanece enquanto a magia durar. A cópia pode aparecer em qualquer local que você já tenha visto dentro do alcance da magia, independentemente da interposição de obstáculos. A ilusão se parece e soa como você, mas é intangível. Se a ilusão sofrer qualquer dano, ela desaparece e a magia se encerra.

Você pode usar uma ação para mover a ilusão a até duas vezes o seu deslocamento e fazê-la gesticular, falar e se comportar da maneira que você escolher. Ela imita seus maneirismos perfeitamente.

Você pode ver através dos olhos e ouvir através dos ouvidos de sua cópia como se estivesse no espaço ocupado por ela. No seu turno, com uma ação bônus, você pode parar de usar os sentidos da cópia para usar os seus, ou voltar para os dela novamente. Enquanto estiver usando os sentidos de sua cópia, você estará cego e surdo em relação aos seus arredores.

Interação física com a cópia revela que ela é uma ilusão, pois coisas podem passar através dela. Se uma criatura usar uma ação para examinar a imagem, ela pode determinar que se trata de uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD para evitar sua magia. Se a criatura discernir a ilusão pelo que realmente é, poderá ver através da imagem, e qualquer som que a ilusão faça se torna abafado para a criatura.$$, $$SRD$$),
($$SRD_2014$$, $$protection-from-energy-2014$$, $$Protection From Energy$$, $$Proteção Contra Energia$$, 3, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Concentração, até 1 hora$$, $$Você toca uma criatura voluntária. Enquanto a magia durar, o alvo passa a ter resistência a um tipo de dano à sua escolha: ácido, elétrico, ígneo, gélido ou trovejante.$$, $$SRD$$),
($$SRD_2014$$, $$protection-from-evil-and-good-2014$$, $$Protection from Evil and Good$$, $$Proteção Contra o Bem e o Mal$$, 1, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (Holy water or powdered silver and iron, which the spell consumes.)$$, $$Concentração, até 10 minutos$$, $$Enquanto a magia durar, uma criatura voluntária tocada por você passa a ter proteção contra certos tipos de criaturas: aberrações, celestiais, elementais, feéricos, ínferos e mortos-vivos.

A proteção concede vários benefícios. Criaturas destes tipos têm desvantagem nas jogadas de ataque contra o alvo. O alvo não pode ser amedrontado, enfeitiçado ou possuído por elas. Se o alvo já estiver amedrontado, enfeitiçado ou possuído por estas criaturas, ele terá vantagem sobre qualquer nova salvaguarda contra o efeito relevante.$$, $$SRD$$),
($$SRD_2014$$, $$protection-from-poison-2014$$, $$Protection from Poison$$, $$Proteção Contra Veneno$$, 2, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$1 hora$$, $$Você toca uma criatura. Se ela estiver envenenada, você neutraliza o veneno. Se mais de um veneno afligir o alvo, você neutraliza o veneno que sabe estar presente, ou neutraliza um deles, ao acaso.

Enquanto a magia durar, o alvo tem vantagem nas salvaguardas contra ser envenenado, e resistência a dano venenoso.$$, $$SRD$$),
($$SRD_2014$$, $$purify-food-and-drink-2014$$, $$Purify Food and Drink$$, $$Purificar Alimentos e Bebidas$$, 1, $$Transmutação$$, $$1 ação$$, $$3 metros$$, $$V, S$$, $$Instantânea$$, $$Toda a comida e bebida não-mágica dentro de uma esfera de 1,5 metro de raio [5-foot radius] centrada em um ponto à sua escolha, no alcance da magia, é purificada e tornada livre de venenos e doenças.$$, $$SRD$$),
($$SRD_2014$$, $$raise-dead-2014$$, $$Raise Dead$$, $$Reviver os Mortos$$, 5, $$Necromancia$$, $$1 hora$$, $$Toque$$, $$V, S, M (A diamond worth at least 500gp, which the spell consumes.)$$, $$Instantânea$$, $$Uma criatura que você toca retorna dos mortos, desde que não tenha falecido há mais de 10 dias. Se a alma dela estiver disposta e livre para retornar ao corpo, ela retorna à vida com 1 ponto de vida.  A magia também neutraliza quaisquer venenos e cura doenças não-mágicas que a afetavam no momento em que morreu. Entretanto, a magia não remove doenças mágicas ou efeitos semelhantes; se eles não forem cancelados antes da conjuração, voltam a ter efeito assim que a criatura voltar a viver. Esta magia não retorna um morto-vivo à vida.  Todas as lesões mortais são fechadas, mas partes perdidas do corpo não são restauradas. Se o cadáver tiver partes ou órgãos vitais do corpo faltando - como a cabeça, por exemplo, a magia falha automaticamente.  Voltar à vida após a morte é uma provação. O alvo sofre -4 de penalidade em todas as jogadas de ataque, salvaguardas e testes de atributo. Toda vez que o alvo completa um descanso longo, a penalidade é reduzida em 1, até desaparecer.$$, $$SRD$$),
($$SRD_2014$$, $$ray-of-enfeeblement-2014$$, $$Ray of Enfeeblement$$, $$Raio do Enfraquecimento$$, 2, $$Necromancia$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Concentração, até 1 minuto$$, $$Um feixe negro de energia debilitante brota do seu dedo em direção a uma criatura no alcance da magia. Faça um ataque mágico à distância contra o alvo. Se acertar, enquanto a magia durar, o alvo passa a causar apenas metade do dano em ataques armados que usem Força.  No final de cada um dos próprios turnos, o alvo pode fazer uma salvaguarda de Constituição contra a magia. Em caso de sucesso, a magia se encerra.$$, $$SRD$$),
($$SRD_2014$$, $$ray-of-frost-2014$$, $$Ray of Frost$$, $$Raio de Gelo$$, 0, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Um feixe congelante de luz azul-esbranquiçada parte em direção a uma criatura no alcance da magia. Realize um ataque mágico à distância contra o alvo. Se acertar, a criatura sofre 1d8 pontos de dano Gélido e seu Deslocamento é reduzido em 3 metros até o início do seu próximo turno.   Aprimoramento de Truque.  O dano aumenta em 1d8 quando você atinge os níveis 5 (2d8), 11 (3d8) e 17 (4d8).$$, $$SRD$$),
($$SRD_2014$$, $$regenerate-2014$$, $$Regenerate$$, $$Regeneração$$, 7, $$Transmutação$$, $$1 minuto$$, $$Toque$$, $$V, S, M (A prayer wheel and holy water.)$$, $$1 hora$$, $$Você toca uma criatura e estimula sua capacidade natural de cura. O alvo recupera 4d8+15 pontos de vida. Enquanto a magia durar, o alvo recupera 1 ponto de vida no começo de cada turno dele (10 pontos de vida por minuto).

Membros amputados do corpo do alvo (dedos, pernas, cauda e assim por diante), se houver, são restaurados após 2 minutos. Se a parte amputada do corpo for colocada no lugar, a magia instantaneamente faz com que o membro se reconecte.$$, $$SRD$$),
($$SRD_2014$$, $$reincarnate-2014$$, $$Reincarnate$$, $$Reencarnar$$, 5, $$Transmutação$$, $$1 hora$$, $$Toque$$, $$V, S, M (Rare oils and unguents worth at least 1,000 gp, which the spell consumes.)$$, $$Instantânea$$, $$Você toca um humanoide morto ou um pedaço de um humanoide morto. Contanto que a criatura não esteja morta há mais de 10 dias, a magia forma um novo corpo adulto para ela e convoca sua alma a entrar no corpo. Se a alma da criatura não estiver livre ou disposta para tal, a magia falha.  A magia molda um novo corpo para a criatura habitar, o que pode causar uma mudança de raça da criatura. O DM joga na tabela Reencarnar para determinar que forma a criatura assume quando restaurada à vida, ou o DM escolhe uma forma.

A criatura reencarnada recorda sua vida e experiências anteriores. Ela mantém as capacidades que tinha em sua forma original, exceto pela mudança de sua raça original para a nova e dos seus traços raciais, obviamente.$$, $$SRD$$),
($$SRD_2014$$, $$remove-curse-2014$$, $$Remove Curse$$, $$Remover Maldição$$, 3, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S$$, $$Instantânea$$, $$Ao tocar uma criatura ou objeto, todas as maldições lançadas sobre eles se encerram. Se o objeto for um item mágico amaldiçoado, a maldição se mantém, mas a magia quebra a sintonia do dono com o objeto, de modo que ele pode ser removido ou descartado.$$, $$SRD$$),
($$SRD_2014$$, $$resilient-sphere-2014$$, $$Resilient Sphere$$, $$Esfera Resiliente$$, 4, $$Evocação$$, $$1 ação$$, $$9 metros$$, $$V, S, M (A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.)$$, $$Concentração, até 1 minuto$$, $$Uma esfera de energia cintilante envolve uma criatura ou objeto de tamanho Grande ou menor, no alcance da magia. Uma criatura que estiver na esfera contra a própria vontade deve fazer uma salvaguarda de Destreza. Se falhar, a criatura fica enclausurada enquanto a magia durar.

Nada - nem objetos físicos, energia ou outros efeitos mágicos - pode passar através da barreira, para dentro ou fora, apesar de uma criatura na esfera poder respirar nela. A esfera é imune a todos os danos e qualquer criatura ou objeto dentro dela não pode sofrer dano por ataques ou efeitos provenientes do exterior, tampouco pode causar dano à qualquer coisa do lado de fora.

A esfera não possui peso e é grande o suficiente para conter apenas a criatura ou objeto dentro dela. Uma criatura enclausurada pode usar sua ação, empurrando-se contra a parede da esfera e, assim, rolando-a por até metade do deslocamento da criatura. Da mesma forma, o globo pode ser apanhado e movido por outras criaturas.

Uma magia Desintegrar tendo como alvo o globo, o destrói sem causar dano a qualquer coisa dentro dele.$$, $$SRD$$),
($$SRD_2014$$, $$resistance-2014$$, $$Resistance$$, $$Resistência$$, 0, $$Abjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (A miniature cloak.)$$, $$Concentração, até 1 minuto$$, $$Você toca uma criatura voluntária e escolhe um tipo de dano: ácido, contundente, cortante, elétrico, gélido, ígneo, necrótico, perfurante, radiante, trovejante ou venenoso. Quando a criatura sofre dano do tipo escolhido antes que a magia termine, a criatura reduz o dano total sofrido em 1d4 pontos. Uma criatura pode se beneficiar desta magia apenas uma vez por turno.$$, $$SRD$$),
($$SRD_2014$$, $$resurrection-2014$$, $$Resurrection$$, $$Ressurreição$$, 7, $$Necromancia$$, $$1 hora$$, $$Toque$$, $$V, S, M (A diamond worth at least 1,000gp, which the spell consumes.)$$, $$Instantânea$$, $$Você toca uma criatura, morta há não mais de um século, que não tenha morrido de causas naturais e que não seja um morto-vivo. Se a alma dela estiver livre e disposta, a criatura retorna à vida com todos os pontos de vida.  A magia neutraliza quaisquer venenos e cura doenças normais que afligiam a criatura quando morreu. Entretanto, ela não remove maldições, doenças mágicas ou coisas do gênero; se esses efeitos não forem removidos antes da conjuração da magia, eles voltam a afligir o alvo após o seu retomo à vida.  A magia fecha todas as lesões fatais e restaura quaisquer partes corpóreas perdidas.  Voltar à vida após a morte é uma provação. O alvo sofre -4 de penalidade em todas as jogadas de ataque, salvaguardas e testes de atributo. Toda vez que o alvo completa um descanso longo, a penalidade é reduzida em 1, até desaparecer completamente.  Conjurar esta magia para restaurar vida a um indivíduo que esteja morto por um ano ou mais é algo extenuante para o conjurador. Até terminar um descanso longo, é impossível conjurar magias novamente e também todas as jogadas de ataque, testes de atributo e salvaguardas possuem desvantagem.$$, $$SRD$$),
($$SRD_2014$$, $$reverse-gravity-2014$$, $$Reverse Gravity$$, $$Inverter a Gravidade$$, 7, $$Transmutação$$, $$1 ação$$, $$30 metros$$, $$V, S, M (A lodestone and iron filings.)$$, $$Concentração, até 1 minuto$$, $$Esta magia inverte a gravidade numa área de 15 metros de raio e 30 metros de altura, formando um cilindro [50-foot-radius, 100-foot high cylinder] centrado em um ponto no alcance da magia. Todas as criaturas e objetos que não estão, de alguma forma, ancorados ao solo nessa área, "caem" para cima e alcançam o topo da área quando a magia é conjurada. Uma criatura pode fazer uma salvaguarda de Destreza para se agarrar a um objeto fixo que possa alcançar, evitando a queda.

Se algum objeto sólido (como um teto) for encontrado durante esta queda, criaturas e objetos caindo se chocam contra ele, como fariam durante uma queda normal para baixo. Se um objeto ou criatura atingir o topo da área sem bater em nada, ele permanece lá, oscilando ligeiramente, enquanto a magia durar.

Ao final da duração, objetos e criaturas afetados caem de volta para baixo.$$, $$SRD$$),
($$SRD_2014$$, $$revivify-2014$$, $$Revivify$$, $$Revivificar$$, 3, $$Conjuração$$, $$1 ação$$, $$Toque$$, $$V, S, M (Diamonds worth 300gp, which the spell consumes.)$$, $$Instantânea$$, $$Você toca uma criatura que faleceu há menos de um minuto. Aquela criatura volta à vida com 1 ponto de vida. A magia não pode retornar quem morreu de idade avançada, nem pode restaurar quaisquer partes perdidas do corpo.$$, $$SRD$$),
($$SRD_2014$$, $$rope-trick-2014$$, $$Rope Trick$$, $$Corda Extradimensional$$, 2, $$Transmutação$$, $$1 ação$$, $$Toque$$, $$V, S, M (Powdered corn extract and a twisted loop of parchment.)$$, $$1 hora$$, $$Você toca um pedaço de corda de até 18 metros [60 ft.] de comprimento. Uma extremidade da corda, em seguida, sobe para o ar, até ficar perpendicular ao solo. Na extremidade superior da corda, uma entrada invisível se abre para um espaço extradimensional enquanto a magia durar.  O espaço extradimensional pode ser alcançado escalando-se a corda até o topo. O espaço pode conter até oito criaturas de tamanho Médio ou menores. A corda pode ser puxada para o espaço, fazendo com que desapareça de vista para quem está de fora do espaço.  Ataques e magias não podem atravessar a entrada, seja para dentro ou para fora do espaço extradimensional, mas quem está dentro pode ver do lado de fora, como se olhasse através de uma janela de 1,00 x 1,50 metro [3-foot-by-5-foot], tendo a corda como centro.  Qualquer coisa dentro do espaço extradimensional cai quando a magia termina.$$, $$SRD$$),
($$SRD_2014$$, $$sacred-flame-2014$$, $$Sacred Flame$$, $$Chama Sagrada$$, 0, $$Evocação$$, $$1 ação$$, $$18 metros$$, $$V, S$$, $$Instantânea$$, $$Uma irradiação semelhante a uma chama irrompe em uma criatura que você possa ver dentro da distância da magia. O alvo deve ser bem sucedido em uma salvaguarda de Destreza. Se falhar, sofre 1d8 pontos de dano Radiante. O alvo não recebe nenhum benefício de Cobertura Parcial ou Cobertura de Três Quartos para esta salvaguarda.   Aprimoramento de Truque.  O dano aumenta em 1d8 quando você atinge os níveis 5 (2d8), 11 (3d8) e 17 (4d8).$$, $$SRD$$),
($$SRD_2014$$, $$sanctuary-2014$$, $$Sanctuary$$, $$Santuário$$, 1, $$Abjuração$$, $$1 ação bônus$$, $$9 metros$$, $$V, S, M (A small silver mirror.)$$, $$1 minuto$$, $$Você protege uma criatura que esteja dentro do alcance da magia contra ataques. Enquanto a magia durar, qualquer criatura que tenha a criatura protegida como alvo de um ataque ou de uma magia prejudicial deve antes fazer uma salvaguarda de Sabedoria. Se falhar, o atacante deve escolher outro alvo ou perderá o ataque ou magia. Esta magia não garante ao alvo proteção contra efeitos de área, como a explosão de uma bola de fogo.

Se o alvo protegido fizer um ataque ou conjurar uma magia que afete uma criatura inimiga, a magia se encerra.$$, $$SRD$$),
($$SRD_2014$$, $$scorching-ray-2014$$, $$Scorching Ray$$, $$Raio Ardente$$, 2, $$Evocação$$, $$1 ação$$, $$36 metros$$, $$V, S$$, $$Instantânea$$, $$Você cria três raios de fogo e os dispara em alvos que estejam no alcance da magia. Você pode dispará-los contra um alvo ou vários.

Faça um ataque mágico à distância para cada raio. Se acertar, o alvo sofre 2d6 pontos de dano ígneo.

Em Círculos Superiores.  Ao conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você cria um raio adicional para cada círculo do espaço acima do 2º.$$, $$SRD$$),
($$SRD_2014$$, $$scrying-2014$$, $$Scrying$$, $$Vidência$$, 5, $$Adivinhação$$, $$10 minutos$$, $$Pessoal$$, $$V, S, M (A focus worth at least 1,000 gp, such as a crystal ball, a silver mirror, or a font filled with holy water.)$$, $$Concentração, até 10 minutos$$, $$Você pode ver e escutar uma determinada criatura à sua escolha que esteja no mesmo plano de existência. O alvo deve fazer uma salvaguarda de Sabedoria, modificada por quão bem você o conhece e pelo tipo de conexão física com ele. Se um alvo souber que você está conjurando esta magia, ele pode abrir mão da salvaguarda voluntariamente se ele quiser ser observado.

Conhecimento

Modificador de Salvaguarda

Segunda mão (ouviu falar do alvo)

+5

Primeira mão (você conhece o alvo)

+0

Familiar (você conhece bem o alvo)

-5

Conexão

Modificador de Salvaguarda

Semelhança ou imagem

-2

